const K8S_ISOLATION_RETRY_ATTEMPT_CONTEXT_KEY = "paperclipK8sIsolationRetryAttempt";
const K8S_ISOLATION_RETRY_AT_CONTEXT_KEY = "paperclipK8sIsolationRetryAt";
const K8S_ISOLATION_RETRY_BASE_DELAY_MS = 15_000;
const K8S_ISOLATION_RETRY_MAX_DELAY_MS = 5 * 60_000;
// Rate-limit retries (errorFamily = "rate_limit_exhausted") use a flat short
// delay instead of stacking exponential backoff. Rationale: rate-limit isn't
// a transient upstream fault — it means "this account's window is closed".
// The right wait time is the soonest pool reset, not 2hrs of guesswork.
// The ccrotate gate (PR #87) at dispatch time is the actual decider:
//   - if pool has capacity now: gate allows, run proceeds on a fresh account
//   - if pool still empty:      gate denies + skips, next timer tick retries
// Stacking exponential backoff (2m → 10m → 30m → 2h) repeatedly delayed
// retries for hours past the actual reset, leaving issues "in_progress" with
// no activity. (Observed BLO-3182 2026-05-06: 5 rate-limit failures stacked
// scheduledRetryAttempt to 4, retry pushed to T+95min after the last
// failure, even though pool reset was much sooner.)
export const RATE_LIMIT_HEARTBEAT_RETRY_DELAY_MS = 90 * 1000;
const RATE_LIMIT_HEARTBEAT_RETRY_JITTER_RATIO = 0.25;
// Cap rate-limit retry chains so a stuck pool can't queue indefinitely. The
// gate skips dispatches when pool is empty; we only count retries that
// actually ran (and re-failed). Practical ceiling: 12 = ~18min of accumulated
// post-gate retries before we give up and require operator intervention.
const RATE_LIMIT_HEARTBEAT_RETRY_MAX_ATTEMPTS = 12;
// Fallback delay for a ccrotate capacity defer when the gate can't derive a
// `resumeAt` (e.g. no future reset epoch in the tier cache). Without this the
// scheduled-retry row would carry a null `scheduledRetryAt` and never be
// claimed by the `scheduledRetryAt <= now` sweep — silently stranded. A short
// poll interval lets the sweep re-check capacity soon. PEN-382.
export const CCROTATE_CAPACITY_DEFAULT_RETRY_DELAY_MS = 5 * 60 * 1000;
export const CCROTATE_CAPACITY_RETRY_REASON = "ccrotate_capacity";

/**
 * Context-snapshot key holding how many GitHub review-request *deliveries* a
 * single `scheduled_retry` run will settle (BLO-18859 review follow-up).
 *
 * A capacity deferral counts `deferred` once per delivery, but same-task-key
 * deliveries coalesce onto one run — so without this tally the promoter's
 * single `queued` would leave N-1 deliveries permanently stranded between
 * `received` and `queued`, which is exactly the shape real loss has.
 */
export const GITHUB_REVIEW_DELIVERY_COUNT_KEY = "githubReviewDeliveryCount";

/**
 * Upper bound applied when replaying {@link GITHUB_REVIEW_DELIVERY_COUNT_KEY}
 * into counter increments. The value is derived from committed rows, so a
 * corrupt or hand-edited snapshot must not be able to spin the promoter.
 */
const GITHUB_REVIEW_DELIVERY_COUNT_MAX = 1000;

/**
 * Read a coalesced-delivery tally off a run snapshot, clamped to
 * `[1, GITHUB_REVIEW_DELIVERY_COUNT_MAX]`. Absent/garbage means "one delivery",
 * which is what every run written before this key existed represents.
 */
export function readGithubReviewDeliveryCount(snapshot: Record<string, unknown>): number {
  const raw = snapshot[GITHUB_REVIEW_DELIVERY_COUNT_KEY];
  const parsed = typeof raw === "number" ? raw : Number.parseInt(String(raw ?? ""), 10);
  if (!Number.isFinite(parsed) || parsed < 1) return 1;
  return Math.min(Math.floor(parsed), GITHUB_REVIEW_DELIVERY_COUNT_MAX);
}

function readIntegerEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw == null || raw.trim() === "") return fallback;
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function strictGitCheckoutProbeTimeoutMs(): number {
  return Math.max(
    100,
    readIntegerEnv(
      "PAPERCLIP_STRICT_GIT_CHECKOUT_PROBE_TIMEOUT_MS",
      STRICT_GIT_CHECKOUT_PROBE_TIMEOUT_DEFAULT_MS,
    ),
  );
}

const K8S_CCROTATE_IN_RUN_RETRY_MAX_ATTEMPTS = Math.max(
  0,
  readIntegerEnv("PAPERCLIP_K8S_CCROTATE_IN_RUN_RETRY_MAX_ATTEMPTS", 6),
);
const K8S_CCROTATE_IN_RUN_RETRY_DEFAULT_DELAY_MS = Math.max(
  1_000,
  readIntegerEnv("PAPERCLIP_K8S_CCROTATE_IN_RUN_RETRY_DEFAULT_DELAY_MS", 90_000),
);
const K8S_CCROTATE_IN_RUN_RETRY_MAX_DELAY_MS = Math.max(
  1_000,
  readIntegerEnv("PAPERCLIP_K8S_CCROTATE_IN_RUN_RETRY_MAX_DELAY_MS", 600_000),
);
// Backstop so a pool that never recovers eventually stops re-deferring and
// surfaces for operator attention instead of looping forever. PEN-382.
export const CCROTATE_CAPACITY_MAX_RETRY_ATTEMPTS = 24;
// When adapter resolution momentarily falls back to the no-op `process`
// adapter for a non-process agent type (e.g. claude_k8s briefly unresolved),
// we treat it as a transient miss and schedule a quick bounded retry instead
// of hard-failing the agent.
export const ADAPTER_RESOLUTION_RETRY_DELAY_MS = 30 * 1000;
// Capacity-class (k8s_concurrent_run_blocked) retries for pr_review wakes.
// Flat short delay (same 90s base as rate-limit), storm-survivable cap higher
// than the rate-limit 12 so a multi-hour concurrency storm doesn't silently
// drop the review. Only pr_review wakes are re-queued; non-PR wakes remain
// terminal (BLO-7913 non-PR leak guard preserved).
const CAPACITY_BLOCKED_HEARTBEAT_RETRY_REASON = "capacity_blocked";
const CAPACITY_BLOCKED_HEARTBEAT_RETRY_WAKE_REASON = "capacity_blocked_retry";
export const CAPACITY_BLOCKED_HEARTBEAT_RETRY_DELAY_MS = 90 * 1000;
export const CAPACITY_BLOCKED_HEARTBEAT_RETRY_MAX_ATTEMPTS = 20;
export const JOB_FAILED_HEARTBEAT_RETRY_REASON = "job_failed";
export const JOB_FAILED_HEARTBEAT_RETRY_WAKE_REASON = "job_failed_retry";
export const JOB_FAILED_HEARTBEAT_RETRY_MAX_ATTEMPTS = 4;
export const DEP_BLOCKED_RETRY_REASON = "dependency_blocked";
export const DEP_BLOCKED_BASE_DELAY_MS = 5 * 60 * 1000;
export const DEP_BLOCKED_MAX_DELAY_MS = 60 * 60 * 1000;
export const DEP_BLOCKED_MAX_RETRY_ATTEMPTS = 72;

function depBlockedRetryDelayMs(attempt: number): number {
  return Math.min(DEP_BLOCKED_BASE_DELAY_MS * Math.pow(2, attempt), DEP_BLOCKED_MAX_DELAY_MS);
}
export const INTERACTION_CONTINUATION_INFRA_RETRY_REASON = "interaction_continuation_infra_retry";
export const INTERACTION_CONTINUATION_INFRA_WAKE_REASON = "interaction_continuation_infra_retry";
const INTERACTION_CONTINUATION_INFRA_MAX_ATTEMPTS = 3;
const RESOLVED_INTERACTION_CONTINUATION_STATUSES = new Set(["accepted", "answered", "rejected"]);
const WORKSPACE_VALIDATION_FAILURE_CODE = "workspace_validation_failed";
const WORKSPACE_VALIDATION_RECOVERY_CAUSE = "workspace_validation_failed";
const CONFIGURATION_INCOMPLETE_FAILURE_CODE = "configuration_incomplete";
const CONFIGURATION_INCOMPLETE_RECOVERY_CAUSE = "configuration_incomplete";
const EXECUTION_REVIEW_PARTICIPANT_RECOVERY_RETRY_REASON = "execution_review_participant_recovery";
const EXECUTION_REVIEW_PARTICIPANT_RECOVERY_WAKE_REASON = "execution_review_participant_recovery";
const EXECUTION_REVIEW_PARTICIPANT_RECOVERY_CAUSE = "execution_review_participant_recovery";
const GITHUB_PR_WORKFLOW_SKILL_KEY = "paperclipai/bundled/software-development/github-pr-workflow";
const GITHUB_PR_WORKFLOW_SKILL_SLUG = "github-pr-workflow";
const PUSH_CAPABILITY_ENV_KEYS = ["GH_TOKEN", "GITHUB_TOKEN"] as const;
// Keep this in sync with local adapters that require a git workspace before launch.
const GIT_SENSITIVE_LOCAL_ADAPTER_TYPES = new Set([
  "claude_local",
  "codex_local",
  "cursor",
  "gemini_local",
  "grok_local",
  "hermes_local",
  "opencode_local",
  "pi_local",
]);
// BLO-18147: claude_k8s pods bootstrap their own git workspace in-pod by
// locally `git clone --shared`-ing from the adapter's resolved cwd (confirmed
// live from a running pod's entrypoint). When no project or session
// workspace is available, that cwd falls back to the shared, actively-
// mutated per-agent AGENT_HOME directory on the same storage-sensitive
// cephfs PVC implicated in BLO-17793; a clone failure there surfaces as
// git's raw exit 128 and kills the container before `claude` even starts,
// burning Job backoff budget instead of a recoverable error. Scoped to
// claude_k8s only — opencode_k8s pods were observed healthy through the same
// incident window (BLO-18145) and are not known to share this bootstrap path.
const K8S_GIT_SENSITIVE_ADAPTER_TYPES = new Set(["claude_k8s"]);

// BLO-18760: does the workspace-less fallback need a repo-less clone source?
//
// Only for the adapters that bootstrap by cloning their resolved cwd, and only
// under `run` isolation — the one mode where that cwd is used *solely* as a
// clone source (the pod's workspace/home/session/cache roots are all ephemeral
// per-run paths). Under `shared` and `workspace` isolation the agent home is
// the live working directory and must stay persistent, so those keep it.
export function shouldUseRepoLessFallbackWorkspaceSource(input: {
  adapterType: string | null | undefined;
  k8sIsolationMode: "shared" | "run" | "workspace" | null | undefined;
}): boolean {
  const adapterType = readNonEmptyString(input.adapterType);
  if (!adapterType) return false;
  return K8S_GIT_SENSITIVE_ADAPTER_TYPES.has(adapterType) && input.k8sIsolationMode === "run";
}

// BLO-18760 (review follow-up): is a saved session cwd the workspace-less
// fallback dir belonging to the *other* k8s isolation mode?
//
// The session cwd is persisted per (agent, adapter, task) and replayed on every
// resume, but isolation is decided per *run*. The saved-cwd early return in
// `resolveWorkspaceForRun` is otherwise screened only by
// `isUnsafeSessionWorkspaceCwd`, which rejects system temp roots and knows
// nothing about isolation — so a cwd chosen under one mode is silently
// inherited by a run in the other. Both directions break:
//
//   shared -> run:  the persistent agent home (carrying a real `.git` from
//     unrelated prior runs) returns as `task_session`, the repo-less selection
//     never runs, and the BLO-18147 dispatch guard parks the run — re-opening,
//     via a resumed session, the exact strand BLO-18760 closes.
//
//   run -> shared:  a shared run adopts `empty-workspaces/<agent>` as its *live*
//     working directory and writes a `.git` into it. That directory's
//     repo-less-ness is an invariant introduced by BLO-18760 and is load-bearing
//     for every later run-isolated launch, which the same guard would then park.
//     The session/workspace mismatch check downstream fires only after
//     `executionWorkspace` is realized, so it does not prevent the inheritance,
//     and the breakage surfaces on a later, different run.
//
// Deliberately narrow: true only for the two workspace-less fallback dirs. Any
// other resumable cwd — project workspace, per-run worktree, operator branch —
// is left alone, so warm-session continuity for workspace-bound issues is
// unaffected.
export function isWorkspaceLessFallbackCwdForOtherIsolationMode(input: {
  sessionCwd: string | null | undefined;
  agentId: string;
  adapterType: string | null | undefined;
  k8sIsolationMode: "shared" | "run" | "workspace" | null | undefined;
}): boolean {
  const sessionCwd = readNonEmptyString(input.sessionCwd);
  if (!sessionCwd) return false;
  const useRepoLessFallbackSource = shouldUseRepoLessFallbackWorkspaceSource({
    adapterType: input.adapterType,
    k8sIsolationMode: input.k8sIsolationMode,
  });
  const mismatchedFallbackDir = useRepoLessFallbackSource
    ? resolveDefaultAgentWorkspaceDir(input.agentId)
    : resolveAgentEmptyWorkspaceSourceDir(input.agentId);
  return sameResolvedPath(sessionCwd, mismatchedFallbackDir);
}
export const MAX_TURN_CONTINUATION_RETRY_REASON = "max_turns_continuation";
export const MAX_TURN_CONTINUATION_WAKE_REASON = "max_turns_continuation_retry";
const MAX_TURN_CONTINUATION_DEFAULT_MAX_ATTEMPTS = 2;
const MAX_TURN_CONTINUATION_MAX_ATTEMPTS_CAP = 10;
const MAX_TURN_CONTINUATION_DEFAULT_DELAY_MS = 1_000;
const MAX_TURN_CONTINUATION_MAX_DELAY_MS = 5 * 60 * 1000;
const MAX_TURN_CONTINUATION_LIVE_RUN_STATUSES = ["scheduled_retry", "queued", "running"] as const;
type CodexTransientFallbackMode =
  | "same_session"
  | "safer_invocation"
  | "fresh_session"
  | "fresh_session_safer_invocation";

interface MaxTurnContinuationPolicy {
  enabled: boolean;
  maxAttempts: number;
  delayMs: number;
}

export class WorkspaceValidationFailure extends Error {
  code = WORKSPACE_VALIDATION_FAILURE_CODE;
  resultJson: Record<string, unknown>;

  constructor(message: string, resultJson: Record<string, unknown>) {
    super(message);
    this.name = "WorkspaceValidationFailure";
    this.resultJson = resultJson;
  }
}

// Pre-dispatch gate outcome: required secret/env bindings are missing, so the
// run must not be dispatched. Surfaced as a configuration-incomplete blocker
// routed to a human owner instead of N opaque dispatched-then-failed runs.
export class ConfigurationIncompleteFailure extends Error {
  code = CONFIGURATION_INCOMPLETE_FAILURE_CODE;
  resultJson: Record<string, unknown>;

  constructor(message: string, resultJson: Record<string, unknown>) {
    super(message);
    this.name = "ConfigurationIncompleteFailure";
    this.resultJson = resultJson;
  }
}

function resolveCodexTransientFallbackMode(attempt: number): CodexTransientFallbackMode {
  if (attempt <= 1) return "same_session";
  if (attempt === 2) return "safer_invocation";
  if (attempt === 3) return "fresh_session";
  return "fresh_session_safer_invocation";
}

function readHeartbeatRunErrorFamily(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode" | "resultJson">,
) {
  const resultJson = parseObject(run.resultJson);
  const persistedFamily = readNonEmptyString(resultJson.errorFamily);
  if (persistedFamily) return persistedFamily;

  if (run.errorCode === "rate_limit_exhausted") {
    return "rate_limit_exhausted";
  }
  if (run.errorCode === "provider_quota") {
    return "provider_quota";
  }
  if (run.errorCode === "codex_transient_upstream" || run.errorCode === "claude_transient_upstream") {
    return "transient_upstream";
  }
  // BLO-18285: the server-side classification of a hint-less provider 503/529
  // on the k8s adapters, which never run the local adapters' transient parser.
  if (run.errorCode === "provider_transient_upstream") {
    return "transient_upstream";
  }
  if (run.errorCode === "k8s_concurrent_run_blocked") {
    return "capacity_blocked";
  }
  return null;
}

function isMaxTurnExhaustionRun(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode" | "resultJson">,
) {
  const resultJson = parseObject(run.resultJson);
  return Boolean(
    normalizeMaxTurnStopReason(resultJson.stopReason) ??
      normalizeMaxTurnStopReason(run.errorCode),
  );
}

function readTransientRetryNotBeforeFromRun(run: Pick<typeof heartbeatRuns.$inferSelect, "resultJson">) {
  const resultJson = parseObject(run.resultJson);
  const value = resultJson.retryNotBefore ?? resultJson.transientRetryNotBefore;
  if (!(typeof value === "string" || typeof value === "number" || value instanceof Date)) {
    return null;
  }
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

type TransientRecoveryContract =
  | {
      errorFamily: "transient_upstream";
      retryNotBefore: Date | null;
    }
  | {
      errorFamily: "rate_limit_exhausted";
      retryNotBefore: Date | null;
    }
  | {
      errorFamily: "provider_quota";
      retryNotBefore: Date | null;
    };

function readTransientRecoveryContractFromRun(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode" | "resultJson">,
): TransientRecoveryContract | null {
  const family = readHeartbeatRunErrorFamily(run);
  if (family === "transient_upstream") {
    return {
      errorFamily: "transient_upstream",
      retryNotBefore: readTransientRetryNotBeforeFromRun(run),
    };
  }
  if (family === "rate_limit_exhausted") {
    return {
      errorFamily: "rate_limit_exhausted",
      retryNotBefore: readTransientRetryNotBeforeFromRun(run),
    };
  }
  if (family === "provider_quota") {
    return {
      errorFamily: "provider_quota",
      retryNotBefore: readTransientRetryNotBeforeFromRun(run),
    };
  }
  return null;
}

export function shouldScheduleAutomaticRunRetry(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode" | "resultJson" | "contextSnapshot">,
) {
  if (readTransientRecoveryContractFromRun(run)) return true;

  // BLO-8215: a mid-run GitHub App token expiry on a PR-review publish is flagged
  // `pr_review_auth_expired` and is recoverable — the next run gets a freshly
  // minted installation token and completes the publish. Gate on the taskKey-
  // aware pr-review check (same helper the process-loss retry path uses) so it
  // fires even when the persisted contextSnapshot is trimmed of githubPrNumber.
  if (run.errorCode === "pr_review_auth_expired") {
    return isPrReviewRetryContext(parseObject(run.contextSnapshot));
  }

  // BLO-17456: a run that exited successfully but left no durable review/skip
  // evidence (`pr_review_output_missing`, set by evaluatePrReviewCompletionEvidence
  // only after its own GitHub-side rescue check — BLO-10448 — already failed to
  // find one) was previously a terminal failure with no automatic retry, so
  // clearing it required an out-of-band fix (e.g. a manual agent image bump)
  // instead of the platform just trying again. Bounded-retry it like the other
  // pr_review-scoped recoverable failures above so a transient posting glitch
  // self-heals instead of silently stranding the exact-head gate.
  if (
    run.errorCode === "pr_review_output_missing" ||
    run.errorCode === "pr_review_verification_unavailable"
  ) {
    return isPrReviewRetryContext(parseObject(run.contextSnapshot));
  }

  const contextSnapshot = parseObject(run.contextSnapshot);
  const isIssueRun = Boolean(readNonEmptyString(contextSnapshot.issueId));

  // Capacity refusals are safe to retry for durable issue work as well as PR
  // reviews. Timer and maintenance runs remain terminal to avoid retry leaks.
  if (run.errorCode === "k8s_concurrent_run_blocked") {
    return isIssueRun || isPrReviewRetryContext(contextSnapshot);
  }

  // A failed external-lifecycle Job may have performed non-idempotent work.
  // Retry only when the reconciler durably proved adapter invocation never
  // began; lock/status gates alone cannot make partial external writes safe.
  if (run.errorCode === "job_failed") {
    const recovery = parseObject(parseObject(run.resultJson).externalLifecycleRecovery);
    return isIssueRun && recovery.adapterInvocationStarted === false;
  }

  // BLO-10448: scheduler-level transient infra failures where the agent pod
  // never ran — the node pool was momentarily saturated (k8s_pod_schedule_failed:
  // Unschedulable / image-pull / schedule-timeout) or the external-lifecycle Job
  // vanished before completion (job_missing). The work never started, so re-queue
  // pr_review wakes with bounded backoff to let the review land once capacity
  // frees, instead of silently dropping it (observed on the Ally reviewer path:
  // a single Unschedulable burst dropped a PR review with no retry). Non-PR wakes
  // stay terminal, matching the k8s_concurrent_run_blocked leak guard above.
  if (run.errorCode === "k8s_pod_schedule_failed" || run.errorCode === "job_missing") {
    return isPrReviewRetryContext(parseObject(run.contextSnapshot));
  }

  if (run.errorCode !== "adapter_failed" && run.errorCode !== "process_lost") return false;

  // BLO-9147 AC1: gate on wakeReason/reviewKind/taskKey from the persisted
  // contextSnapshot, NOT on githubPrNumber presence. derivePaperclipPrReview
  // returns null when githubPrNumber is absent (thin 3-key snapshot), causing
  // silent single-attempt drops for webhook-driven runs whose snapshot was
  // trimmed. isPrReviewRetryContext handles all three forms: reviewKind,
  // taskKey-prefixed, and wakeReason-prefixed.
  return isPrReviewRetryContext(parseObject(run.contextSnapshot));
}

function isPrReviewRetryContext(contextSnapshot: Record<string, unknown>) {
  const reviewKind = readNonEmptyString(contextSnapshot.reviewKind);
  if (reviewKind === "pr_review") return true;
  const taskKey = readNonEmptyString(contextSnapshot.taskKey);
  return taskKey?.startsWith("pr_review:") === true;
}

type PrReviewFairnessRun = Pick<
  typeof heartbeatRuns.$inferSelect,
  "id" | "createdAt" | "contextSnapshot"
>;

export function selectAgedPrReviewRunForFairDispatch(
  queuedRuns: PrReviewFairnessRun[],
  lastStartedRun: Pick<PrReviewFairnessRun, "contextSnapshot"> | null,
  now = new Date(),
) {
  if (
    lastStartedRun &&
    isPrReviewRetryContext(parseObject(lastStartedRun.contextSnapshot))
  ) {
    return null;
  }

  const cutoff = now.getTime() - PR_REVIEW_QUEUE_FAIRNESS_MAX_WAIT_MS;
  return queuedRuns
    .filter(
      (run) =>
        run.createdAt.getTime() <= cutoff &&
        isPrReviewRetryContext(parseObject(run.contextSnapshot)),
    )
    .sort(
      (left, right) =>
        left.createdAt.getTime() - right.createdAt.getTime() ||
        left.id.localeCompare(right.id),
    )[0]?.id ?? null;
}

/**
 * Returns the opts to pass to `scheduleBoundedRetryForRun` for an automatic
 * retry, or undefined to use the default transient-failure opts. Called only
 * when `shouldScheduleAutomaticRunRetry` already returned true.
 */
function resolveAutomaticRunRetryOpts(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode">,
) {
  if (run.errorCode === "k8s_concurrent_run_blocked") {
    return {
      retryReason: CAPACITY_BLOCKED_HEARTBEAT_RETRY_REASON,
      wakeReason: CAPACITY_BLOCKED_HEARTBEAT_RETRY_WAKE_REASON,
      maxAttempts: CAPACITY_BLOCKED_HEARTBEAT_RETRY_MAX_ATTEMPTS,
      delayMs: CAPACITY_BLOCKED_HEARTBEAT_RETRY_DELAY_MS,
    };
  }
  if (run.errorCode === "job_failed") {
    return {
      retryReason: JOB_FAILED_HEARTBEAT_RETRY_REASON,
      wakeReason: JOB_FAILED_HEARTBEAT_RETRY_WAKE_REASON,
      maxAttempts: JOB_FAILED_HEARTBEAT_RETRY_MAX_ATTEMPTS,
    };
  }
  return undefined;
}

function requiresIssueExecutionRetryLock(retryReason: string | null | undefined) {
  return (
    retryReason === MAX_TURN_CONTINUATION_RETRY_REASON ||
    retryReason === CAPACITY_BLOCKED_HEARTBEAT_RETRY_REASON ||
    retryReason === JOB_FAILED_HEARTBEAT_RETRY_REASON
  );
}

function requiresInProgressIssueRetry(retryReason: string | null | undefined) {
  return requiresIssueExecutionRetryLock(retryReason);
}

function isResolvedInteractionContinuationWakeContext(contextSnapshot: unknown) {
  const context = parseObject(contextSnapshot);
  const interactionId = readNonEmptyString(context.interactionId);
  const interactionStatus = readNonEmptyString(context.interactionStatus);
  if (!interactionId || !interactionStatus) return false;
  if (!RESOLVED_INTERACTION_CONTINUATION_STATUSES.has(interactionStatus)) return false;

  const mutation = readNonEmptyString(context.mutation);
  const wakeReason = readNonEmptyString(context.wakeReason);
  const retryReason = readNonEmptyString(context.retryReason);
  return (
    (mutation === "interaction" && wakeReason === "issue_commented") ||
    wakeReason === INTERACTION_CONTINUATION_INFRA_WAKE_REASON ||
    retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON
  );
}

function isSpawnLikeFailureMessage(value: unknown) {
  if (typeof value !== "string") return false;
  return /failed to start command|spawn\b|\bENOENT\b/i.test(value);
}

export function isRetryableInteractionContinuationInfrastructureFailure(
  run: Pick<typeof heartbeatRuns.$inferSelect, "error" | "errorCode" | "resultJson">,
) {
  if (run.errorCode === WORKSPACE_VALIDATION_FAILURE_CODE) {
    const workspaceValidation = parseObject(parseObject(run.resultJson).workspaceValidation);
    if (
      readNonEmptyString(workspaceValidation.reason) ===
      "k8s_agent_home_git_bootstrap_unsupported"
    ) {
      return false;
    }
    return true;
  }
  if (run.errorCode === "process_lost") {
    return true;
  }

  if (run.errorCode !== "adapter_failed" && run.errorCode !== "setup_failed") return false;

  const resultJson = parseObject(run.resultJson);
  return (
    isSpawnLikeFailureMessage(run.error) ||
    isSpawnLikeFailureMessage(resultJson.errorMessage) ||
    isSpawnLikeFailureMessage(resultJson.message)
  );
}

function mergeAdapterRecoveryMetadata(input: {
  resultJson: Record<string, unknown> | null | undefined;
  errorFamily?: string | null;
  retryNotBefore?: string | null;
}) {
  const errorFamily = readNonEmptyString(input.errorFamily);
  const retryNotBefore = readNonEmptyString(input.retryNotBefore);
  if (!input.resultJson && !errorFamily && !retryNotBefore) return input.resultJson ?? null;

  return {
    ...(input.resultJson ?? {}),
    ...(errorFamily ? { errorFamily } : {}),
    ...(retryNotBefore
      ? {
          retryNotBefore,
          transientRetryNotBefore: retryNotBefore,
          ...(errorFamily === "provider_quota" ? { providerQuotaRetryNotBefore: retryNotBefore } : {}),
        }
      : {}),
  };
}
const RUNNING_ISSUE_WAKE_REASONS_REQUIRING_FOLLOWUP = new Set([
  "approval_approved",
  ISSUE_BLOCKERS_RESOLVED_WAKE_REASON,
]);
const ISSUE_RESPONSIBLE_USER_WAKE_REASONS = new Set([
  "issue_assigned",
  "issue_checked_out",
  "issue_commented",
  "issue_comment_mentioned",
  "issue_reopened_via_comment",
  "issue_blockers_resolved",
  "issue_children_completed",
  "issue_status_changed",
  "issue_tree_restored",
  "issue_recovery_action_restored",
  "execution_review_requested",
  "execution_approval_requested",
  "execution_changes_requested",
  "approval_approved",
]);
const SESSIONED_LOCAL_ADAPTERS = new Set([
  "claude_local",
  "codex_local",
  "cursor",
  "gemini_local",
  "hermes_local",
  "opencode_local",
  "pi_local",
]);
const EXTERNAL_LIFECYCLE_ADAPTERS = new Set<string>(EXTERNAL_LIFECYCLE_ADAPTER_TYPES);
// Fallback staleness window for external-lifecycle (k8s Job) runs when the
// kube API is unavailable (local dev, RBAC misconfig, transient failure).
// In-cluster the reaper uses listLiveAgentJobRunIds() to identify dead
// Jobs immediately; this threshold only applies when that probe returns
// null. Kept generous so a slow probe + a healthy long-running Claude
// session don't collide.
// Shared with issue-run-holding.ts for one named 15-minute slot-accounting
// threshold. Issue/worktree ownership stays more conservative: a running row
// holds its issue until it reaches a terminal/missing lifecycle state.
const EXTERNAL_LIFECYCLE_STALE_MS = RUN_STALE_SILENCE_MS;
// External-lifecycle adapters create a DB run before the adapter.invoke event
// is appended. Startup and periodic reapers can overlap that setup window;
// give slow pre-run hooks and kube Job creation time to reach adapter.invoke.
const EXTERNAL_LIFECYCLE_PRE_ADAPTER_STALE_MS = 5 * 60 * 1000;
// BLO-16253: dispatchRank (priorityRank * 2 + statusBonus) has no time
// component, so a `todo` queued run can be starved forever behind a busy
// agent's constantly-refreshed `in_progress` follow-up dispatches, even at
// equal or lower priority — the availableSlots gate caps external-lifecycle
// dispatch to exactly one winner per tick (see BLO-13176 note below), so a
// perpetual loser never gets a turn. Observed 2026-07-15 on BLO-15871 (low
// priority, todo): its queued run sat unpromoted for 4+ hours while the same
// agent's low/high-priority in_progress issues kept winning the single slot
// every tick. Aging closes this in two bounded steps: after
// STARVATION_STATUS_BOOST_MS waited, forgive the todo/in_progress status
// penalty (lets it tie same-priority in_progress work); after
// STARVATION_FULL_ESCALATION_MS, promote it ahead of routine work while
// preserving ranks 0-1 for explicit critical issues.
const STARVATION_STATUS_BOOST_MS = 30 * 60 * 1000;
const STARVATION_FULL_ESCALATION_MS = 2 * 60 * 60 * 1000;
// BLO-16253 follow-up: a recovery/wake_owner run (contextSnapshot.recoveryActionId
// set — see recovery/service.ts enqueueWakeup calls) represents an ALREADY-DETECTED
// failure that needs the owner's attention now, not routine backlog grooming. The
// routine STARVATION_FULL_ESCALATION_MS floor (2h) is appropriate for "eventually
// get to this todo," but far too slow for "your assigned recovery is broken" —
// observed live: BLO-15871's stranded_assigned_issue recovery (owner CTO) sat
// unacted for ~2h48m because it competed for CTO's single dispatch slot on the
// exact same terms as routine low-priority backlog, only escalating once it
// crossed the routine 2h floor. Recovery wakes get a much shorter floor so they
// jump the queue quickly instead of waiting behind ordinary work.
const STARVATION_RECOVERY_ESCALATION_MS = 10 * 60 * 1000;
// If another process has just finalized a run while its k8s Job is still
// visible, do not immediately delete that live Job. The adapter process may
// still be awaiting/synchronizing the Job and should be allowed to finish.
const EXTERNAL_LIFECYCLE_RECENT_RUN_GRACE_MS = 5 * 60 * 1000;
// BLO-12996: hard ceiling after which a live-but-silent external-lifecycle Job
// is force-killed to unblock agent dispatch. This is deliberately MUCH longer
// than EXTERNAL_LIFECYCLE_STALE_MS (15 min). The 15-min soft floor is safe for
// *not counting* a stale run toward the slot gate (BLO-12990 Fix #1) and for
// reaping runs whose Job is already absent/terminal, but it is NOT safe as a
// kill trigger for a Job that is still `phase: active`: the 2026-05-23 RCA
// (see reapOrphanedRuns) found that killing live-but-quiet Jobs at that floor
// produced ~6.5/hr fleet-wide false `process_lost` on healthy long-streaming
// agents. A genuinely stuck run emits no useful action for far longer — the
// silent-active-run reviewer flags at ~1h and observed zombies ran 90-120 min
// with zero output. 45 min keys the destructive kill well past any healthy
// quiet gap (which bumps lastUsefulActionAt) while still reclaiming the slot
// and node CPU long before the multi-hour manual-reap point.
const EXTERNAL_LIFECYCLE_HARD_STALE_MS = 45 * 60 * 1000;
// BLO-12564: cold-boot reattach grace. On a fresh worker boot the in-cluster
// kube client may not be serving yet, so the startup reap (server/src/index.ts)
// and the first periodic ticks can run with BOTH listAgentJobRunStatuses() and
// listLiveAgentJobRunIds() returning null (fully kube-blind — the same signal
// that drives recordProcessLostLivenessNull()). A running external-lifecycle Job
// survives the worker restart (it is owned by its own k8s controller), so minting
// process_lost while blind would zero a run whose Job is very likely still
// Running. This grace — measured from worker boot — holds the reap while fully
// blind so the next warm tick can resolve "alive" (reattach) or "dead" (reap).
// Past the grace, a persistent kube outage still reaps after the silence floor:
// no permanent shield, no regression to the legitimate-lost path. Symmetric to
// the BLO-12563 shutdown-side drain guard. Wired only on the long-lived worker
// (server/src/index.ts); the factory default is 0 (off) so route/service
// per-request constructions and the steady-state test contract stay unchanged.
export const EXTERNAL_LIFECYCLE_COLD_BOOT_REATTACH_GRACE_MS = 5 * 60 * 1000;
// Routes and the scheduler construct separate heartbeatService instances, but
// they must agree on in-process adapter executions when reaping stale runs.
const activeRunExecutions = new Set<string>();
// BLO-16850: minimum pod age before the orphaned-managed-pod sweep will
// force-delete it. A pod is created moments before its heartbeat_runs row
// flips to "running"; this grace prevents reaping that startup race. Mirrors
// the 5-min grace in cleanupManagedJobsWithoutRun.
const ORPHANED_MANAGED_POD_REAP_GRACE_MS = 5 * 60 * 1000;
const INLINE_BASE64_IMAGE_DATA_RE = /("type":"image","source":\{"type":"base64","data":")([A-Za-z0-9+/=]{1024,})(")/g;
const SESSION_ISOLATION_KEY_PARAM = "paperclipIsolationKey";

type RuntimeConfigSecretResolver = Pick<
  ReturnType<typeof secretService>,
  | "resolveAdapterConfigForRuntime"
  | "resolveEnvBindings"
  | "collectMissingRuntimeBindings"
  | "collectMissingAdapterConfigRuntimeBindings"
>;

function formatMissingBindingForOperator(missing: MissingRuntimeBinding): string {
  if (missing.bindingType === "user_secret_ref") {
    const definitionLabel =
      missing.userSecretDefinitionName
        ? `"${missing.userSecretDefinitionName}"`
        : missing.userSecretDefinitionKey
          ? `"${missing.userSecretDefinitionKey}"`
          : "declared user secret";
    const ownerLabel = missing.responsibleUserId ? ` for responsible user ${missing.responsibleUserId}` : "";
    return `user secret ${definitionLabel}${ownerLabel} not available at ${missing.consumerType} ${missing.configPath}`;
  }
  const secretLabel = missing.secretName
    ? `"${missing.secretName}"`
    : missing.secretId ?? "unknown";
  return `secret ${secretLabel} not bound at ${missing.consumerType} ${missing.configPath}`;
}

function isConfiguredEnvBindingValue(binding: unknown) {
  const parsed = envBindingSchema.safeParse(binding);
  if (!parsed.success) return false;
  const value = parsed.data;
  if (typeof value === "string") return value.trim().length > 0;
  if (value.type === "plain") return value.value.trim().length > 0;
  return true;
}

function hasGithubPrWorkflowSkill(desiredSkills: string[]) {
  return desiredSkills.some((skill) => {
    const normalized = skill.trim();
    return normalized === GITHUB_PR_WORKFLOW_SKILL_KEY
      || normalized === GITHUB_PR_WORKFLOW_SKILL_SLUG
      || normalized.endsWith(`/${GITHUB_PR_WORKFLOW_SKILL_SLUG}`);
  });
}

export function requiresPushCapabilityPreflight(input: {
  adapterType: string;
  issueId: string | null | undefined;
  explicitRunScopedSkillKeys: string[];
}) {
  return Boolean(input.issueId)
    && GIT_SENSITIVE_LOCAL_ADAPTER_TYPES.has(input.adapterType)
    && hasGithubPrWorkflowSkill(input.explicitRunScopedSkillKeys);
}

const LOW_TRUST_SENSITIVE_ENV_KEY_RE =
  /(api[-_]?key|access[-_]?token|auth(?:_?token)?|authorization|bearer|secret|passwd|password|credential|jwt|private[-_]?key|cookie|connectionstring)/i;

function isPaperclipRuntimeEnvKey(key: string) {
  return key.startsWith("PAPERCLIP_");
}

function stripPaperclipRuntimeEnvBindings(envValue: unknown): Record<string, unknown> | null {
  const record = parseObject(envValue);
  const filtered = Object.fromEntries(
    Object.entries(record).filter(([key]) => !isPaperclipRuntimeEnvKey(key)),
  );
  return Object.keys(filtered).length > 0 ? filtered : null;
}

function stripPaperclipRuntimeEnvFromAdapterConfig(config: Record<string, unknown>): Record<string, unknown> {
  if (!Object.prototype.hasOwnProperty.call(config, "env")) return config;
  return {
    ...config,
    env: stripPaperclipRuntimeEnvBindings(config.env) ?? {},
  };
}

function assertLowTrustEnvConfigAllowed(envValue: unknown, source: string) {
  const record = stripPaperclipRuntimeEnvBindings(envValue);
  if (!record) return;
  for (const [key, rawBinding] of Object.entries(record)) {
    const parsed = envBindingSchema.safeParse(rawBinding);
    if (!parsed.success) continue;
    const binding = parsed.data;
    const isPlainBinding =
      typeof binding === "string" ||
      (typeof binding === "object" && binding !== null && binding.type === "plain");
    if (isPlainBinding && LOW_TRUST_SENSITIVE_ENV_KEY_RE.test(key)) {
      throw new HttpError(422, `Low-trust execution cannot use inline sensitive env value ${source}.${key}`, {
        code: "low_trust_inline_sensitive_env_denied",
      });
    }
  }
}

export async function resolveExecutionRunAdapterConfig(input: {
  companyId: string;
  agentId?: string | null;
  adapterType?: string | null;
  issueId?: string | null;
  heartbeatRunId?: string | null;
  responsibleUserId?: string | null;
  environmentId?: string | null;
  environmentEnv?: unknown;
  projectId?: string | null;
  routineId?: string | null;
  executionRunConfig: Record<string, unknown>;
  projectEnv: unknown;
  routineEnv?: unknown;
  secretsSvc: RuntimeConfigSecretResolver;
  trustPreset?: TrustPresetResolution;
  requiredScopedEnvBinding?: {
    keys: string[];
    consumerScopes: Array<"agent" | "project">;
    reason: string;
    remediation: string;
  };
}) {
  const executionRunConfig = stripPaperclipRuntimeEnvFromAdapterConfig(input.executionRunConfig);
  const environmentEnv = stripPaperclipRuntimeEnvBindings(input.environmentEnv);
  const projectEnv = stripPaperclipRuntimeEnvBindings(input.projectEnv);
  const routineEnv = stripPaperclipRuntimeEnvBindings(input.routineEnv);
  const lowTrustAllowedBindingIds = input.trustPreset?.kind === "low_trust_review"
    ? input.trustPreset.boundary.allowedSecretBindingIds ?? []
    : undefined;
  if (input.trustPreset?.kind === "low_trust_review") {
    assertLowTrustEnvConfigAllowed(environmentEnv, "environment.env");
    assertLowTrustEnvConfigAllowed(executionRunConfig.env, "agent.env");
    assertLowTrustEnvConfigAllowed(projectEnv, "project.env");
    assertLowTrustEnvConfigAllowed(routineEnv, "routine.env");
  }
  const agentEnv = parseObject(executionRunConfig.env);
  const requiredScopedEnvBinding = input.requiredScopedEnvBinding ?? null;
  const requiredScopedBindingsConfigured = requiredScopedEnvBinding
    ? requiredScopedEnvBinding.keys.some((key) => (
      requiredScopedEnvBinding.consumerScopes.includes("agent")
      && isConfiguredEnvBindingValue(agentEnv[key])
    ) || (
      requiredScopedEnvBinding.consumerScopes.includes("project")
      && isConfiguredEnvBindingValue(projectEnv?.[key])
    ))
    : false;
  if (requiredScopedEnvBinding && !requiredScopedBindingsConfigured) {
    throw new ConfigurationIncompleteFailure(`configuration incomplete: ${requiredScopedEnvBinding.remediation}`, {
      configurationIncomplete: {
        reason: requiredScopedEnvBinding.reason,
        companyId: input.companyId,
        agentId: input.agentId ?? null,
        issueId: input.issueId ?? null,
        projectId: input.projectId ?? null,
        routineId: input.routineId ?? null,
        requiredEnvKeys: requiredScopedEnvBinding.keys,
        requiredScopes: requiredScopedEnvBinding.consumerScopes,
        missingBindings: [],
      },
    });
  }
  // Pre-dispatch binding-validation gate: detect declared secret refs that have
  // no binding before resolving any secret value. Missing bindings short-circuit
  // to a configuration-incomplete blocker routed to a human owner instead of a
  // dispatched-then-failed run (which previously surfaced as opaque setup_failed).
  if (typeof input.secretsSvc.collectMissingRuntimeBindings === "function") {
    const missingBindings: MissingRuntimeBinding[] = [];
    if (environmentEnv && input.environmentId) {
      missingBindings.push(
        ...(await input.secretsSvc.collectMissingRuntimeBindings(
          input.companyId,
          environmentEnv,
          {
            consumerType: "environment",
            consumerId: input.environmentId,
            responsibleUserId: input.responsibleUserId ?? null,
          },
        )),
      );
    }
    if (input.agentId) {
      missingBindings.push(
        ...(await input.secretsSvc.collectMissingRuntimeBindings(
          input.companyId,
          parseObject(executionRunConfig.env),
          {
            consumerType: "agent",
            consumerId: input.agentId,
            responsibleUserId: input.responsibleUserId ?? null,
          },
        )),
      );
      if (typeof input.secretsSvc.collectMissingAdapterConfigRuntimeBindings === "function") {
        missingBindings.push(
          ...(await input.secretsSvc.collectMissingAdapterConfigRuntimeBindings(
            input.companyId,
            executionRunConfig,
            input.adapterType ?? null,
            {
              consumerType: "agent",
              consumerId: input.agentId,
              responsibleUserId: input.responsibleUserId ?? null,
            },
          )),
        );
      }
    }
    if (projectEnv && input.projectId) {
      missingBindings.push(
        ...(await input.secretsSvc.collectMissingRuntimeBindings(
          input.companyId,
          projectEnv,
          {
            consumerType: "project",
            consumerId: input.projectId,
            responsibleUserId: input.responsibleUserId ?? null,
          },
        )),
      );
    }
    if (routineEnv && input.routineId) {
      missingBindings.push(
        ...(await input.secretsSvc.collectMissingRuntimeBindings(
          input.companyId,
          routineEnv,
          {
            consumerType: "routine",
            consumerId: input.routineId,
            responsibleUserId: input.responsibleUserId ?? null,
          },
        )),
      );
    }
    if (requiredScopedEnvBinding) {
      const requiredEnvKeys = new Set(requiredScopedEnvBinding.keys);
      const requiredScopes = new Set(requiredScopedEnvBinding.consumerScopes);
      const requiredMissingBindings = missingBindings.filter((binding) =>
        requiredScopes.has(binding.consumerType as "agent" | "project")
        && requiredEnvKeys.has(binding.envKey),
      );
      if (requiredMissingBindings.length > 0) {
        const detail = requiredMissingBindings.map(formatMissingBindingForOperator).join("; ");
        throw new ConfigurationIncompleteFailure(
          `configuration incomplete: ${requiredScopedEnvBinding.remediation}; ${detail}`,
          {
            configurationIncomplete: {
              reason: requiredScopedEnvBinding.reason,
              companyId: input.companyId,
              agentId: input.agentId ?? null,
              issueId: input.issueId ?? null,
              projectId: input.projectId ?? null,
              routineId: input.routineId ?? null,
              requiredEnvKeys: requiredScopedEnvBinding.keys,
              requiredScopes: requiredScopedEnvBinding.consumerScopes,
              missingBindings: requiredMissingBindings,
            },
          },
        );
      }
    }
    if (missingBindings.length > 0) {
      const detail = missingBindings.map(formatMissingBindingForOperator).join("; ");
      throw new ConfigurationIncompleteFailure(`configuration incomplete: ${detail}`, {
        configurationIncomplete: {
          reason: "secret_binding_missing",
          companyId: input.companyId,
          agentId: input.agentId ?? null,
          issueId: input.issueId ?? null,
          projectId: input.projectId ?? null,
          routineId: input.routineId ?? null,
          missingBindings,
        },
      });
    }
  }
  const environmentEnvResolution = environmentEnv
    ? await input.secretsSvc.resolveEnvBindings(
        input.companyId,
        environmentEnv,
        input.environmentId
          ? {
              consumerType: "environment",
              consumerId: input.environmentId,
              actorType: "agent",
              actorId: input.agentId ?? null,
              responsibleUserId: input.responsibleUserId ?? null,
              issueId: input.issueId ?? null,
              heartbeatRunId: input.heartbeatRunId ?? null,
              ...(lowTrustAllowedBindingIds !== undefined ? { allowedBindingIds: lowTrustAllowedBindingIds } : {}),
            }
          : undefined,
      )
    : { env: {}, secretKeys: new Set<string>(), manifest: [] };
  const { config: resolvedConfig, secretKeys, manifest } = await input.secretsSvc.resolveAdapterConfigForRuntime(
    input.companyId,
    executionRunConfig,
    input.agentId
      ? {
          consumerType: "agent",
          consumerId: input.agentId,
          actorType: "agent",
          actorId: input.agentId,
          responsibleUserId: input.responsibleUserId ?? null,
          issueId: input.issueId ?? null,
          heartbeatRunId: input.heartbeatRunId ?? null,
          ...(lowTrustAllowedBindingIds !== undefined ? { allowedBindingIds: lowTrustAllowedBindingIds } : {}),
        }
      : undefined,
    { adapterType: input.adapterType ?? null },
  );
  if (Object.keys(environmentEnvResolution.env).length > 0) {
    resolvedConfig.env = {
      ...environmentEnvResolution.env,
      ...parseObject(resolvedConfig.env),
    };
    for (const key of environmentEnvResolution.secretKeys) {
      secretKeys.add(key);
    }
  }
  const projectEnvResolution = projectEnv
    ? await input.secretsSvc.resolveEnvBindings(
        input.companyId,
        projectEnv,
        input.projectId
          ? {
              consumerType: "project",
              consumerId: input.projectId,
              actorType: "agent",
              actorId: input.agentId ?? null,
              responsibleUserId: input.responsibleUserId ?? null,
              issueId: input.issueId ?? null,
              heartbeatRunId: input.heartbeatRunId ?? null,
              ...(lowTrustAllowedBindingIds !== undefined ? { allowedBindingIds: lowTrustAllowedBindingIds } : {}),
            }
          : undefined,
      )
    : { env: {}, secretKeys: new Set<string>(), manifest: [] };
  if (Object.keys(projectEnvResolution.env).length > 0) {
    resolvedConfig.env = {
      ...parseObject(resolvedConfig.env),
      ...projectEnvResolution.env,
    };
    for (const key of projectEnvResolution.secretKeys) {
      secretKeys.add(key);
    }
  }
  const routineEnvResolution = routineEnv
    ? await input.secretsSvc.resolveEnvBindings(
        input.companyId,
        routineEnv,
        input.routineId
          ? {
              consumerType: "routine",
              consumerId: input.routineId,
              actorType: "agent",
              actorId: input.agentId ?? null,
              responsibleUserId: input.responsibleUserId ?? null,
              issueId: input.issueId ?? null,
              heartbeatRunId: input.heartbeatRunId ?? null,
              ...(lowTrustAllowedBindingIds !== undefined ? { allowedBindingIds: lowTrustAllowedBindingIds } : {}),
            }
          : undefined,
      )
    : { env: {}, secretKeys: new Set<string>(), manifest: [] };
  if (Object.keys(routineEnvResolution.env).length > 0) {
    resolvedConfig.env = {
      ...parseObject(resolvedConfig.env),
      ...routineEnvResolution.env,
    };
    for (const key of routineEnvResolution.secretKeys) {
      secretKeys.add(key);
    }
  }
  // Pre-dispatch credential gate for codex_local: a managed Codex home with no
  // usable auth.json and an empty OPENAI_API_KEY would dispatch a run that
  // immediately fails with "no Codex credentials provisioned" (adapter_failed),
  // making a configuration problem look like a runtime failure. Surface it as a
  // configuration-incomplete blocker instead, naming the missing credential
  // action and owner without leaking any secret value. This runs after secret
  // resolution so a per-agent OPENAI_API_KEY (plain or resolved secret) counts
  // as satisfying the credential. It shares the exact readiness predicate the
  // adapter uses at execute time, so the two cannot drift.
  if ((input.adapterType ?? null) === "codex_local") {
    const resolvedEnv = parseObject(resolvedConfig.env);
    const readiness = await evaluateCodexCredentialReadiness({
      env: process.env,
      companyId: input.companyId,
      configuredCodexHome: readNonEmptyString(resolvedEnv.CODEX_HOME),
      configuredApiKey: readNonEmptyString(resolvedEnv.OPENAI_API_KEY),
    });
    if (readiness.managed && !readiness.ready) {
      throw new ConfigurationIncompleteFailure(
        `configuration incomplete: no Codex credentials available for managed home "${readiness.effectiveHome}". ` +
          `Sign in to Codex on the host with a ChatGPT subscription, or bind a per-agent OPENAI_API_KEY secret for this agent.`,
        {
          configurationIncomplete: {
            reason: "codex_credentials_missing",
            companyId: input.companyId,
            agentId: input.agentId ?? null,
            issueId: input.issueId ?? null,
            projectId: input.projectId ?? null,
            routineId: input.routineId ?? null,
            responsibleUserId: input.responsibleUserId ?? null,
            adapterType: "codex_local",
            requiredEnvKeys: ["OPENAI_API_KEY"],
            effectiveCodexHome: readiness.effectiveHome,
            missingBindings: [],
          },
        },
      );
    }
  }
  return {
    resolvedConfig,
    secretKeys,
    secretManifest: [
      ...(environmentEnvResolution.manifest ?? []),
      ...(manifest ?? []),
      ...(projectEnvResolution.manifest ?? []),
      ...(routineEnvResolution.manifest ?? []),
    ],
  };
}

export function extractMentionedSkillIdsFromSources(
  sources: Array<string | null | undefined>,
): string[] {
  const mentionedIds = new Set<string>();
  for (const source of sources) {
    if (typeof source !== "string" || source.length === 0) continue;
    for (const skillId of extractSkillMentionIds(source)) {
      if (!isUuidLike(skillId)) continue;
      mentionedIds.add(skillId);
    }
  }
  return [...mentionedIds];
}

export function applyRunScopedMentionedSkillKeys(
  config: Record<string, unknown>,
  skillKeys: string[],
): Record<string, unknown> {
  const normalizedSkillKeys = Array.from(
    new Set(
      skillKeys
        .map((value) => value.trim())
        .filter(Boolean),
    ),
  );
  if (normalizedSkillKeys.length === 0) return config;

  const existingPreference = readPaperclipSkillSyncPreference(config);
  return writePaperclipSkillSyncPreference(config, [
    ...existingPreference.desiredSkillEntries,
    ...normalizedSkillKeys,
  ]);
}

export function computeBoundedTransientHeartbeatRetrySchedule(
  attempt: number,
  now = new Date(),
  random: () => number = Math.random,
) {
  if (!Number.isInteger(attempt) || attempt <= 0) return null;
  const baseDelayMs = BOUNDED_TRANSIENT_HEARTBEAT_RETRY_DELAYS_MS[attempt - 1];
  if (typeof baseDelayMs !== "number") return null;
  const sample = Math.min(1, Math.max(0, random()));
  const jitterMultiplier = 1 + (((sample * 2) - 1) * BOUNDED_TRANSIENT_HEARTBEAT_RETRY_JITTER_RATIO);
  const delayMs = Math.max(1_000, Math.round(baseDelayMs * jitterMultiplier));
  return {
    attempt,
    baseDelayMs,
    delayMs,
    dueAt: new Date(now.getTime() + delayMs),
    maxAttempts: BOUNDED_TRANSIENT_HEARTBEAT_RETRY_MAX_ATTEMPTS,
  };
}

/**
 * Schedule a rate-limit retry: flat short delay (90s ± 25%), capped attempt
 * count. The actual decision of whether the retry runs is delegated to the
 * ccrotate gate at dispatch time — this function only sets when we're next
 * willing to try. Past the cap, returns null so the caller logs retry-
 * exhausted and stops queuing.
 */
export function computeRateLimitHeartbeatRetrySchedule(
  attempt: number,
  now = new Date(),
  random: () => number = Math.random,
) {
  if (!Number.isInteger(attempt) || attempt <= 0) return null;
  if (attempt > RATE_LIMIT_HEARTBEAT_RETRY_MAX_ATTEMPTS) return null;
  const baseDelayMs = RATE_LIMIT_HEARTBEAT_RETRY_DELAY_MS;
  const sample = Math.min(1, Math.max(0, random()));
  const jitterMultiplier = 1 + (((sample * 2) - 1) * RATE_LIMIT_HEARTBEAT_RETRY_JITTER_RATIO);
  const delayMs = Math.max(1_000, Math.round(baseDelayMs * jitterMultiplier));
  return {
    attempt,
    baseDelayMs,
    delayMs,
    dueAt: new Date(now.getTime() + delayMs),
    maxAttempts: RATE_LIMIT_HEARTBEAT_RETRY_MAX_ATTEMPTS,
  };
}

async function resolveRunScopedMentionedSkillKeys(input: {
  db: Db;
  companyId: string;
  issueId: string | null;
}): Promise<string[]> {
  if (!input.issueId) return [];

  const issue = await input.db
    .select({
      title: issues.title,
      description: issues.description,
    })
    .from(issues)
    .where(and(eq(issues.id, input.issueId), eq(issues.companyId, input.companyId)))
    .then((rows) => rows[0] ?? null);
  if (!issue) return [];

  const comments = await input.db
    .select({ body: issueComments.body })
    .from(issueComments)
    .where(
      and(
        eq(issueComments.issueId, input.issueId),
        eq(issueComments.companyId, input.companyId),
        isNull(issueComments.deletedAt),
      ),
    );
  const mentionedSkillIds = extractMentionedSkillIdsFromSources([
    issue.title,
    issue.description ?? "",
    ...comments.map((comment) => comment.body),
  ]);
  if (mentionedSkillIds.length === 0) return [];

  const skillRows = await input.db
    .select({
      id: companySkillsTable.id,
      key: companySkillsTable.key,
    })
    .from(companySkillsTable)
    .where(
      and(
        eq(companySkillsTable.companyId, input.companyId),
        inArray(companySkillsTable.id, mentionedSkillIds),
      ),
    );
  const skillKeyById = new Map(skillRows.map((row) => [row.id, row.key]));
  return mentionedSkillIds
    .map((skillId) => skillKeyById.get(skillId) ?? null)
    .filter((skillKey): skillKey is string => Boolean(skillKey));
}

function leaseReleaseStatusForRunStatus(
  status: string | null | undefined,
): Extract<EnvironmentLeaseStatus, "released" | "expired" | "failed"> {
  if (status === "cancelled") return "expired";
  return status === "failed" || status === "timed_out" ? "failed" : "released";
}

export function applyPersistedExecutionWorkspaceConfig(input: {
  config: Record<string, unknown>;
  workspaceConfig: ExecutionWorkspaceConfig | null;
  mode: ReturnType<typeof resolveExecutionWorkspaceMode>;
}) {
  const nextConfig = { ...input.config };

  if (input.mode !== "agent_default") {
    if (input.workspaceConfig?.workspaceRuntime === null) {
      delete nextConfig.workspaceRuntime;
    } else if (input.workspaceConfig?.workspaceRuntime) {
      nextConfig.workspaceRuntime = { ...input.workspaceConfig.workspaceRuntime };
    }
    if (input.workspaceConfig?.desiredState === null) {
      delete nextConfig.desiredState;
    } else if (input.workspaceConfig?.desiredState) {
      nextConfig.desiredState = input.workspaceConfig.desiredState;
    }
    if (input.workspaceConfig?.serviceStates === null) {
      delete nextConfig.serviceStates;
    } else if (input.workspaceConfig?.serviceStates) {
      nextConfig.serviceStates = { ...input.workspaceConfig.serviceStates };
    }
  }

  if (input.workspaceConfig && input.mode === "isolated_workspace") {
    const nextStrategy = parseObject(nextConfig.workspaceStrategy);
    if (input.workspaceConfig.provisionCommand === null) delete nextStrategy.provisionCommand;
    else nextStrategy.provisionCommand = input.workspaceConfig.provisionCommand;
    if (input.workspaceConfig.teardownCommand === null) delete nextStrategy.teardownCommand;
    else nextStrategy.teardownCommand = input.workspaceConfig.teardownCommand;
    nextConfig.workspaceStrategy = nextStrategy;
  }

  return nextConfig;
}

export function mergeExecutionWorkspaceMetadataForPersistence(input: {
  existingMetadata: Record<string, unknown> | null | undefined;
  source: string;
  createdByRuntime: boolean;
  configSnapshot: Record<string, unknown> | null;
  shouldReuseExisting: boolean;
  shouldRefreshConfigSnapshot?: boolean;
  workspaceConfigMetadata?: EffectiveRunWorkspaceConfigMetadata | null;
  baseRef: string | null | undefined;
  baseRefSha: string | null | undefined;
}) {
  const base = {
    ...(input.existingMetadata ?? {}),
    source: input.source,
    createdByRuntime: input.createdByRuntime,
  } as Record<string, unknown>;

  const existingSnapshot = parseObject(base.baseRefSnapshot);
  if (
    typeof existingSnapshot.resolvedSha !== "string"
    && input.baseRefSha
  ) {
    base.baseRefSnapshot = {
      baseRef: input.baseRef ?? null,
      resolvedSha: input.baseRefSha,
    };
  }

  if (input.workspaceConfigMetadata) {
    base[WORKSPACE_CONFIG_FINGERPRINT_METADATA_KEY] = {
      version: input.workspaceConfigMetadata.version,
      workspaceHash: input.workspaceConfigMetadata.fingerprint,
      categories: input.workspaceConfigMetadata.categories,
      categoryFingerprints: input.workspaceConfigMetadata.categoryFingerprints,
      lastEvaluatedAt: input.workspaceConfigMetadata.evaluatedAt,
    };
  }

  if ((input.shouldReuseExisting && !input.shouldRefreshConfigSnapshot) || !input.configSnapshot) {
    return base;
  }

  return mergeExecutionWorkspaceConfig(base, input.configSnapshot);
}

export function stripWorkspaceRuntimeFromExecutionRunConfig(config: Record<string, unknown>) {
  const nextConfig = { ...config };
  delete nextConfig.workspaceRuntime;
  return nextConfig;
}

function buildExecutionWorkspaceConfigSnapshot(
  config: Record<string, unknown>,
  environmentId?: string | null,
): Partial<ExecutionWorkspaceConfig> | null {
  const strategy = parseObject(config.workspaceStrategy);
  const snapshot: Partial<ExecutionWorkspaceConfig> = {};
  // Persist the resolved environment onto the workspace so reused sessions stay on the
  // environment they were created against until the workspace itself is recreated/reset.
  const hasExplicitEnvironmentSelection = environmentId !== undefined;

  if (hasExplicitEnvironmentSelection) {
    snapshot.environmentId = environmentId ?? null;
  }

  if ("workspaceStrategy" in config) {
    snapshot.provisionCommand = typeof strategy.provisionCommand === "string" ? strategy.provisionCommand : null;
    snapshot.teardownCommand = typeof strategy.teardownCommand === "string" ? strategy.teardownCommand : null;
  }

  if ("workspaceRuntime" in config) {
    const workspaceRuntime = parseObject(config.workspaceRuntime);
    snapshot.workspaceRuntime = Object.keys(workspaceRuntime).length > 0 ? workspaceRuntime : null;
  }
  if ("desiredState" in config) {
    snapshot.desiredState =
      config.desiredState === "running" || config.desiredState === "stopped" || config.desiredState === "manual"
        ? config.desiredState
        : null;
  }
  if ("serviceStates" in config) {
    const serviceStates = parseObject(config.serviceStates);
    snapshot.serviceStates = Object.keys(serviceStates).length > 0
      ? Object.fromEntries(
          Object.entries(serviceStates).filter(([, state]) =>
            state === "running" || state === "stopped" || state === "manual"
          ),
        ) as ExecutionWorkspaceConfig["serviceStates"]
      : null;
  }

  const hasSnapshot = Object.values(snapshot).some((value) => {
    if (value === null) return false;
    if (typeof value === "object") return Object.keys(value).length > 0;
    return true;
  }) || hasExplicitEnvironmentSelection;
  return hasSnapshot ? snapshot : null;
}

export function stripHostWorkspaceProvisionForLowTrustSandbox(input: {
  config: Record<string, unknown>;
  trustPreset: TrustPresetResolution;
  selectedEnvironmentDriver: string | null | undefined;
}): Record<string, unknown> {
  if (input.trustPreset.kind !== "low_trust_review") return input.config;
  if (input.selectedEnvironmentDriver !== "sandbox") return input.config;

  const workspaceStrategy = parseObject(input.config.workspaceStrategy);
  if (typeof workspaceStrategy.provisionCommand !== "string") return input.config;

  const nextWorkspaceStrategy = { ...workspaceStrategy };
  delete nextWorkspaceStrategy.provisionCommand;

  return {
    ...input.config,
    workspaceStrategy: nextWorkspaceStrategy,
  };
}

export async function preflightLowTrustWorkspaceIsolation(input: {
  db?: Db;
  trustPreset: TrustPresetResolution;
  isolatedWorkspacesEnabled: boolean;
  effectiveExecutionWorkspaceMode: string | null | undefined;
  issue: { companyId: string; id?: string | null; projectId?: string | null } | null;
  resolveSelectedEnvironmentDriver: () => Promise<string | null | undefined>;
}): Promise<string | null> {
  if (input.trustPreset.kind !== "denied" && input.trustPreset.kind !== "low_trust_review") {
    return null;
  }

  const selectedEnvironmentDriver =
    input.trustPreset.kind === "low_trust_review"
      ? await input.resolveSelectedEnvironmentDriver()
      : null;

  await assertLowTrustWorkspaceIsolation({
    db: input.db,
    resolution: input.trustPreset,
    isolatedWorkspacesEnabled: input.isolatedWorkspacesEnabled,
    effectiveExecutionWorkspaceMode: input.effectiveExecutionWorkspaceMode,
    selectedEnvironmentDriver,
    issue: input.issue,
  });

  return selectedEnvironmentDriver ?? null;
}

export async function resolveWorkspaceAfterLowTrustPreflight<TWorkspace>(input: {
  db?: Db;
  trustPreset: TrustPresetResolution;
  isolatedWorkspacesEnabled: boolean;
  effectiveExecutionWorkspaceMode: string | null | undefined;
  issue: { companyId: string; id?: string | null; projectId?: string | null } | null;
  resolveSelectedEnvironmentDriver: () => Promise<string | null | undefined>;
  resolveWorkspace: () => Promise<TWorkspace>;
}): Promise<{ selectedEnvironmentDriver: string | null; workspace: TWorkspace }> {
  const selectedEnvironmentDriver = await preflightLowTrustWorkspaceIsolation({
    db: input.db,
    trustPreset: input.trustPreset,
    isolatedWorkspacesEnabled: input.isolatedWorkspacesEnabled,
    effectiveExecutionWorkspaceMode: input.effectiveExecutionWorkspaceMode,
    issue: input.issue,
    resolveSelectedEnvironmentDriver: input.resolveSelectedEnvironmentDriver,
  });

  return {
    selectedEnvironmentDriver,
    workspace: await input.resolveWorkspace(),
  };
}

function deriveRepoNameFromRepoUrl(repoUrl: string | null): string | null {
  const trimmed = repoUrl?.trim() ?? "";
  if (!trimmed) return null;
  try {
    const parsed = new URL(trimmed);
    const cleanedPath = parsed.pathname.replace(/\/+$/, "");
    const repoName = cleanedPath.split("/").filter(Boolean).pop()?.replace(/\.git$/i, "") ?? "";
    return repoName || null;
  } catch {
    return null;
  }
}

async function ensureManagedProjectWorkspace(input: {
  companyId: string;
  projectId: string;
  repoUrl: string | null;
}): Promise<{ cwd: string; warning: string | null }> {
  const cwd = resolveManagedProjectWorkspaceDir({
    companyId: input.companyId,
    projectId: input.projectId,
    repoName: deriveRepoNameFromRepoUrl(input.repoUrl),
  });
  await fs.mkdir(path.dirname(cwd), { recursive: true });
  const stats = await fs.stat(cwd).catch(() => null);

  if (!input.repoUrl) {
    if (!stats) {
      await fs.mkdir(cwd, { recursive: true });
    }
    return { cwd, warning: null };
  }

  const gitDirExists = await fs
    .stat(path.resolve(cwd, ".git"))
    .then((entry) => entry.isDirectory())
    .catch(() => false);
  if (gitDirExists) {
    return { cwd, warning: null };
  }

  if (stats) {
    const entries = await fs.readdir(cwd).catch(() => []);
    if (entries.length > 0) {
      return {
        cwd,
        warning: `Managed workspace path "${cwd}" already exists but is not a git checkout. Using it as-is.`,
      };
    }
    await fs.rm(cwd, { recursive: true, force: true });
  }

  try {
    await execFile("git", ["clone", input.repoUrl, cwd], {
      env: sanitizeRuntimeServiceBaseEnv(process.env),
      timeout: MANAGED_WORKSPACE_GIT_CLONE_TIMEOUT_MS,
    });
    return { cwd, warning: null };
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to prepare managed checkout for "${input.repoUrl}" at "${cwd}": ${reason}`);
  }
}

type WorkspaceValidationFailureLike = WorkspaceValidationFailure | {
  code: typeof WORKSPACE_VALIDATION_FAILURE_CODE;
  resultJson: Record<string, unknown>;
};

function isWorkspaceValidationFailure(error: unknown): error is WorkspaceValidationFailureLike {
  if (error instanceof WorkspaceValidationFailure) return true;
  const maybe = error as { code?: unknown; resultJson?: unknown } | null;
  return Boolean(
    maybe &&
      maybe.code === WORKSPACE_VALIDATION_FAILURE_CODE &&
      maybe.resultJson &&
      typeof maybe.resultJson === "object" &&
      !Array.isArray(maybe.resultJson),
  );
}

function isWorkspaceValidationFailedRun(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode"> | null | undefined,
) {
  return run?.errorCode === WORKSPACE_VALIDATION_FAILURE_CODE;
}

function readWorkspaceValidationPayloadFromRun(
  run: Pick<typeof heartbeatRuns.$inferSelect, "resultJson"> | null | undefined,
) {
  return parseObject(parseObject(run?.resultJson).workspaceValidation);
}

function stableStringifyForFingerprint(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((entry) => stableStringifyForFingerprint(entry)).join(",")}]`;
  }
  if (value && typeof value === "object") {
    const rec = value as Record<string, unknown>;
    return `{${Object.keys(rec).sort().map((key) => `${JSON.stringify(key)}:${stableStringifyForFingerprint(rec[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function fingerprintFinalizeWorkspaceBranchValidation(input: {
  issueId: string | null;
  executionWorkspaceId: string;
  inspection: ReturnType<typeof formatManagedGitWorktreeBranchInspection>;
}) {
  const digest = createHash("sha256")
    .update(stableStringifyForFingerprint({
      version: 1,
      reason: "git_worktree_branch_incoherence",
      issueId: input.issueId,
      executionWorkspaceId: input.executionWorkspaceId,
      worktreePath: input.inspection.worktreePath ? path.resolve(input.inspection.worktreePath) : null,
      repoRoot: input.inspection.repoRoot ? path.resolve(input.inspection.repoRoot) : null,
      expectedBranchName: input.inspection.expectedBranchName,
      actualBranchName: input.inspection.actualBranchName,
      reasonCode: input.inspection.reasonCode,
    }))
    .digest("hex");
  return `workspace_finalize_branch_mismatch:v1:sha256:${digest}`;
}

function isConfigurationIncompleteFailure(error: unknown): error is ConfigurationIncompleteFailure {
  return error instanceof ConfigurationIncompleteFailure;
}

export function isConfigurationIncompleteFailedRun(
  run: Pick<typeof heartbeatRuns.$inferSelect, "errorCode"> | null | undefined,
) {
  return run?.errorCode === CONFIGURATION_INCOMPLETE_FAILURE_CODE || run?.errorCode === "model_not_found";
}

async function hasGitMetadata(cwd: string | null | undefined) {
  const normalized = readNonEmptyString(cwd);
  if (!normalized) return false;
  return fs
    .lstat(path.resolve(normalized, ".git"))
    .then((entry) => entry.isDirectory() || entry.isFile())
    .catch(() => false);
}

async function isGitCheckout(cwd: string | null | undefined) {
  const normalized = readNonEmptyString(cwd);
  if (!normalized) return false;
  return execFile("git", ["rev-parse", "--show-toplevel"], { cwd: normalized })
    .then((result) => Boolean(readNonEmptyString(result.stdout)))
    .catch(() => false);
}

async function pathIsAbsent(cwd: string): Promise<boolean> {
  try {
    await fs.lstat(cwd);
    return false;
  } catch (error: unknown) {
    return (error as NodeJS.ErrnoException)?.code === "ENOENT";
  }
}

// Unlike isGitCheckout(), this does not fail open: a probe error that isn't
// positively identifiable as "cwd is not a git checkout" (missing directory,
// or git's own "not a git repository" fatal) is treated as "could be a
// checkout". That covers the storage-layer failures (permission denied,
// stale handle, I/O error, timeout) BLO-18147 exists to guard against —
// those must reject dispatch, not silently wave it through because the probe
// itself couldn't complete. Uses try/await rather than .then/.catch because
// execFile can throw synchronously (e.g. ENOTDIR when cwd is not a
// directory) before returning a promise to chain onto.
async function probeGitCheckoutStateStrict(
  cwd: string,
): Promise<"checkout" | "not_a_checkout" | "indeterminate"> {
  try {
    const result = await execFile("git", ["rev-parse", "--show-toplevel"], {
      cwd,
      timeout: strictGitCheckoutProbeTimeoutMs(),
    });
    return readNonEmptyString(result.stdout) ? "checkout" : "indeterminate";
  } catch (error: unknown) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") {
      return await pathIsAbsent(cwd) ? "not_a_checkout" : "indeterminate";
    }
    const stderr = typeof (error as { stderr?: unknown })?.stderr === "string"
      ? (error as { stderr: string }).stderr
      : "";
    if (/not a git repository/i.test(stderr)) return "not_a_checkout";
    return "indeterminate";
  }
}

function sameResolvedPath(left: string | null | undefined, right: string | null | undefined) {
  const leftPath = readNonEmptyString(left);
  const rightPath = readNonEmptyString(right);
  if (!leftPath || !rightPath) return false;
  return path.resolve(leftPath) === path.resolve(rightPath);
}

async function hasGitPushRemote(cwd: string | null | undefined) {
  const normalized = readNonEmptyString(cwd);
  if (!normalized) return false;
  const remoteNames = await execFile("git", ["remote"], { cwd: normalized })
    .then((result) =>
      result.stdout
        .split(/\r?\n/)
        .map((value) => value.trim())
        .filter((value) => value.length > 0),
    )
    .catch(() => []);

  for (const remoteName of remoteNames) {
    const pushUrl = await execFile("git", ["remote", "get-url", "--push", remoteName], { cwd: normalized })
      .then((result) => readNonEmptyString(result.stdout))
      .catch(() => null);
    if (pushUrl) return true;
  }
  return false;
}

export async function assertGitWorktreeBaseWorkspaceReady(input: {
  requestedExecutionWorkspaceMode: ReturnType<typeof resolveExecutionWorkspaceMode>;
  config: Record<string, unknown>;
  issue: {
    id: string;
    identifier: string | null;
    projectId: string | null;
    projectWorkspaceId: string | null;
    executionWorkspaceId?: string | null;
    executionWorkspacePreference?: string | null;
  } | null;
  base: ExecutionWorkspaceInput;
}) {
  if (!input.issue) return;
  if (
    input.requestedExecutionWorkspaceMode !== "isolated_workspace" &&
    input.requestedExecutionWorkspaceMode !== "operator_branch"
  ) {
    return;
  }

  const strategyType = resolveEffectiveWorkspaceStrategyType(
    input.requestedExecutionWorkspaceMode,
    input.config,
  );
  if (strategyType !== "git_worktree") return;

  const issueLabel = input.issue.identifier ?? input.issue.id;
  const remediation = "This task needs a project / project workspace or a reusable execution workspace before it can run.";
  const fail = (reason: string, message: string, extra: Record<string, unknown> = {}) => {
    throw new WorkspaceValidationFailure(message, {
      workspaceValidation: {
        reason,
        issueId: input.issue!.id,
        issueIdentifier: input.issue!.identifier,
        issueProjectId: input.issue!.projectId,
        issueProjectWorkspaceId: input.issue!.projectWorkspaceId,
        issueExecutionWorkspaceId: input.issue!.executionWorkspaceId ?? null,
        issueExecutionWorkspacePreference: input.issue!.executionWorkspacePreference ?? null,
        requestedExecutionWorkspaceMode: input.requestedExecutionWorkspaceMode,
        workspaceStrategyType: strategyType,
        resolvedWorkspaceSource: input.base.source,
        resolvedProjectId: input.base.projectId,
        resolvedProjectWorkspaceId: input.base.workspaceId,
        resolvedWorkspaceCwd: input.base.baseCwd,
        ...extra,
      },
    });
  };

  if (input.base.source === "agent_home") {
    fail(
      "git_worktree_base_agent_home",
      `Issue ${issueLabel} requested ${input.requestedExecutionWorkspaceMode} with git_worktree, but no project or reusable execution workspace was resolved; refusing to create a git worktree from agent fallback cwd "${input.base.baseCwd}". ${remediation}`,
    );
  }

  if (!await isGitCheckout(input.base.baseCwd)) {
    fail(
      "git_worktree_base_not_git_checkout",
      `Issue ${issueLabel} requested ${input.requestedExecutionWorkspaceMode} with git_worktree, but base workspace "${input.base.baseCwd}" is not a git checkout. ${remediation}`,
    );
  }
}

export async function assertPushCapabilityCheckoutValid(input: {
  enabled: boolean;
  issue: {
    id: string;
    identifier: string | null;
  } | null;
  cwd: string | null | undefined;
}) {
  if (!input.enabled || !input.issue) return;
  const cwd = readNonEmptyString(input.cwd);
  if (!cwd) return;
  if (await hasGitPushRemote(cwd)) return;
  throw new WorkspaceValidationFailure(
    `Issue ${input.issue.identifier ?? input.issue.id} requested the GitHub PR workflow, but checkout "${cwd}" has no configured push remote. Bind the run to a writable repo checkout before dispatching the agent.`,
    {
      workspaceValidation: {
        reason: "missing_git_push_remote",
        issueId: input.issue.id,
        issueIdentifier: input.issue.identifier,
        executionWorkspaceCwd: cwd,
        requiredEnvKeys: [...PUSH_CAPABILITY_ENV_KEYS],
      },
    },
  );
}

export async function assertGitSensitiveAdapterWorkspaceValid(input: {
  adapterType: string;
  agentId: string;
  issue: {
    id: string;
    identifier: string | null;
    projectId: string | null;
    projectWorkspaceId: string | null;
  } | null;
  resolvedWorkspace: ResolvedWorkspaceForRun;
  executionWorkspace: RealizedExecutionWorkspace;
  persistedExecutionWorkspace: ExecutionWorkspace | null;
  executionTarget: unknown;
  k8sRunIsolation?: { isolationMode: "shared" | "run" | "workspace" } | null;
  environmentDriver?: string | null;
  leaseMetadata?: unknown;
}) {
  const k8sIssue = input.issue;
  const effectiveCwd = readNonEmptyString(input.executionWorkspace.cwd);
  const agentFallbackCwd = resolveDefaultAgentWorkspaceDir(input.agentId);
  // claude_k8s only clones the source checkout for per-run isolation. Key the
  // invariant on that effective source path, not the resolver label: a missing
  // project cwd can retain source="project_primary" while falling back here.
  //
  // BLO-18760: also cover source="agent_home" by label. That fallback now
  // resolves to a repo-less sibling dir rather than the persistent agent home,
  // so a path-only check would silently stop probing it. Probing it is the
  // point — the run is allowed through precisely *because* the probe confirms
  // "not_a_checkout", so if that directory ever acquires a `.git` we park
  // instead of handing the pod a clone source that can exit 128.
  const cwdIsAgentHomeFallback =
    effectiveCwd !== null && path.resolve(effectiveCwd) === path.resolve(agentFallbackCwd);
  // BLO-18760: the repo-less fallback source is a second directory that means
  // "this run resolved no project or session workspace". Every check keyed on
  // the agent-home path must treat it the same way, or the new path silently
  // escapes guards the old one was subject to.
  const cwdIsWorkspaceLessFallback =
    cwdIsAgentHomeFallback ||
    sameResolvedPath(effectiveCwd, resolveAgentEmptyWorkspaceSourceDir(input.agentId));
  // Gate on the *path*, not just the "agent_home" label, or a resumed run
  // walks straight past this probe. Only the first workspace-less run carries
  // source="agent_home": that cwd is then persisted into the task session, and
  // every resume resolves it back as source="task_session" (the session branch
  // accepts any existing dir that isUnsafeSessionWorkspaceCwd doesn't flag, and
  // it only flags system roots). A label-only gate would therefore probe run 1
  // and skip runs 2..n on the identical directory — so if it ever acquired a
  // `.git`, the resumed run would hand claude_k8s the unsafe clone source this
  // guard exists to refuse, breaking the BLO-18147 fail-closed invariant.
  if (
    K8S_GIT_SENSITIVE_ADAPTER_TYPES.has(input.adapterType) &&
    k8sIssue &&
    input.k8sRunIsolation?.isolationMode === "run" &&
    !input.resolvedWorkspace.realizationFailure &&
    effectiveCwd !== null &&
    (cwdIsWorkspaceLessFallback || input.resolvedWorkspace.source === "agent_home")
  ) {
    // Deliberately not isGitCheckout(): that helper fails open (any probe
    // error -> false), which would wave a storage-layer probe failure
    // straight through to dispatch and reproduce the exact exit-128 this
    // guard exists to prevent. Reject dispatch unless the probe positively
    // confirms the fallback cwd is NOT a git checkout.
    const gitProbeState = await probeGitCheckoutStateStrict(effectiveCwd);
    if (gitProbeState !== "not_a_checkout") {
      throw new WorkspaceValidationFailure(
        `Issue ${k8sIssue.identifier ?? k8sIssue.id} has no usable project or session execution workspace. Refusing to dispatch ${input.adapterType} run isolation from the fallback cwd "${effectiveCwd}" because its in-pod git bootstrap clones locally from this checkout and can exit 128 under storage pressure (git probe: ${gitProbeState}). This directory is expected to contain no git repository; remove the checkout under it, or bind a project or execution workspace to this issue, before retrying.`,
        {
          workspaceValidation: {
            reason: "k8s_agent_home_git_bootstrap_unsupported",
            adapterType: input.adapterType,
            issueId: k8sIssue?.id ?? null,
            issueIdentifier: k8sIssue?.identifier ?? null,
            resolvedWorkspaceSource: input.resolvedWorkspace.source,
            resolvedWorkspaceCwd: effectiveCwd,
            isolationMode: input.k8sRunIsolation.isolationMode,
            gitProbeState,
          },
        },
      );
    }
  }

  if (!GIT_SENSITIVE_LOCAL_ADAPTER_TYPES.has(input.adapterType)) return;

  const executionTargetKind = readNonEmptyString((input.executionTarget as { kind?: unknown } | null)?.kind) ?? "local";
  if (executionTargetKind !== "local") return;

  const issue = input.issue;
  if (!issue) return;
  if (input.resolvedWorkspace.realizationFailure) return;
  const resolvedWorkspace = input.resolvedWorkspace;

  const environmentDriver = readNonEmptyString(input.environmentDriver) ?? "local";
  const leaseMetadata = parseObject(input.leaseMetadata);
  const leaseProviderMetadata = parseObject(leaseMetadata.providerMetadata);
  const leaseRemoteCwd =
    readNonEmptyString(leaseMetadata.remoteCwd) ??
    readNonEmptyString(leaseProviderMetadata.remoteCwd);

  const persistedCwd = readNonEmptyString(input.persistedExecutionWorkspace?.cwd);
  const workspaceExpectation =
    Boolean(issue.projectWorkspaceId) ||
    Boolean(resolvedWorkspace.workspaceId) ||
    input.executionWorkspace.strategy === "git_worktree";

  const fail = (reason: string, message: string, extra: Record<string, unknown> = {}) => {
    throw new WorkspaceValidationFailure(message, {
      workspaceValidation: {
        reason,
        adapterType: input.adapterType,
        issueId: issue.id,
        issueIdentifier: issue.identifier,
        issueProjectId: issue.projectId,
        issueProjectWorkspaceId: issue.projectWorkspaceId,
        resolvedWorkspaceSource: resolvedWorkspace.source,
        resolvedProjectId: resolvedWorkspace.projectId,
        resolvedProjectWorkspaceId: resolvedWorkspace.workspaceId,
        resolvedWorkspaceCwd: resolvedWorkspace.cwd,
        executionWorkspaceCwd: effectiveCwd,
        executionWorkspaceStrategy: input.executionWorkspace.strategy,
        executionWorkspaceProjectId: input.executionWorkspace.projectId,
        executionWorkspaceProjectWorkspaceId: input.executionWorkspace.workspaceId,
        persistedExecutionWorkspaceId: input.persistedExecutionWorkspace?.id ?? null,
        persistedWorkspaceCwd: persistedCwd,
        persistedWorkspaceStrategy: input.persistedExecutionWorkspace?.strategyType ?? null,
        persistedProjectId: input.persistedExecutionWorkspace?.projectId ?? null,
        persistedProjectWorkspaceId: input.persistedExecutionWorkspace?.projectWorkspaceId ?? null,
        persistedProviderRef: input.persistedExecutionWorkspace?.providerRef ?? null,
        ...extra,
      },
    });
  };

  if (issue.projectWorkspaceId && !issue.projectId) {
    fail(
      "missing_project_id",
      `Issue ${issue.identifier ?? issue.id} is linked to a project workspace but has no project id; refusing to launch ${input.adapterType} from fallback cwd.`,
    );
  }

  if (!input.executionTarget && environmentDriver !== "local" && leaseRemoteCwd) return;

  if (workspaceExpectation && !input.persistedExecutionWorkspace) {
    fail(
      "missing_persisted_execution_workspace",
      `Issue ${issue.identifier ?? issue.id} requires a project execution workspace, but none was persisted before adapter launch.`,
    );
  }

  if (workspaceExpectation && !effectiveCwd) {
    fail(
      "missing_effective_cwd",
      `Issue ${issue.identifier ?? issue.id} expected a project workspace, but no adapter cwd was resolved before launch.`,
    );
  }

  if (
    input.persistedExecutionWorkspace &&
    effectiveCwd &&
    persistedCwd &&
    !sameResolvedPath(effectiveCwd, persistedCwd)
  ) {
    fail(
      "persisted_cwd_mismatch",
      `Issue ${issue.identifier ?? issue.id} resolved adapter cwd "${effectiveCwd}" but persisted execution workspace cwd is "${persistedCwd}".`,
    );
  }

  const expectedProjectWorkspaceId = issue.projectWorkspaceId ?? resolvedWorkspace.workspaceId ?? null;
  if (
    expectedProjectWorkspaceId &&
    input.persistedExecutionWorkspace &&
    !input.persistedExecutionWorkspace.projectWorkspaceId
  ) {
    fail(
      "persisted_workspace_missing_project_workspace_id",
      `Issue ${issue.identifier ?? issue.id} expected project workspace "${expectedProjectWorkspaceId}" but persisted execution workspace has no project workspace id.`,
    );
  }

  if (
    expectedProjectWorkspaceId &&
    input.persistedExecutionWorkspace?.projectWorkspaceId &&
    input.persistedExecutionWorkspace.projectWorkspaceId !== expectedProjectWorkspaceId
  ) {
    fail(
      "project_workspace_mismatch",
      `Issue ${issue.identifier ?? issue.id} expected project workspace "${expectedProjectWorkspaceId}" but persisted execution workspace points at "${input.persistedExecutionWorkspace.projectWorkspaceId}".`,
    );
  }

  if (workspaceExpectation && effectiveCwd && cwdIsWorkspaceLessFallback) {
    fail(
      "fallback_agent_home_cwd",
      `Issue ${issue.identifier ?? issue.id} expected a project workspace, but ${input.adapterType} would launch from agent fallback cwd "${effectiveCwd}".`,
    );
  }

  if (
    input.persistedExecutionWorkspace?.strategyType === "git_worktree" &&
    input.persistedExecutionWorkspace.providerRef &&
    effectiveCwd &&
    !sameResolvedPath(effectiveCwd, input.persistedExecutionWorkspace.providerRef)
  ) {
    fail(
      "git_worktree_provider_ref_mismatch",
      `Issue ${issue.identifier ?? issue.id} expected git worktree "${input.persistedExecutionWorkspace.providerRef}" but adapter cwd resolved to "${effectiveCwd}".`,
    );
  }

  if (workspaceExpectation && effectiveCwd && !await hasGitMetadata(effectiveCwd)) {
    fail(
      "missing_git_metadata",
      `Issue ${issue.identifier ?? issue.id} expected a git workspace for ${input.adapterType}, but "${effectiveCwd}" has no .git metadata.`,
    );
  }

  const expectedManagedBranchName =
    readNonEmptyString(input.executionWorkspace.branchName) ??
    readNonEmptyString(input.persistedExecutionWorkspace?.branchName);
  if (
    input.persistedExecutionWorkspace?.strategyType === "git_worktree" &&
    effectiveCwd &&
    expectedManagedBranchName
  ) {
    const inspection = await inspectManagedGitWorktreeBranch({
      worktreePath: effectiveCwd,
      expectedBranchName: expectedManagedBranchName,
    });
    if (!inspection.valid) {
      fail(
        "git_worktree_branch_mismatch",
        `Issue ${issue.identifier ?? issue.id} expected git worktree branch "${expectedManagedBranchName}" at "${effectiveCwd}", but ${inspection.reason ?? "the checked-out branch could not be verified"}.`,
        { managedGitWorktreeBranch: formatManagedGitWorktreeBranchInspection(inspection) },
      );
    }
  }
}

