function appendExcerpt(prev: string, chunk: string) {
  return appendWithByteCap(prev, chunk, MAX_EXCERPT_BYTES);
}

function truncateRunEventString(value: string) {
  if (value.length <= MAX_RUN_EVENT_PAYLOAD_STRING_CHARS) return value;
  const omittedChars = value.length - MAX_RUN_EVENT_PAYLOAD_STRING_CHARS;
  return `${value.slice(0, MAX_RUN_EVENT_PAYLOAD_STRING_CHARS)}\n[truncated ${omittedChars} chars]`;
}

function boundRunEventValue(value: unknown, depth: number, seen: WeakSet<object>): unknown {
  if (typeof value === "string") {
    return truncateRunEventString(value);
  }
  if (
    value === null
    || typeof value === "number"
    || typeof value === "boolean"
  ) {
    return value;
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  if (Array.isArray(value)) {
    if (depth >= MAX_RUN_EVENT_PAYLOAD_DEPTH) {
      return {
        _truncated: true,
        type: "array",
        originalLength: value.length,
      };
    }
    const bounded = value
      .slice(0, MAX_RUN_EVENT_PAYLOAD_ARRAY_ITEMS)
      .map((entry) => boundRunEventValue(entry, depth + 1, seen));
    if (value.length > MAX_RUN_EVENT_PAYLOAD_ARRAY_ITEMS) {
      bounded.push({
        _truncated: true,
        omittedItems: value.length - MAX_RUN_EVENT_PAYLOAD_ARRAY_ITEMS,
      });
    }
    return bounded;
  }
  if (typeof value !== "object" || value === undefined) {
    return null;
  }
  if (seen.has(value)) {
    return "[Circular]";
  }
  seen.add(value);
  const entries = Object.entries(value as Record<string, unknown>);
  if (depth >= MAX_RUN_EVENT_PAYLOAD_DEPTH) {
    const bounded = {
      _truncated: true,
      type: "object",
      keys: entries.map(([key]) => key).slice(0, 20),
    };
    seen.delete(value);
    return bounded;
  }

  const out: Record<string, unknown> = {};
  for (const [key, entryValue] of entries.slice(0, MAX_RUN_EVENT_PAYLOAD_OBJECT_KEYS)) {
    out[key] = boundRunEventValue(entryValue, depth + 1, seen);
  }
  if (entries.length > MAX_RUN_EVENT_PAYLOAD_OBJECT_KEYS) {
    out._truncated = true;
    out._omittedKeys = entries.length - MAX_RUN_EVENT_PAYLOAD_OBJECT_KEYS;
  }
  seen.delete(value);
  return out;
}

export function boundHeartbeatRunEventPayloadForStorage(payload: Record<string, unknown>): Record<string, unknown> {
  const bounded = boundRunEventValue(payload, 0, new WeakSet());
  return parseObject(bounded) ?? { _truncated: true };
}

function redactInlineBase64ImageData(chunk: string) {
  return chunk.replace(INLINE_BASE64_IMAGE_DATA_RE, (_match, prefix: string, data: string, suffix: string) =>
    `${prefix}[omitted base64 image data: ${data.length} chars]${suffix}`,
  );
}

export function compactRunLogChunk(chunk: string, maxChars = MAX_PERSISTED_LOG_CHUNK_CHARS) {
  const normalized = redactSensitiveText(redactInlineBase64ImageData(chunk));
  if (normalized.length <= maxChars) return normalized;

  const headChars = Math.max(0, Math.floor(maxChars * 0.6));
  const tailChars = Math.max(0, Math.floor(maxChars * 0.25));
  const omittedChars = Math.max(0, normalized.length - headChars - tailChars);
  const marker = `\n[paperclip truncated run log chunk: omitted ${omittedChars} chars]\n`;
  return `${normalized.slice(0, headChars)}${marker}${normalized.slice(normalized.length - tailChars)}`;
}

export function sanitizeRunLogChunkForStorage(
  chunk: string,
  currentUserRedactionOptions: Parameters<typeof redactCurrentUserText>[1],
  maxChars = MAX_PERSISTED_LOG_CHUNK_CHARS,
) {
  return compactRunLogChunk(redactCurrentUserText(chunk, currentUserRedactionOptions), maxChars);
}

const SYNTHETIC_KEEPALIVE_RUN_LOG_LINE_RE =
  /^\[paperclip\] keepalive\b.*\bjob\b.*\brunning \(\d+s since last output\)$/;

export function isSyntheticNonProgressRunLogChunk(chunk: string) {
  const lines = chunk
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  return lines.length > 0 && lines.every((line) => SYNTHETIC_KEEPALIVE_RUN_LOG_LINE_RE.test(line));
}

function normalizeHeartbeatIntervalSec(value: unknown, fallback: number) {
  const parsed = Math.floor(asNumber(value, fallback));
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(HEARTBEAT_POLICY_INTERVAL_MIN_SEC, Math.min(HEARTBEAT_POLICY_INTERVAL_MAX_SEC, parsed));
}

function normalizeHeartbeatCooldownSec(value: unknown, fallback: number) {
  const parsed = Math.floor(asNumber(value, fallback));
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(HEARTBEAT_POLICY_COOLDOWN_MIN_SEC, Math.min(HEARTBEAT_POLICY_COOLDOWN_MAX_SEC, parsed));
}

function normalizeMaxConcurrentRuns(value: unknown, fallback: number = HEARTBEAT_MAX_CONCURRENT_RUNS_DEFAULT) {
  const parsed = Math.floor(asNumber(value, fallback));
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(HEARTBEAT_POLICY_MAX_CONCURRENT_MIN, Math.min(HEARTBEAT_POLICY_MAX_CONCURRENT_MAX, parsed));
}

function normalizeOptionalNonNegativeInteger(value: unknown) {
  if (value === null || value === undefined || value === "") return null;
  const normalized = Math.floor(asNumber(value, 0));
  return normalized >= 0 ? normalized : null;
}

type ParsedHeartbeatPolicy = {
  preset: HeartbeatPreset | null;
  enabled: boolean;
  intervalSec: number;
  wakeOnDemand: boolean;
  cooldownSec: number;
  maxConcurrentRuns: number;
  /**
   * Default-off eligibility gate for external-lifecycle (k8s) concurrency
   * (BLO-15959). See {@link resolveExternalLifecycleConcurrency}.
   */
  concurrencyEnabled: boolean;
  idleAutoPauseAfter: number;
  adapterFailedAutoPauseAfter: number;
  skipTimerWhenNoActionableWork: boolean;
  maxDailyRuns: number | null;
  maxDailyCostCents: number | null;
};

export function resolveHeartbeatPolicyForRuntimeConfig(runtimeConfigValue: unknown): ParsedHeartbeatPolicy {
  const runtimeConfig = parseObject(runtimeConfigValue);
  const heartbeat = parseObject(runtimeConfig.heartbeat);
  const presetCandidate = readNonEmptyString(heartbeat.preset);
  const preset =
    presetCandidate && presetCandidate in HEARTBEAT_PRESET_CONFIGS
      ? (presetCandidate as HeartbeatPreset)
      : null;
  const presetConfig = preset ? HEARTBEAT_PRESET_CONFIGS[preset] : null;

  const enabled = asBoolean(heartbeat.enabled, presetConfig?.enabled ?? true);
  const intervalSec = normalizeHeartbeatIntervalSec(heartbeat.intervalSec, presetConfig?.intervalSec ?? 3600);
  const wakeOnDemand = asBoolean(
    heartbeat.wakeOnDemand ?? heartbeat.wakeOnAssignment ?? heartbeat.wakeOnOnDemand ?? heartbeat.wakeOnAutomation,
    presetConfig?.wakeOnDemand ?? true,
  );
  const maxConcurrentRuns = normalizeMaxConcurrentRuns(
    heartbeat.maxConcurrentRuns,
    presetConfig?.maxConcurrentRuns ?? HEARTBEAT_MAX_CONCURRENT_RUNS_DEFAULT,
  );
  // BLO-15959: deliberately NOT influenced by preset — a preset tunes
  // interval/cooldown/maxConcurrentRuns, but opting an agent into actual
  // external-lifecycle concurrency must be an explicit, separate decision.
  const concurrencyEnabled = asBoolean(heartbeat.concurrencyEnabled, false);
  const desiredCooldownSec = normalizeHeartbeatCooldownSec(heartbeat.cooldownSec, presetConfig?.cooldownSec ?? 0);
  const cooldownSec = enabled ? Math.min(desiredCooldownSec, intervalSec) : desiredCooldownSec;
  const idleAutoPauseAfter = Math.max(0, asNumber(heartbeat.idleAutoPauseAfter, 0));
  const adapterFailedAutoPauseAfter = Math.max(0, asNumber(heartbeat.adapterFailedAutoPauseAfter, 0));
  const skipTimerWhenNoActionableWork = asBoolean(heartbeat.skipTimerWhenNoActionableWork, false);
  const maxDailyRuns = normalizeOptionalNonNegativeInteger(heartbeat.maxDailyRuns);
  const maxDailyCostCents = normalizeOptionalNonNegativeInteger(heartbeat.maxDailyCostCents);

  return {
    preset,
    enabled,
    intervalSec,
    wakeOnDemand,
    cooldownSec,
    maxConcurrentRuns,
    concurrencyEnabled,
    idleAutoPauseAfter,
    adapterFailedAutoPauseAfter,
    skipTimerWhenNoActionableWork,
    maxDailyRuns,
    maxDailyCostCents,
  };
}

/**
 * Resolve the admitted concurrency ceiling for external-lifecycle (k8s)
 * adapters (BLO-15959). This is a separate, default-off eligibility gate on
 * top of the per-agent `maxConcurrentRuns` policy value:
 *
 * - Disabled (default): every external-lifecycle agent is held to exactly
 *   one concurrent run, regardless of what `maxConcurrentRuns` is configured
 *   to. This is the fallback/rollback posture — flipping the flag back off
 *   restores it immediately with no migration or data repair, because it is
 *   computed fresh from policy on every dispatch rather than persisted.
 * - Enabled: the effective ceiling is `min(maxConcurrentRuns,
 *   EXTERNAL_LIFECYCLE_SLOT_CAPACITY)` — the operator's configured value,
 *   further bounded by the operational slot ceiling so a high
 *   `maxConcurrentRuns` cannot alone exceed what the cluster is provisioned
 *   for one agent.
 *
 * Serialization of shared-workspace / same-isolation-key runs is a distinct,
 * already-enforced invariant (the unique active-isolation-writer constraint
 * in external_runtime_reservations, BLO-15956/BLO-15958) and is unaffected by
 * this gate either way.
 */
export function resolveExternalLifecycleConcurrency(
  policy: Pick<ParsedHeartbeatPolicy, "concurrencyEnabled" | "maxConcurrentRuns">,
): { effectiveMaxConcurrentRuns: number; concurrencyEnabled: boolean } {
  if (!policy.concurrencyEnabled) {
    return { effectiveMaxConcurrentRuns: 1, concurrencyEnabled: false };
  }
  return {
    effectiveMaxConcurrentRuns: Math.max(
      1,
      Math.min(policy.maxConcurrentRuns, EXTERNAL_LIFECYCLE_SLOT_CAPACITY),
    ),
    concurrencyEnabled: true,
  };
}

/**
 * Decide whether the heartbeat cooldown should suppress a wakeup.
 *
 * The cooldown is an anti-thrash guard for the periodic *timer* self-wake loop.
 * It must NOT apply to externally-triggered demand wakes (PR opened/review/
 * @mention; any source other than "timer"): a demand wake skipped on cooldown
 * is terminal — agent_wakeup_requests has no defer/schedule column, so the
 * skip is never re-dispatched — which silently drops discrete work. A PR opened
 * while the agent is within the cooldown of an unrelated run would otherwise
 * never be reviewed (PEN-825 / BLO-9089). Demand backpressure is already
 * provided by event coalescing (idempotencyKey), maxConcurrentRuns, and the
 * issue-execution lock; the cooldown is not the mechanism for it.
 *
 * Pure (injectable `now`) so the gate logic is unit-testable without a DB.
 */
export function isHeartbeatCooldownActive(args: {
  source: string;
  cooldownSec: number;
  lastHeartbeatAt: Date | string | number | null | undefined;
  now?: number;
}): { active: boolean; remainingSec: number } {
  const { source, cooldownSec, lastHeartbeatAt } = args;
  // Only the periodic timer loop is throttled; demand wakes always pass through.
  if (source !== "timer") return { active: false, remainingSec: 0 };
  if (!(cooldownSec > 0) || lastHeartbeatAt == null) return { active: false, remainingSec: 0 };
  const now = args.now ?? Date.now();
  const elapsedMs = now - new Date(lastHeartbeatAt).getTime();
  const cooldownMs = cooldownSec * 1000;
  if (elapsedMs >= cooldownMs) return { active: false, remainingSec: 0 };
  return { active: true, remainingSec: Math.ceil((cooldownMs - elapsedMs) / 1000) };
}

interface WakeupOptions {
  source?: "timer" | "assignment" | "on_demand" | "automation";
  triggerDetail?: "manual" | "ping" | "callback" | "system";
  reason?: string | null;
  payload?: Record<string, unknown> | null;
  idempotencyKey?: string | null;
  requestedByActorType?: "user" | "agent" | "system";
  requestedByActorId?: string | null;
  contextSnapshot?: Record<string, unknown>;
}

