  async function performIssueMonitorRecovery(input: {
    claimed: IssueMonitorDispatchRow;
    scheduledAtIso: string;
    nextAttemptCount: number;
    clearReason: IssueExecutionMonitorClearReason;
    recoveryPolicy: IssueExecutionMonitorRecoveryPolicy;
    monitor: IssueExecutionMonitorPolicy | null;
    actorType: "user" | "agent" | "system";
    actorId: string;
    agentId: string | null;
    runId: string | null;
    activitySource: "manual" | "scheduled";
  }) {
    const details = monitorRecoveryDetails({
      claimed: input.claimed,
      scheduledAtIso: input.scheduledAtIso,
      nextAttemptCount: input.nextAttemptCount,
      clearReason: input.clearReason,
      recoveryPolicy: input.recoveryPolicy,
      monitor: input.monitor,
      source: input.activitySource,
    });

    if (input.recoveryPolicy === "create_recovery_issue") {
      let recoveryIssue = await findOpenIssueMonitorRecoveryIssue(input.claimed);
      if (!recoveryIssue) {
        recoveryIssue = await issuesSvc.create(input.claimed.companyId, {
          title: `Recover external-service monitor for ${input.claimed.identifier ?? input.claimed.title}`,
          description: monitorRecoveryComment({
            issue: input.claimed,
            clearReason: input.clearReason,
            recoveryPolicy: input.recoveryPolicy,
            nextAttemptCount: input.nextAttemptCount,
          }),
          status: "todo",
          priority: "high",
          parentId: input.claimed.id,
          projectId: input.claimed.projectId,
          goalId: input.claimed.goalId,
          assigneeAgentId: input.claimed.assigneeAgentId,
          assigneeAdapterOverrides: recoveryAssigneeAdapterOverrides("status_only"),
          originKind: RECOVERY_ORIGIN_KINDS.strandedIssueRecovery,
          originId: input.claimed.id,
          originFingerprint: `issue_monitor:${input.clearReason}`,
          billingCode: input.claimed.billingCode,
        });
      }

      if (recoveryIssue.assigneeAgentId) {
        await enqueueWakeup(recoveryIssue.assigneeAgentId, {
          source: "automation",
          triggerDetail: "system",
          reason: "issue_monitor_recovery_issue",
          idempotencyKey: `issue-monitor-recovery-issue:${input.claimed.id}:${input.clearReason}:${input.scheduledAtIso}`,
          payload: withRecoveryModelProfileHint({ issueId: recoveryIssue.id, sourceIssueId: input.claimed.id }, "status_only"),
          requestedByActorType: input.actorType,
          requestedByActorId: input.actorId,
          contextSnapshot: withRecoveryModelProfileHint({
            issueId: recoveryIssue.id,
            sourceIssueId: input.claimed.id,
            source: "issue.monitor.recovery_issue",
            wakeReason: "issue_monitor_recovery_issue",
          }, "status_only"),
        });
      }

      await logActivity(db, {
        companyId: input.claimed.companyId,
        actorType: input.actorType,
        actorId: input.actorId,
        agentId: input.agentId,
        runId: input.runId,
        action: "issue.monitor_recovery_issue_created",
        entityType: "issue",
        entityId: input.claimed.id,
        details: {
          ...details,
          recoveryIssueId: recoveryIssue.id,
          recoveryIdentifier: recoveryIssue.identifier,
        },
      });
      return;
    }

    if (input.recoveryPolicy === "escalate_to_board") {
      await db.insert(issueComments).values({
        companyId: input.claimed.companyId,
        issueId: input.claimed.id,
        body: monitorRecoveryComment({
          issue: input.claimed,
          clearReason: input.clearReason,
          recoveryPolicy: input.recoveryPolicy,
          nextAttemptCount: input.nextAttemptCount,
        }),
      });

      await logActivity(db, {
        companyId: input.claimed.companyId,
        actorType: input.actorType,
        actorId: input.actorId,
        agentId: input.agentId,
        runId: input.runId,
        action: "issue.monitor_escalated_to_board",
        entityType: "issue",
        entityId: input.claimed.id,
        details,
      });
      return;
    }

    await enqueueWakeup(input.claimed.assigneeAgentId!, {
      source: "automation",
      triggerDetail: "system",
      reason: "issue_monitor_recovery",
      idempotencyKey: `issue-monitor-recovery:${input.claimed.id}:${input.clearReason}:${input.scheduledAtIso}`,
      payload: withRecoveryModelProfileHint({
        issueId: input.claimed.id,
        monitorAttemptCount: input.nextAttemptCount,
        monitorNotes: input.claimed.monitorNotes ?? null,
        clearReason: input.clearReason,
        serviceName: input.monitor?.serviceName ?? null,
        timeoutAt: input.monitor?.timeoutAt ?? null,
        maxAttempts: input.monitor?.maxAttempts ?? null,
      }, "status_only"),
      requestedByActorType: input.actorType,
      requestedByActorId: input.actorId,
      contextSnapshot: withRecoveryModelProfileHint({
        issueId: input.claimed.id,
        source: "issue.monitor.recovery",
        wakeReason: "issue_monitor_recovery",
        monitorAttemptCount: input.nextAttemptCount,
        monitorNotes: input.claimed.monitorNotes ?? null,
        clearReason: input.clearReason,
        serviceName: input.monitor?.serviceName ?? null,
        timeoutAt: input.monitor?.timeoutAt ?? null,
        maxAttempts: input.monitor?.maxAttempts ?? null,
      }, "status_only"),
    });

    await logActivity(db, {
      companyId: input.claimed.companyId,
      actorType: input.actorType,
      actorId: input.actorId,
      agentId: input.agentId,
      runId: input.runId,
      action: "issue.monitor_recovery_wake_queued",
      entityType: "issue",
      entityId: input.claimed.id,
      details,
    });
  }

  async function clearIssueMonitorAndRecover(input: {
    claimed: IssueMonitorDispatchRow;
    policy: ReturnType<typeof normalizeIssueExecutionPolicy>;
    scheduledAtIso: string;
    nextAttemptCount: number;
    clearReason: IssueExecutionMonitorClearReason;
    recoveryPolicy: IssueExecutionMonitorRecoveryPolicy;
    monitor: IssueExecutionMonitorPolicy | null;
    now: Date;
    actorType: "user" | "agent" | "system";
    actorId: string;
    agentId: string | null;
    runId: string | null;
    activitySource: "manual" | "scheduled";
  }) {
    await db
      .update(issues)
      .set({
        ...buildIssueMonitorClearedPatch({
          issue: input.claimed,
          policy: input.policy,
          clearReason: input.clearReason,
          clearedAt: input.now,
        }),
        updatedAt: input.now,
      })
      .where(eq(issues.id, input.claimed.id));

    await logActivity(db, {
      companyId: input.claimed.companyId,
      actorType: input.actorType,
      actorId: input.actorId,
      agentId: input.agentId,
      runId: input.runId,
      action: "issue.monitor_exhausted",
      entityType: "issue",
      entityId: input.claimed.id,
      details: monitorRecoveryDetails({
        claimed: input.claimed,
        scheduledAtIso: input.scheduledAtIso,
        nextAttemptCount: input.nextAttemptCount,
        clearReason: input.clearReason,
        recoveryPolicy: input.recoveryPolicy,
        monitor: input.monitor,
        source: input.activitySource,
      }),
    });

    await performIssueMonitorRecovery({
      claimed: input.claimed,
      scheduledAtIso: input.scheduledAtIso,
      nextAttemptCount: input.nextAttemptCount,
      clearReason: input.clearReason,
      recoveryPolicy: input.recoveryPolicy,
      monitor: input.monitor,
      actorType: input.actorType,
      actorId: input.actorId,
      agentId: input.agentId,
      runId: input.runId,
      activitySource: input.activitySource,
    });

    return { outcome: "skipped" as const, reason: input.clearReason };
  }

  async function dispatchClaimedIssueMonitor(
    claimed: IssueMonitorDispatchRow,
    input: {
      now: Date;
      source: "automation" | "on_demand";
      triggerDetail: "manual" | "system";
      wakeReason: string;
      actorType: "user" | "agent" | "system";
      actorId: string;
      agentId: string | null;
      runId: string | null;
      clearOnClientError: boolean;
      activitySource: "manual" | "scheduled";
    },
  ) {
    if (!claimed.assigneeAgentId || !claimed.monitorNextCheckAt) {
      throw conflict("Issue monitor is not ready to dispatch");
    }

    const scheduledAtIso = claimed.monitorNextCheckAt.toISOString();
    const nextAttemptCount = (claimed.monitorAttemptCount ?? 0) + 1;
    const policy = normalizeIssueExecutionPolicy(claimed.executionPolicy ?? null);
    const monitor = policy?.monitor ?? null;
    const clearReason = issueMonitorLimitClearReason({ monitor, nextAttemptCount, now: input.now });
    const recoveryPolicy = monitorRecoveryPolicy(monitor);
    const monitorMetadata = {
      serviceName: monitor?.serviceName ?? null,
      timeoutAt: monitor?.timeoutAt ?? null,
      maxAttempts: monitor?.maxAttempts ?? null,
      recoveryPolicy: monitor?.recoveryPolicy ?? null,
    };
    const executionState = claimed.status === "in_review"
      ? parseIssueExecutionState(claimed.executionState)
      : null;
    const currentParticipant = executionState?.status === "pending"
      ? executionState.currentParticipant
      : null;
    const reviewParticipantAgentId = currentParticipant?.type === "agent"
      ? currentParticipant.agentId
      : null;
    const isProviderQuotaReviewMonitor = monitor?.serviceName === PROVIDER_QUOTA_MONITOR_SERVICE_NAME &&
      Boolean(reviewParticipantAgentId);
    const targetAgentId = isProviderQuotaReviewMonitor
      ? reviewParticipantAgentId
      : claimed.assigneeAgentId;
    if (!targetAgentId) {
      throw conflict("Issue monitor has no agent target");
    }
    const wakeReason = isProviderQuotaReviewMonitor
      ? EXECUTION_REVIEW_PARTICIPANT_RECOVERY_WAKE_REASON
      : input.wakeReason;
    const reviewRecoveryContext = isProviderQuotaReviewMonitor
      ? {
          retryReason: EXECUTION_REVIEW_PARTICIPANT_RECOVERY_RETRY_REASON,
          currentStageId: executionState?.currentStageId ?? null,
          currentStageType: executionState?.currentStageType ?? null,
          reviewRecoveryInstruction:
            "The previous reviewer run reached provider quota. Resume this execution-review stage now that the quota wait has elapsed.",
        }
      : {};

    if (clearReason) {
      return clearIssueMonitorAndRecover({
        claimed,
        policy,
        scheduledAtIso,
        nextAttemptCount,
        clearReason,
        recoveryPolicy,
        monitor,
        now: input.now,
        actorType: input.actorType,
        actorId: input.actorId,
        agentId: input.agentId,
        runId: input.runId,
        activitySource: input.activitySource,
      });
    }

    try {
      await enqueueWakeup(targetAgentId, {
        source: input.source,
        triggerDetail: input.triggerDetail,
        reason: wakeReason,
        idempotencyKey: `issue-monitor:${claimed.id}:${scheduledAtIso}`,
        payload: {
          issueId: claimed.id,
          nextCheckAt: scheduledAtIso,
          monitorAttemptCount: nextAttemptCount,
          monitorNotes: claimed.monitorNotes ?? null,
          ...monitorMetadata,
          ...reviewRecoveryContext,
          source: input.activitySource,
        },
        requestedByActorType: input.actorType,
        requestedByActorId: input.actorId,
        contextSnapshot: {
          issueId: claimed.id,
          source: isProviderQuotaReviewMonitor ? "issue.execution_review_recovery" : "issue.monitor",
          wakeReason,
          nextCheckAt: scheduledAtIso,
          monitorAttemptCount: nextAttemptCount,
          monitorNotes: claimed.monitorNotes ?? null,
          ...monitorMetadata,
          ...reviewRecoveryContext,
          manualTrigger: input.activitySource === "manual",
        },
      });

      await db
        .update(issues)
        .set({
          ...buildIssueMonitorTriggeredPatch({
            issue: claimed,
            policy,
            triggeredAt: input.now,
          }),
          updatedAt: new Date(),
        })
        .where(eq(issues.id, claimed.id));

      await logActivity(db, {
        companyId: claimed.companyId,
        actorType: input.actorType,
        actorId: input.actorId,
        agentId: input.agentId,
        runId: input.runId,
        action: "issue.monitor_triggered",
        entityType: "issue",
        entityId: claimed.id,
        details: {
          identifier: claimed.identifier,
          nextCheckAt: scheduledAtIso,
          lastTriggeredAt: input.now.toISOString(),
          attemptCount: nextAttemptCount,
          notes: claimed.monitorNotes ?? null,
          ...monitorMetadata,
          source: input.activitySource,
        },
      });

      return { outcome: "triggered" as const };
    } catch (err) {
      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
        if (input.clearOnClientError) {
          await db
            .update(issues)
            .set({
              ...buildIssueMonitorClearedPatch({
                issue: claimed,
                policy,
                clearReason: "dispatch_skipped",
                clearedAt: input.now,
              }),
              updatedAt: new Date(),
            })
            .where(eq(issues.id, claimed.id));

          await logActivity(db, {
            companyId: claimed.companyId,
            actorType: input.actorType,
            actorId: input.actorId,
            agentId: input.agentId,
            runId: input.runId,
            action: "issue.monitor_skipped",
            entityType: "issue",
            entityId: claimed.id,
            details: {
              identifier: claimed.identifier,
              nextCheckAt: scheduledAtIso,
              attemptCount: nextAttemptCount,
              notes: claimed.monitorNotes ?? null,
              reason: err.message,
              source: input.activitySource,
            },
          });

          return { outcome: "skipped" as const, reason: err.message };
        }

        await db
          .update(issues)
          .set({
            monitorWakeRequestedAt: null,
            updatedAt: new Date(),
          })
          .where(eq(issues.id, claimed.id));
      } else {
        await db
          .update(issues)
          .set({
            monitorWakeRequestedAt: null,
            updatedAt: new Date(),
          })
          .where(eq(issues.id, claimed.id));
      }

      throw err;
    }
  }

  async function triggerIssueMonitor(issueId: string, input?: {
    now?: Date;
    actorType?: "user" | "agent" | "system";
    actorId?: string | null;
    agentId?: string | null;
    runId?: string | null;
    wakeReason?: string;
  }) {
    const now = input?.now ?? new Date();
    const actorType = input?.actorType ?? "system";
    const actorId = input?.actorId ?? (actorType === "system" ? "heartbeat_scheduler" : null);
    if (!actorId) {
      throw conflict("Issue monitor trigger requires an actor");
    }

    const issue = await db
      .select(issueMonitorDispatchColumns)
      .from(issues)
      .where(eq(issues.id, issueId))
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (!issue) {
      throw notFound("Issue not found");
    }
    if (!issue.monitorNextCheckAt) {
      throw conflict("Issue has no scheduled monitor");
    }
    if (!issue.assigneeAgentId || issue.assigneeUserId) {
      throw conflict("Issue monitor requires an agent assignee");
    }
    if (!["in_progress", "in_review"].includes(issue.status)) {
      throw conflict("Issue monitor can only run while the issue is in progress or in review");
    }

    const staleClaimThreshold = new Date(now.getTime() - 5 * 60 * 1000);
    const claimed = await db.transaction(async (tx) => {
      if (!await tryLockIssueMonitorQueue(tx)) return null;
      const [updated] = await tx
        .update(issues)
        .set({
          monitorWakeRequestedAt: now,
          updatedAt: now,
        })
        .where(
          and(
            eq(issues.id, issueId),
            sql`${issues.monitorNextCheckAt} is not null`,
            isNull(issues.assigneeUserId),
            sql`${issues.assigneeAgentId} is not null`,
            inArray(issues.status, ["in_progress", "in_review"]),
            or(
              isNull(issues.monitorWakeRequestedAt),
              lt(issues.monitorWakeRequestedAt, staleClaimThreshold),
            ),
          ),
        )
        .returning();
      return (updated ?? null) as IssueMonitorDispatchRow | null;
    });

    if (!claimed) {
      throw conflict("Issue monitor check is already in progress");
    }

    return dispatchClaimedIssueMonitor(claimed, {
      now,
      source: "on_demand",
      triggerDetail: "manual",
      wakeReason: input?.wakeReason ?? "issue_monitor_due",
      actorType,
      actorId,
      agentId: input?.agentId ?? null,
      runId: input?.runId ?? null,
      clearOnClientError: false,
      activitySource: "manual",
    });
  }

  async function tickDueIssueMonitors(now = new Date()) {
    const staleClaimThreshold = new Date(now.getTime() - 5 * 60 * 1000);
    const dueMonitors = await db
      .select(issueMonitorDispatchColumns)
      .from(issues)
      .innerJoin(companies, eq(companies.id, issues.companyId))
      .where(
        and(
          eq(companies.status, "active"),
          sql`${issues.monitorNextCheckAt} is not null`,
          lte(issues.monitorNextCheckAt, now),
          isNull(issues.assigneeUserId),
          sql`${issues.assigneeAgentId} is not null`,
          inArray(issues.status, ["in_progress", "in_review"]),
          or(
            isNull(issues.monitorWakeRequestedAt),
            lt(issues.monitorWakeRequestedAt, staleClaimThreshold),
          ),
        ),
      )
      .orderBy(asc(issues.monitorNextCheckAt), asc(issues.updatedAt), asc(issues.id))
      .limit(50);

    let triggered = 0;
    let skipped = 0;

    for (const due of dueMonitors) {
      const claimed = await db.transaction(async (tx) => {
        if (!await tryLockIssueMonitorQueue(tx)) return null;
        const [updated] = await tx
          .update(issues)
          .set({
            monitorWakeRequestedAt: now,
            updatedAt: now,
          })
          .where(
            and(
              eq(issues.id, due.id),
              sql`${issues.monitorNextCheckAt} is not null`,
              lte(issues.monitorNextCheckAt, now),
              isNull(issues.assigneeUserId),
              sql`${issues.assigneeAgentId} is not null`,
              inArray(issues.status, ["in_progress", "in_review"]),
              or(
                isNull(issues.monitorWakeRequestedAt),
                lt(issues.monitorWakeRequestedAt, staleClaimThreshold),
              ),
            ),
          )
          .returning();
        return (updated ?? null) as IssueMonitorDispatchRow | null;
      });

      if (!claimed) continue;

      try {
        const result = await dispatchClaimedIssueMonitor(claimed, {
          now,
          source: "automation",
          triggerDetail: "system",
          wakeReason: "issue_monitor_due",
          actorType: "system",
          actorId: "heartbeat_scheduler",
          agentId: null,
          runId: null,
          clearOnClientError: true,
          activitySource: "scheduled",
        });
        if (result.outcome === "triggered") triggered += 1;
        if (result.outcome === "skipped") skipped += 1;
      } catch (err) {
        logger.error({ err, issueId: claimed.id }, "issue monitor tick failed");
      }
    }

    return {
      checked: dueMonitors.length,
      triggered,
      skipped,
    };
  }

  async function getOldestRunForSession(agentId: string, sessionId: string) {
    return db
      .select({
        id: heartbeatRuns.id,
        createdAt: heartbeatRuns.createdAt,
      })
      .from(heartbeatRuns)
      .where(and(eq(heartbeatRuns.agentId, agentId), eq(heartbeatRuns.sessionIdAfter, sessionId)))
      .orderBy(asc(heartbeatRuns.createdAt), asc(heartbeatRuns.id))
      .limit(1)
      .then((rows) => rows[0] ?? null);
  }

  async function resolveNormalizedUsageForSession(input: {
    agentId: string;
    runId: string;
    sessionId: string | null;
    rawUsage: UsageTotals | null;
    usageBasis?: "per_run" | "session_cumulative" | null;
  }) {
    const { agentId, runId, sessionId, rawUsage, usageBasis } = input;
    // Adapters that declare per-run usage (e.g. the ACPX lane reports each
    // turn's tokens, not session totals) must not be session-delta'd, or
    // consecutive runs would be undercounted.
    if (!sessionId || !rawUsage || usageBasis === "per_run") {
      return {
        normalizedUsage: rawUsage,
        previousRawUsage: null as UsageTotals | null,
        derivedFromSessionTotals: false,
      };
    }

    const previousRun = await getLatestRunForSession(agentId, sessionId, { excludeRunId: runId });
    const previousRawUsage = readRawUsageTotals(previousRun?.usageJson);
    return {
      normalizedUsage: deriveNormalizedUsageDelta(rawUsage, previousRawUsage),
      previousRawUsage,
      derivedFromSessionTotals: previousRawUsage !== null,
    };
  }

  async function evaluateSessionCompaction(input: {
    agent: typeof agents.$inferSelect;
    sessionId: string | null;
    issueId: string | null;
    continuationSummaryBody?: string | null;
  }): Promise<SessionCompactionDecision> {
    const { agent, sessionId, issueId } = input;
    if (!sessionId) {
      return {
        rotate: false,
        reason: null,
        handoffMarkdown: null,
        previousRunId: null,
      };
    }

    const policy = parseSessionCompactionPolicy(agent);
    if (!policy.enabled || !hasSessionCompactionThresholds(policy)) {
      return {
        rotate: false,
        reason: null,
        handoffMarkdown: null,
        previousRunId: null,
      };
    }

    const fetchLimit = Math.max(
      policy.maxSessionRuns > 0 ? policy.maxSessionRuns + 1 : 0,
      policy.maxConsecutiveFailedResumes > 0 ? policy.maxConsecutiveFailedResumes : 0,
      4,
    );
    const runs = await db
      .select({
        id: heartbeatRuns.id,
        createdAt: heartbeatRuns.createdAt,
        usageJson: heartbeatRuns.usageJson,
        error: heartbeatRuns.error,
        status: heartbeatRuns.status,
        ...heartbeatRunListResultColumns,
      })
      .from(heartbeatRuns)
      .where(and(eq(heartbeatRuns.agentId, agent.id), eq(heartbeatRuns.sessionIdAfter, sessionId)))
      .orderBy(desc(heartbeatRuns.createdAt))
      .limit(fetchLimit);

    if (runs.length === 0) {
      return {
        rotate: false,
        reason: null,
        handoffMarkdown: null,
        previousRunId: null,
      };
    }

    const latestRun = runs[0] ?? null;
    const oldestRun =
      policy.maxSessionAgeHours > 0
        ? await getOldestRunForSession(agent.id, sessionId)
        : runs[runs.length - 1] ?? latestRun;
    const latestRawUsage = readRawUsageTotals(latestRun?.usageJson);
    const sessionAgeHours =
      latestRun && oldestRun
        ? Math.max(
            0,
            (new Date(latestRun.createdAt).getTime() - new Date(oldestRun.createdAt).getTime()) / (1000 * 60 * 60),
          )
        : 0;
    const consecutiveFailedOrZeroTokenResumes = countConsecutiveFailedOrZeroTokenResumes(runs);

    const reason = computeSessionCompactionReason({
      policy,
      runsCount: runs.length,
      latestRawInputTokens: latestRawUsage?.inputTokens ?? null,
      sessionAgeHours,
      consecutiveFailedOrZeroTokenResumes,
    });


    if (!reason || !latestRun) {
      return {
        rotate: false,
        reason: null,
        handoffMarkdown: null,
        previousRunId: latestRun?.id ?? null,
      };
    }

    const latestSummary = summarizeHeartbeatRunListResultJson({
      summary: latestRun?.resultSummary,
      result: latestRun?.resultResult,
      message: latestRun?.resultMessage,
      error: latestRun?.resultError,
      totalCostUsd: latestRun?.resultTotalCostUsd,
      costUsd: latestRun?.resultCostUsd,
      costUsdCamel: latestRun?.resultCostUsdCamel,
    });
    const latestTextSummary =
      readNonEmptyString(latestSummary?.summary) ??
      readNonEmptyString(latestSummary?.result) ??
      readNonEmptyString(latestSummary?.message) ??
      readNonEmptyString(latestRun.error);

    const handoffMarkdown = [
      "Paperclip session handoff:",
      `- Previous session: ${sessionId}`,
      issueId ? `- Issue: ${issueId}` : "",
      `- Rotation reason: ${reason}`,
      latestTextSummary ? `- Last run summary: ${latestTextSummary}` : "",
      input.continuationSummaryBody
        ? `- Issue continuation summary: ${input.continuationSummaryBody.slice(0, 1_500)}`
        : "",
      "Continue from the current task state. Rebuild only the minimum context you need.",
    ]
      .filter(Boolean)
      .join("\n");

    return {
      rotate: true,
      reason,
      handoffMarkdown,
      previousRunId: latestRun.id,
    };
  }

  async function resolveSessionBeforeForWakeup(
    agent: typeof agents.$inferSelect,
    taskKey: string | null,
  ) {
    if (taskKey) {
      const codec = getAdapterSessionCodec(agent.adapterType);
      const existingTaskSession = await getTaskSession(
        agent.companyId,
        agent.id,
        agent.adapterType,
        taskKey,
      );
      const parsedParams = normalizeSessionParams(
        codec.deserialize(existingTaskSession?.sessionParamsJson ?? null),
      );
      return truncateDisplayId(
        existingTaskSession?.sessionDisplayId ??
          (codec.getDisplayId ? codec.getDisplayId(parsedParams) : null) ??
          readNonEmptyString(parsedParams?.sessionId),
      );
    }

    const runtimeForRun = await getRuntimeState(agent.id);
    return runtimeForRun?.sessionId ?? null;
  }

  async function hasResolvableSessionWorkspaceCwd(sessionParams: Record<string, unknown> | null | undefined) {
    const cwd = readNonEmptyString(sessionParams?.cwd);
    if (!cwd || isUnsafeSessionWorkspaceCwd(cwd)) return false;
    return fs
      .stat(cwd)
      .then((stats) => stats.isDirectory())
      .catch(() => false);
  }

  async function hasResolvablePriorSessionWorkspaceForWake(input: {
    agent: typeof agents.$inferSelect;
    contextSnapshot: Record<string, unknown>;
    taskKey: string | null;
    explicitResumeSession: Awaited<ReturnType<typeof resolveExplicitResumeSessionOverride>> | null;
  }) {
    if (await hasResolvableSessionWorkspaceCwd(input.explicitResumeSession?.sessionParams)) return true;
    if (shouldResetTaskSessionForWake(input.contextSnapshot)) return false;
    if (!input.taskKey) return false;

    const codec = getAdapterSessionCodec(input.agent.adapterType);
    const taskSession = await getTaskSession(
      input.agent.companyId,
      input.agent.id,
      input.agent.adapterType,
      input.taskKey,
    );
    const taskSessionParams = normalizeResumeParamsForAdapter(
      input.agent.adapterType,
      codec.deserialize(taskSession?.sessionParamsJson ?? null),
    );
    return hasResolvableSessionWorkspaceCwd(taskSessionParams);
  }

  async function resolveExplicitResumeSessionOverride(
    agent: typeof agents.$inferSelect,
    payload: Record<string, unknown> | null,
    taskKey: string | null,
  ) {
    const resumeFromRunId = readNonEmptyString(payload?.resumeFromRunId);
    if (!resumeFromRunId) return null;

    const resumeRun = await db
      .select({
        id: heartbeatRuns.id,
        contextSnapshot: heartbeatRuns.contextSnapshot,
        resultJson: heartbeatRuns.resultJson,
        sessionIdBefore: heartbeatRuns.sessionIdBefore,
        sessionIdAfter: heartbeatRuns.sessionIdAfter,
      })
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.id, resumeFromRunId),
          eq(heartbeatRuns.companyId, agent.companyId),
          eq(heartbeatRuns.agentId, agent.id),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!resumeRun) return null;

    const resumeContext = parseObject(resumeRun.contextSnapshot);
    const resumeTaskKey = deriveTaskKey(resumeContext, null) ?? taskKey;
    const resumeTaskSession = resumeTaskKey
      ? await getTaskSession(agent.companyId, agent.id, agent.adapterType, resumeTaskKey)
      : null;
    const sessionCodec = getAdapterSessionCodec(agent.adapterType);
    const resumeRunResult = parseObject(resumeRun.resultJson);
    const resumeRunSessionId = requiresCanonicalSessionIds(agent.adapterType)
      ? readNonEmptyString(resumeRunResult.sessionId) ?? readNonEmptyString(resumeRunResult.session_id)
      : null;
    const sessionOverride = buildExplicitResumeSessionOverride({
      adapterType: agent.adapterType,
      resumeFromRunId,
      resumeRunSessionIdBefore: resumeRun.sessionIdBefore,
      resumeRunSessionIdAfter: resumeRun.sessionIdAfter,
      resumeRunSessionParams: resumeRunSessionId ? { sessionId: resumeRunSessionId } : null,
      taskSession: resumeTaskSession,
      sessionCodec,
    });
    if (!sessionOverride) return null;

    return {
      resumeFromRunId,
      taskKey: resumeTaskKey,
      issueId: readNonEmptyString(resumeContext.issueId),
      taskId: readNonEmptyString(resumeContext.taskId) ?? readNonEmptyString(resumeContext.issueId),
      sessionDisplayId: sessionOverride.sessionDisplayId,
      sessionParams: (() => {
        const sourceIsolationKey = readK8sIsolationKeyFromContext(resumeContext);
        if (!isK8sAdapter(agent.adapterType) || !sessionOverride.sessionParams || !sourceIsolationKey) {
          return sessionOverride.sessionParams;
        }
        return {
          ...sessionOverride.sessionParams,
          [SESSION_ISOLATION_KEY_PARAM]: sourceIsolationKey,
        };
      })(),
    };
  }

  async function resolveWorkspaceForRun(
    agent: typeof agents.$inferSelect,
    context: Record<string, unknown>,
    previousSessionParams: Record<string, unknown> | null,
    opts?: { useProjectWorkspace?: boolean | null; k8sIsolationMode?: "shared" | "run" | "workspace" | null },
  ): Promise<ResolvedWorkspaceForRun> {
    const issueId = readNonEmptyString(context.issueId) ?? readNonEmptyString(context.taskId);
    const contextProjectId = readNonEmptyString(context.projectId);
    const contextProjectWorkspaceId = readNonEmptyString(context.projectWorkspaceId);
    const issueProjectRef = issueId
      ? await db
          .select({
            projectId: issues.projectId,
            projectWorkspaceId: issues.projectWorkspaceId,
          })
          .from(issues)
          .where(and(eq(issues.id, issueId), eq(issues.companyId, agent.companyId)))
          .then((rows) => rows[0] ?? null)
      : null;
    const issueProjectId = issueProjectRef?.projectId ?? null;
    const preferredProjectWorkspaceId =
      issueProjectRef?.projectWorkspaceId ?? contextProjectWorkspaceId ?? null;
    const resolvedProjectId = issueProjectId ?? contextProjectId;
    const useProjectWorkspace = opts?.useProjectWorkspace !== false;
    const workspaceProjectId = useProjectWorkspace ? resolvedProjectId : null;

    const unorderedProjectWorkspaceRows = workspaceProjectId
      ? await db
          .select()
          .from(projectWorkspaces)
          .where(
            and(
              eq(projectWorkspaces.companyId, agent.companyId),
              eq(projectWorkspaces.projectId, workspaceProjectId),
            ),
          )
          .orderBy(asc(projectWorkspaces.createdAt), asc(projectWorkspaces.id))
      : [];
    const projectWorkspaceRows = prioritizeProjectWorkspaceCandidatesForRun(
      unorderedProjectWorkspaceRows,
      preferredProjectWorkspaceId,
    );

    const workspaceHints = projectWorkspaceRows.map((workspace) => ({
      workspaceId: workspace.id,
      cwd: readNonEmptyString(workspace.cwd),
      repoUrl: readNonEmptyString(workspace.repoUrl),
      repoRef: readNonEmptyString(workspace.repoRef),
    }));

    // Determine the project-primary and whether the issue explicitly targets a
    // *non-primary* workspace. Computed once from the unordered (creation-order)
    // rows — independent of `projectWorkspaceRows.length` so the fail-loud guard
    // also covers the zero-rows / target-not-in-project edge (BLO-8188). When a
    // non-primary target cannot be realized we must not silently rebind to the
    // primary source; instead we surface a typed failure. See BLO-8188 / BLO-8154.
    const primaryProjectWorkspaceId = resolveProjectPrimaryWorkspaceId(unorderedProjectWorkspaceRows);
    const targetsNonPrimaryPreferred = isNonPrimaryWorkspaceTarget({
      preferredProjectWorkspaceId,
      rowsInCreationOrder: unorderedProjectWorkspaceRows,
    });
    const buildRealizationFailedResult = (
      reason: string | null,
    ): ResolvedWorkspaceRealizationFailed | null => {
      const realizationFailure = evaluatePreferredProjectWorkspaceRealization({
        preferredProjectWorkspaceId,
        primaryProjectWorkspaceId,
        targetsNonPrimary: targetsNonPrimaryPreferred,
        preferredWorkspaceRealized: false,
        reason,
      });
      if (!realizationFailure) return null;
      return {
        realizationFailure,
        preferredProjectWorkspaceId: realizationFailure.preferredProjectWorkspaceId,
        workspaceHints,
        warnings: [realizationFailure.reason],
      };
    };

    if (projectWorkspaceRows.length > 0) {
      const preferredWorkspace = preferredProjectWorkspaceId
        ? projectWorkspaceRows.find((workspace) => workspace.id === preferredProjectWorkspaceId) ?? null
        : null;
      const missingProjectCwds: string[] = [];
      let hasConfiguredProjectCwd = false;
      let preferredWorkspaceWarning: string | null = null;
      if (preferredProjectWorkspaceId && !preferredWorkspace) {
        preferredWorkspaceWarning =
          `Selected project workspace "${preferredProjectWorkspaceId}" is not available on this project.`;
      }
      // Restrict realization to the preferred workspace only when a non-primary
      // target was requested, so a different workspace can never silently
      // satisfy the run in its place.
      const realizationCandidates = targetsNonPrimaryPreferred
        ? projectWorkspaceRows.filter((workspace) => workspace.id === preferredProjectWorkspaceId)
        : projectWorkspaceRows;
      for (const workspace of realizationCandidates) {
        let projectCwd = readNonEmptyString(workspace.cwd);
        let managedWorkspaceWarning: string | null = null;
        if (!projectCwd || projectCwd === REPO_ONLY_CWD_SENTINEL) {
          try {
            const managedWorkspace = await ensureManagedProjectWorkspace({
              companyId: agent.companyId,
              projectId: workspaceProjectId ?? resolvedProjectId ?? workspace.projectId,
              repoUrl: readNonEmptyString(workspace.repoUrl),
            });
            projectCwd = managedWorkspace.cwd;
            managedWorkspaceWarning = managedWorkspace.warning;
          } catch (error) {
            if (preferredWorkspace?.id === workspace.id) {
              preferredWorkspaceWarning = error instanceof Error ? error.message : String(error);
            }
            continue;
          }
        }
        hasConfiguredProjectCwd = true;
        const projectCwdExists = await fs
          .stat(projectCwd)
          .then((stats) => stats.isDirectory())
          .catch(() => false);
        if (projectCwdExists) {
          return {
            cwd: projectCwd,
            source: "project_primary" as const,
            projectId: resolvedProjectId,
            workspaceId: workspace.id,
            repoUrl: workspace.repoUrl,
            repoRef: workspace.repoRef,
            workspaceHints,
            warnings: [preferredWorkspaceWarning, managedWorkspaceWarning].filter(
              (value): value is string => Boolean(value),
            ),
            preferredProjectWorkspaceId,
          };
        }
        if (preferredWorkspace?.id === workspace.id) {
          preferredWorkspaceWarning =
            `Selected project workspace path "${projectCwd}" is not available yet.`;
        }
        missingProjectCwds.push(projectCwd);
      }

      // Reaching here means the (restricted, when non-primary) candidate set
      // never yielded a usable cwd. If the issue explicitly targeted a
      // non-primary workspace, fail loud instead of silently rebinding to the
      // project-primary source. The failure result carries no executable cwd —
      // the caller aborts the run on it.
      const realizationFailed = buildRealizationFailedResult(preferredWorkspaceWarning);
      if (realizationFailed) {
        return realizationFailed;
      }

      const fallbackCwd = resolveDefaultAgentWorkspaceDir(agent.id);
      await fs.mkdir(fallbackCwd, { recursive: true });
      const warnings: string[] = [];
      if (preferredWorkspaceWarning) {
        warnings.push(preferredWorkspaceWarning);
      }
      if (missingProjectCwds.length > 0) {
        const firstMissing = missingProjectCwds[0];
        const extraMissingCount = Math.max(0, missingProjectCwds.length - 1);
        warnings.push(
          extraMissingCount > 0
            ? `Project workspace path "${firstMissing}" and ${extraMissingCount} other configured path(s) are not available yet. Using fallback workspace "${fallbackCwd}" for this run.`
            : `Project workspace path "${firstMissing}" is not available yet. Using fallback workspace "${fallbackCwd}" for this run.`,
        );
      } else if (!hasConfiguredProjectCwd) {
        warnings.push(
          `Project workspace has no local cwd configured. Using fallback workspace "${fallbackCwd}" for this run.`,
        );
      }
      return {
        cwd: fallbackCwd,
        source: "project_primary" as const,
        projectId: resolvedProjectId,
        workspaceId: projectWorkspaceRows[0]?.id ?? null,
        repoUrl: projectWorkspaceRows[0]?.repoUrl ?? null,
        repoRef: projectWorkspaceRows[0]?.repoRef ?? null,
        workspaceHints,
        warnings,
        preferredProjectWorkspaceId,
      };
    }

    if (workspaceProjectId) {
      // Zero project-workspace rows backed the issue's explicit non-primary
      // target (rows deleted, or the target belongs to another project). The
      // managed default below would silently run on the wrong source, so fail
      // loud first — this closes the zero-rows bypass of the guard above.
      const realizationFailed = buildRealizationFailedResult(
        targetsNonPrimaryPreferred
          ? `Selected project workspace "${preferredProjectWorkspaceId}" is not available on this project.`
          : null,
      );
      if (realizationFailed) {
        return realizationFailed;
      }
      const managedWorkspace = await ensureManagedProjectWorkspace({
        companyId: agent.companyId,
        projectId: workspaceProjectId,
        repoUrl: null,
      });
      return {
        cwd: managedWorkspace.cwd,
        source: "project_primary" as const,
        projectId: resolvedProjectId,
        workspaceId: null,
        repoUrl: null,
        repoRef: null,
        workspaceHints,
        warnings: managedWorkspace.warning ? [managedWorkspace.warning] : [],
      };
    }

    // BLO-18760: which workspace-less fallback dir does *this* run want? Decided
    // before the saved-session early return below, because that return has to be
    // screened against it — see the isolation-mismatch check.
    const useRepoLessFallbackSource = shouldUseRepoLessFallbackWorkspaceSource({
      adapterType: agent.adapterType,
      k8sIsolationMode: opts?.k8sIsolationMode ?? null,
    });
    const agentHomeFallbackDir = resolveDefaultAgentWorkspaceDir(agent.id);
    const repoLessFallbackDir = resolveAgentEmptyWorkspaceSourceDir(agent.id);

    const sessionCwd = readNonEmptyString(previousSessionParams?.cwd);
    const sessionCwdLooksUnsafe = isUnsafeSessionWorkspaceCwd(sessionCwd);

    // BLO-18760 (review follow-up): the saved-session early return below is
    // isolation-blind — `isUnsafeSessionWorkspaceCwd` screens system temp roots
    // only. Decline a saved cwd that is the workspace-less fallback dir of the
    // *other* isolation mode, in both directions; see
    // `isWorkspaceLessFallbackCwdForOtherIsolationMode` for why each direction
    // breaks. Every other resumable cwd is untouched.
    const sessionCwdIsMismatchedFallback = isWorkspaceLessFallbackCwdForOtherIsolationMode({
      sessionCwd,
      agentId: agent.id,
      adapterType: agent.adapterType,
      k8sIsolationMode: opts?.k8sIsolationMode ?? null,
    });

    if (sessionCwd && !sessionCwdLooksUnsafe && !sessionCwdIsMismatchedFallback) {
      const sessionCwdExists = await fs
        .stat(sessionCwd)
        .then((stats) => stats.isDirectory())
        .catch(() => false);
      if (sessionCwdExists) {
        return {
          cwd: sessionCwd,
          source: "task_session" as const,
          projectId: resolvedProjectId,
          workspaceId: readNonEmptyString(previousSessionParams?.workspaceId),
          repoUrl: readNonEmptyString(previousSessionParams?.repoUrl),
          repoRef: readNonEmptyString(previousSessionParams?.repoRef),
          workspaceHints,
          warnings: [],
        };
      }
    }

    // BLO-18760: an issue with no project and no resumable session used to
    // fall back to the persistent per-agent workspace dir. For claude_k8s
    // under `run` isolation that directory is a *clone source*, and it has
    // usually accumulated a real `.git` from unrelated prior runs — so the
    // pod's `git clone --shared` bootstrap either exits 128 under cephfs
    // pressure or is refused dispatch by the BLO-18147 guard, which parks the
    // issue with no wake path. Hand those runs a repo-less source instead:
    // the pod's `rev-parse --verify HEAD` then fails and its existing
    // non-fatal `else` branch gives the run a clean empty workspace. Issues
    // that never touch a repo now execute instead of stranding, and the
    // guard below still probes this path rather than being bypassed.
    //
    // Deliberately narrow: only the adapters whose in-pod bootstrap clones
    // (K8S_GIT_SENSITIVE_ADAPTER_TYPES) and only under `run` isolation, where
    // the pod's home/session/workspace roots are already ephemeral per-run
    // paths and this cwd serves *only* as the clone source. `shared` and
    // `workspace` isolation keep the persistent agent home, so warm-session
    // continuity is untouched.
    const cwd = useRepoLessFallbackSource ? repoLessFallbackDir : agentHomeFallbackDir;
    await fs.mkdir(cwd, { recursive: true });
    const warnings: string[] = [];
    const fallbackSuffix = useRepoLessFallbackSource
      ? ` Using repo-less fallback workspace "${cwd}" for this run; it starts empty.`
      : ` Using fallback workspace "${cwd}" for this run.`;
    if (sessionCwd && sessionCwdLooksUnsafe) {
      warnings.push(
        `Saved session workspace "${sessionCwd}" points at a system temp root and was rejected as untrusted.${fallbackSuffix}`,
      );
    } else if (sessionCwd && sessionCwdIsMismatchedFallback) {
      // Name the real cause: the directory exists and is readable, we declined it
      // on purpose because it belongs to the other isolation mode.
      warnings.push(
        `Saved session workspace "${sessionCwd}" is the workspace-less fallback for a different k8s isolation mode ` +
          `(this run resolves isolation as "${opts?.k8sIsolationMode ?? "unset"}") and was not reused.${fallbackSuffix}`,
      );
    } else if (sessionCwd) {
      warnings.push(
        `Saved session workspace "${sessionCwd}" is not available.${fallbackSuffix}`,
      );
    } else if (resolvedProjectId) {
      warnings.push(
        `No project workspace directory is currently available for this issue.${fallbackSuffix}`,
      );
    } else {
      warnings.push(
        `No project or prior session workspace was available.${fallbackSuffix}`,
      );
    }
    return {
      cwd,
      source: "agent_home" as const,
      projectId: resolvedProjectId,
      workspaceId: null,
      repoUrl: null,
      repoRef: null,
      workspaceHints,
      warnings,
    };
  }

  async function upsertTaskSession(input: {
    companyId: string;
    agentId: string;
    adapterType: string;
    taskKey: string;
    sessionParamsJson: Record<string, unknown> | null;
    sessionDisplayId: string | null;
    lastRunId: string | null;
    lastError: string | null;
  }) {
    const existing = await getTaskSession(
      input.companyId,
      input.agentId,
      input.adapterType,
      input.taskKey,
    );
    if (existing) {
      return db
        .update(agentTaskSessions)
        .set({
          sessionParamsJson: input.sessionParamsJson,
          sessionDisplayId: input.sessionDisplayId,
          lastRunId: input.lastRunId,
          lastError: input.lastError,
          updatedAt: new Date(),
        })
        .where(eq(agentTaskSessions.id, existing.id))
        .returning()
        .then((rows) => rows[0] ?? null);
    }

    return db
      .insert(agentTaskSessions)
      .values({
        companyId: input.companyId,
        agentId: input.agentId,
        adapterType: input.adapterType,
        taskKey: input.taskKey,
        sessionParamsJson: input.sessionParamsJson,
        sessionDisplayId: input.sessionDisplayId,
        lastRunId: input.lastRunId,
        lastError: input.lastError,
      })
      .returning()
      .then((rows) => rows[0] ?? null);
  }

  async function clearTaskSessions(
    companyId: string,
    agentId: string,
    opts?: { taskKey?: string | null; adapterType?: string | null },
  ) {
    return clearAgentTaskSessions(db, companyId, agentId, opts);
  }

  async function ensureRuntimeState(agent: typeof agents.$inferSelect) {
    const existing = await getRuntimeState(agent.id);
    if (existing) return existing;

    const inserted = await db
      .insert(agentRuntimeState)
      .values({
        agentId: agent.id,
        companyId: agent.companyId,
        adapterType: agent.adapterType,
        stateJson: {},
      })
      .onConflictDoNothing({
        target: agentRuntimeState.agentId,
      })
      .returning()
      .then((rows) => rows[0] ?? null);
    if (inserted) return inserted;

    const ensured = await getRuntimeState(agent.id);
    if (!ensured) {
      throw new Error(`Failed to ensure runtime state for agent ${agent.id}`);
    }
    return ensured;
  }

  async function setRunStatus(
    runId: string,
    status: string,
    patch?: Partial<typeof heartbeatRuns.$inferInsert>,
  ) {
    // BLO-16998: the finalize UPDATE can lose a deadlock (40P01), hit the role
    // statement_timeout (57014), or time out waiting on a row lock (55P03) under
    // bloat/contention. Unretried, the throw leaves the run stuck in `running`
    // forever and the agent never dispatches its next work. The write is
    // idempotent (a status set-by-id), so a bounded jittered retry is safe and
    // covers both the normal completion finalize and the BLO-16850 reaper's
    // process_lost finalize (both go through setRunStatus).
    const updated = await runWithTransientDbRetry(
      () =>
        db
          .update(heartbeatRuns)
          .set({ status, ...patch, updatedAt: new Date() })
          .where(eq(heartbeatRuns.id, runId))
          .returning()
          .then((rows) => rows[0] ?? null),
      {
        onRetry: ({ attempt, error }) =>
          logger.warn(
            {
              runId,
              status,
              attempt,
              sqlstate: (error as { code?: string } | null)?.code,
              err: error,
            },
            "setRunStatus write hit a transient db error; retrying (BLO-16998)",
          ),
      },
    );

    if (updated) {
      if (isHeartbeatRunTerminalStatus(updated.status)) {
        clearHeartbeatRunRuntimeStatus(updated.id);
      }
      publishLiveEvent({
        companyId: updated.companyId,
        type: "heartbeat.run.status",
        payload: {
          runId: updated.id,
          agentId: updated.agentId,
          status: updated.status,
          invocationSource: updated.invocationSource,
          triggerDetail: updated.triggerDetail,
          error: updated.error ?? null,
          errorCode: updated.errorCode ?? null,
          startedAt: updated.startedAt ? new Date(updated.startedAt).toISOString() : null,
          finishedAt: updated.finishedAt ? new Date(updated.finishedAt).toISOString() : null,
        },
      });
      publishRunLifecyclePluginEvent(updated);

      // BLO-4141: when a run reaches a terminal state, retry any deferred image
      // bump for the agent. Fire-and-forget — failures stay inside the
      // processor (logged there + self-healing on the next terminal transition),
      // and we never want a bump-retry error to surface as a heartbeat error
      // since the run itself finished cleanly.
      if (TERMINAL_RUN_STATUSES.has(updated.status)) {
        void refreshExternalRuntimeReservationMetrics(db).catch((err) => {
          logger.warn({ err, runId: updated.id }, "failed to refresh external-runtime reservation metrics");
        });
        const agentIdForBump = updated.agentId;
        const runIdForBump = updated.id;
        void processPendingImageBumpForAgent(db, agentIdForBump).catch((err) => {
          logger.warn(
            {
              agentId: agentIdForBump,
              runId: runIdForBump,
              error: err instanceof Error ? err.message : String(err),
            },
            "processPendingImageBumpForAgent failed; will retry on next run completion",
          );
        });
      }
    }

    return updated;
  }

  async function setRunStatusIfRunning(
    runId: string,
    status: string,
    patch?: Partial<typeof heartbeatRuns.$inferInsert>,
  ) {
    return setRunStatusIfCurrentStatus(runId, "running", status, patch, "setRunStatusIfRunning");
  }

  /**
   * BLO-20396: compare-and-swap a run that is still `queued`.
   *
   * Queued-run cleanup used to go through the by-id `setRunStatus`, which always
   * reports success — so overlapping dispatch passes each believed they had
   * cancelled the same row and each emitted a cancellation log/event, and a
   * cleanup pass could stomp a row another pass had already claimed to
   * `running`. Gating on `status = 'queued'` makes exactly one caller the
   * winner and lets the losers stay silent.
   */
  async function setRunStatusIfQueued(
    runId: string,
    status: string,
    patch?: Partial<typeof heartbeatRuns.$inferInsert>,
  ) {
    return setRunStatusIfCurrentStatus(runId, "queued", status, patch, "setRunStatusIfQueued");
  }

  async function setRunStatusIfCurrentStatus(
    runId: string,
    expectedStatus: string,
    status: string,
    patch: Partial<typeof heartbeatRuns.$inferInsert> | undefined,
    label: string,
  ) {
    // BLO-16998: same transient-retry rationale as setRunStatus — the guarded
    // finalize UPDATE is idempotent (status set-by-id, gated on the expected
    // current status) so replaying it on a transient failure is safe.
    const updated = await runWithTransientDbRetry(
      () =>
        db
          .update(heartbeatRuns)
          .set({ status, ...patch, updatedAt: new Date() })
          .where(and(eq(heartbeatRuns.id, runId), eq(heartbeatRuns.status, expectedStatus)))
          .returning()
          .then((rows) => rows[0] ?? null),
      {
        onRetry: ({ attempt, error }) =>
          logger.warn(
            {
              runId,
              status,
              attempt,
              sqlstate: (error as { code?: string } | null)?.code,
              err: error,
            },
            `${label} write hit a transient db error; retrying (BLO-16998)`,
          ),
      },
    );

    if (updated) {
      if (isHeartbeatRunTerminalStatus(updated.status)) {
        clearHeartbeatRunRuntimeStatus(updated.id);
      }
      publishLiveEvent({
        companyId: updated.companyId,
        type: "heartbeat.run.status",
        payload: {
          runId: updated.id,
          agentId: updated.agentId,
          status: updated.status,
          invocationSource: updated.invocationSource,
          triggerDetail: updated.triggerDetail,
          error: updated.error ?? null,
          errorCode: updated.errorCode ?? null,
          startedAt: updated.startedAt ? new Date(updated.startedAt).toISOString() : null,
          finishedAt: updated.finishedAt ? new Date(updated.finishedAt).toISOString() : null,
        },
      });
      publishRunLifecyclePluginEvent(updated);
      if (TERMINAL_RUN_STATUSES.has(updated.status)) {
        void refreshExternalRuntimeReservationMetrics(db).catch((err) => {
          logger.warn({ err, runId: updated.id }, "failed to refresh external-runtime reservation metrics");
        });
      }
      return { run: updated, updated: true as const };
    }

    const current = await db
      .select()
      .from(heartbeatRuns)
      .where(eq(heartbeatRuns.id, runId))
      .then((rows) => rows[0] ?? null);

    return { run: current, updated: false as const };
  }

  function publishRunLifecyclePluginEvent(run: typeof heartbeatRuns.$inferSelect) {
    const eventType =
      run.status === "running"
        ? "agent.run.started"
        : run.status === "succeeded"
          ? "agent.run.finished"
          : run.status === "failed" || run.status === "timed_out"
            ? "agent.run.failed"
            : run.status === "cancelled"
              ? "agent.run.cancelled"
              : null;
    if (!eventType) return;
    const ctx =
      typeof run.contextSnapshot === "object" && run.contextSnapshot !== null
        ? (run.contextSnapshot as Record<string, unknown>)
        : {};
    const paperclipIssue =
      typeof ctx.paperclipIssue === "object" && ctx.paperclipIssue !== null
        ? (ctx.paperclipIssue as Record<string, unknown>)
        : null;
    publishPluginDomainEvent({
      eventId: randomUUID(),
      eventType,
      occurredAt: new Date().toISOString(),
      actorId: run.agentId,
      actorType: "agent",
      entityId: run.id,
      entityType: "heartbeat_run",
      companyId: run.companyId,
      payload: {
        runId: run.id,
        agentId: run.agentId,
        status: run.status,
        invocationSource: run.invocationSource,
        triggerDetail: run.triggerDetail,
        error: run.error ?? null,
        errorCode: run.errorCode ?? null,
        issueId: ctx.issueId ?? null,
        issueTitle: typeof paperclipIssue?.title === "string" ? paperclipIssue.title : null,
        issueDescription:
          typeof paperclipIssue?.description === "string" ? paperclipIssue.description : null,
        output: run.stdoutExcerpt ?? null,
        result: run.resultJson ?? null,
        startedAt: run.startedAt ? new Date(run.startedAt).toISOString() : null,
        finishedAt: run.finishedAt ? new Date(run.finishedAt).toISOString() : null,
      },
    });
  }

  async function setWakeupStatus(
    wakeupRequestId: string | null | undefined,
    status: string,
    patch?: Partial<typeof agentWakeupRequests.$inferInsert>,
  ) {
    if (!wakeupRequestId) return;
    await db
      .update(agentWakeupRequests)
      .set({ status, ...patch, updatedAt: new Date() })
      .where(eq(agentWakeupRequests.id, wakeupRequestId));
  }

  async function addContinuationExhaustedCommentOnce(input: {
    run: typeof heartbeatRuns.$inferSelect;
    issueId: string;
    comment: string;
  }) {
    const existing = await db
      .select({ id: issueComments.id })
      .from(issueComments)
      .where(
        and(
          eq(issueComments.companyId, input.run.companyId),
          eq(issueComments.issueId, input.issueId),
          eq(issueComments.createdByRunId, input.run.id),
          sql`${issueComments.body} like 'Bounded liveness continuation exhausted%'`,
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (existing) return;
    await issuesSvc.addComment(input.issueId, input.comment, {
      agentId: input.run.agentId,
      runId: input.run.id,
    });
  }

  async function handleRunLivenessContinuation(run: typeof heartbeatRuns.$inferSelect) {
    const livenessState = run.livenessState as RunLivenessState | null;
    if (livenessState !== "plan_only" && livenessState !== "empty_response") return;

    const context = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(context.issueId);
    if (!issueId) return;

    const [issue, agent] = await Promise.all([
      db
        .select({
          id: issues.id,
          companyId: issues.companyId,
          identifier: issues.identifier,
          title: issues.title,
          status: issues.status,
          assigneeAgentId: issues.assigneeAgentId,
          executionState: issues.executionState,
          projectId: issues.projectId,
        })
        .from(issues)
        .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
        .then((rows) => rows[0] ?? null),
      db
        .select({
          id: agents.id,
          companyId: agents.companyId,
          status: agents.status,
        })
        .from(agents)
        .where(eq(agents.id, run.agentId))
        .then((rows) => rows[0] ?? null),
    ]);

    const budgetBlock =
      issue && agent
        ? await budgets.getInvocationBlock(issue.companyId, agent.id, {
          issueId: issue.id,
          projectId: issue.projectId,
        })
        : null;
    if (issue) {
      const productivityHold = await productivityReviews.isProductivityReviewContinuationHoldActive({
        companyId: issue.companyId,
        issueId: issue.id,
        agentId: run.agentId,
      });
      if (productivityHold.held) {
        await setRunStatus(run.id, run.status, {
          livenessReason:
            `${run.livenessReason ?? "Run ended without concrete progress"}; continuation held by productivity review ${productivityHold.reviewIdentifier ?? productivityHold.reviewIssueId}`,
        });
        await productivityReviews.recordContinuationHold({
          companyId: issue.companyId,
          issueId: issue.id,
          runId: run.id,
          agentId: run.agentId,
          reviewIssueId: productivityHold.reviewIssueId,
          trigger: productivityHold.trigger,
          reason: productivityHold.reason,
        });
        return;
      }
    }

    const nextAttempt = readContinuationAttempt(run.continuationAttempt) + 1;
    const idempotencyKey = issue
      ? buildRunLivenessContinuationIdempotencyKey({
        issueId: issue.id,
        sourceRunId: run.id,
        livenessState,
        nextAttempt,
      })
      : null;
    const existingWake = idempotencyKey
      ? await findExistingRunLivenessContinuationWake(db, {
        companyId: run.companyId,
        idempotencyKey,
      })
      : null;

    const decision = decideRunLivenessContinuation({
      run,
      issue,
      agent,
      livenessState,
      livenessReason: run.livenessReason,
      nextAction: run.nextAction,
      budgetBlocked: Boolean(budgetBlock),
      idempotentWakeExists: Boolean(existingWake),
    });

    if (decision.kind === "exhausted") {
      await setRunStatus(run.id, run.status, {
        livenessReason: `${run.livenessReason ?? "Run ended without concrete progress"}; continuation attempts exhausted`,
      });
      await addContinuationExhaustedCommentOnce({
        run,
        issueId,
        comment: decision.comment,
      });
      return;
    }

    if (decision.kind !== "enqueue") return;

    const continuationRun = await enqueueWakeup(run.agentId, {
      source: "automation",
      triggerDetail: "system",
      reason: RUN_LIVENESS_CONTINUATION_REASON,
      payload: decision.payload,
      contextSnapshot: decision.contextSnapshot,
      idempotencyKey: decision.idempotencyKey,
      requestedByActorType: "system",
      requestedByActorId: "heartbeat",
    });

    if (continuationRun) {
      await db
        .update(heartbeatRuns)
        .set({
          continuationAttempt: decision.nextAttempt,
          updatedAt: new Date(),
        })
        .where(eq(heartbeatRuns.id, run.id));
    }
  }

  function issueUiLink(issue: Pick<typeof issues.$inferSelect, "id" | "identifier">) {
    const label = issue.identifier ?? issue.id;
    const prefix = issue.identifier?.split("-")[0] || "PAP";
    return `[${label}](/${prefix}/issues/${label})`;
  }

  function hasUnmanagedBackgroundTaskEvidence(resultJson: Record<string, unknown> | null | undefined) {
    const evidence = parseObject(resultJson?.unmanagedBackgroundTask);
    return evidence.stopped === true &&
      (evidence.stopReason === UNMANAGED_BACKGROUND_TASK_STOP_REASON ||
        evidence.reason === UNMANAGED_BACKGROUND_TASK_LIVENESS_REASON);
  }

  function withUnmanagedBackgroundTaskStopReason(resultJson: Record<string, unknown> | null | undefined) {
    return {
      ...(resultJson ?? {}),
      stopReason: UNMANAGED_BACKGROUND_TASK_STOP_REASON,
    };
  }

  async function buildDetectedSuccessfulRunProgressSummary(run: typeof heartbeatRuns.$inferSelect) {
    const resultJson = parseObject(run.resultJson);
    const candidates = [
      hasUnmanagedBackgroundTaskEvidence(resultJson) ? UNMANAGED_BACKGROUND_TASK_LIVENESS_REASON : null,
      readNonEmptyString(run.nextAction) ? `Next action noted: ${readNonEmptyString(run.nextAction)}` : null,
      readNonEmptyString(run.livenessReason),
      readNonEmptyString(resultJson.summary),
      readNonEmptyString(resultJson.result),
      readNonEmptyString(resultJson.message),
    ].filter((value): value is string => Boolean(value));
    const summary = candidates[0];
    if (!summary) return null;
    return redactDetectedSuccessfulRunProgressSummaryForBoard(
      summary,
      await getCurrentUserRedactionOptions(),
    );
  }

  async function addSuccessfulRunHandoffCommentOnce(input: {
    issue: Pick<typeof issues.$inferSelect, "id" | "identifier" | "title" | "status">;
    run: typeof heartbeatRuns.$inferSelect;
    agent: Pick<typeof agents.$inferSelect, "id" | "name">;
    detectedProgressSummary: string;
  }) {
    const existing = await db
      .select({ id: issueComments.id })
      .from(issueComments)
      .where(
        and(
          eq(issueComments.companyId, input.run.companyId),
          eq(issueComments.issueId, input.issue.id),
          eq(issueComments.createdByRunId, input.run.id),
          sql`(${issueComments.body} = ${SUCCESSFUL_RUN_HANDOFF_REQUIRED_NOTICE_BODY} or ${issueComments.body} like '## This issue still needs a next step%' or ${issueComments.body} like '## Successful run missing issue disposition%')`,
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (existing) return null;
    const notice = buildSuccessfulRunHandoffRequiredNotice(input);
    return issuesSvc.addComment(
      input.issue.id,
      notice.body,
      { runId: input.run.id },
      {
        authorType: "system",
        presentation: notice.presentation,
        metadata: notice.metadata,
      },
    );
  }

  async function handleSuccessfulRunHandoff(run: typeof heartbeatRuns.$inferSelect, agent: typeof agents.$inferSelect) {
    if (run.status !== "succeeded") return;
    const context = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(context.issueId) ?? readNonEmptyString(context.taskId);
    if (!issueId) return;

    const issue = await db
      .select({
        id: issues.id,
        companyId: issues.companyId,
        identifier: issues.identifier,
        title: issues.title,
        status: issues.status,
        assigneeAgentId: issues.assigneeAgentId,
        assigneeUserId: issues.assigneeUserId,
        executionState: issues.executionState,
        monitorNextCheckAt: issues.monitorNextCheckAt,
        projectId: issues.projectId,
      })
      .from(issues)
      .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
      .then((rows) => rows[0] ?? null);
    const idempotencyKey = issue
      ? buildFinishSuccessfulRunHandoffIdempotencyKey({
        issueId: issue.id,
        sourceRunId: run.id,
      })
      : null;
    const taskKey = deriveTaskKeyWithHeartbeatFallback(context, null);
    const detectedProgressSummary = await buildDetectedSuccessfulRunProgressSummary(run);

    const [
      activeExecutionPath,
      queuedWake,
      pendingInteraction,
      pendingApproval,
      explicitBlocker,
      openRecoveryIssue,
      existingWake,
      budgetBlock,
      pauseHold,
      routineReceiverParent,
    ] = await Promise.all([
      issue
        ? db
          .select({ id: heartbeatRuns.id })
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.companyId, issue.companyId),
              eq(heartbeatRuns.agentId, run.agentId),
              inArray(heartbeatRuns.status, [...EXECUTION_PATH_HEARTBEAT_RUN_STATUSES]),
              sql`(
                ${heartbeatRuns.contextSnapshot} ->> 'issueId' = ${issue.id}
                or ${heartbeatRuns.contextSnapshot} ->> 'taskId' = ${issue.id}
              )`,
              sql`${heartbeatRuns.id} <> ${run.id}`,
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: agentWakeupRequests.id })
          .from(agentWakeupRequests)
          .where(
            and(
              eq(agentWakeupRequests.companyId, issue.companyId),
              eq(agentWakeupRequests.agentId, run.agentId),
              inArray(agentWakeupRequests.status, ["queued", "deferred_issue_execution", "claimed"]),
              sql`(
                ${agentWakeupRequests.payload} ->> 'issueId' = ${issue.id}
                or ${agentWakeupRequests.payload} ->> 'taskId' = ${issue.id}
                or ${agentWakeupRequests.payload} -> '_paperclipWakeContext' ->> 'issueId' = ${issue.id}
                or ${agentWakeupRequests.payload} -> '_paperclipWakeContext' ->> 'taskId' = ${issue.id}
              )`,
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: issueThreadInteractions.id })
          .from(issueThreadInteractions)
          .where(
            and(
              eq(issueThreadInteractions.companyId, issue.companyId),
              eq(issueThreadInteractions.issueId, issue.id),
              eq(issueThreadInteractions.status, "pending"),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: issueApprovals.approvalId })
          .from(issueApprovals)
          .innerJoin(approvals, eq(issueApprovals.approvalId, approvals.id))
          .where(
            and(
              eq(issueApprovals.companyId, issue.companyId),
              eq(issueApprovals.issueId, issue.id),
              inArray(approvals.status, ["pending", "revision_requested"]),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: issueRelations.issueId })
          .from(issueRelations)
          .where(
            and(
              eq(issueRelations.companyId, issue.companyId),
              eq(issueRelations.relatedIssueId, issue.id),
              eq(issueRelations.type, "blocks"),
              sql`exists (
                select 1
                from issues blocker
                where blocker.id = ${issueRelations.issueId}
                  and blocker.company_id = ${issue.companyId}
                  and blocker.status not in ('done', 'cancelled')
                  and blocker.hidden_at is null
              )`,
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: issues.id })
          .from(issues)
          .where(
            and(
              eq(issues.companyId, issue.companyId),
              inArray(issues.originKind, [
                RECOVERY_ORIGIN_KINDS.strandedIssueRecovery,
                RECOVERY_ORIGIN_KINDS.issueGraphLivenessEscalation,
              ]),
              eq(issues.originId, issue.id),
              visibleIssueCondition(),
              notInArray(issues.status, ["done", "cancelled"]),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
      idempotencyKey
        ? findExistingFinishSuccessfulRunHandoffWake(db, {
          companyId: run.companyId,
          idempotencyKey,
        })
        : Promise.resolve(null),
      issue
        ? budgets.getInvocationBlock(issue.companyId, run.agentId, {
          issueId: issue.id,
          projectId: issue.projectId,
        })
        : Promise.resolve(null),
      issue
        ? treeControlSvc.getActivePauseHoldGate(issue.companyId, issue.id)
        : Promise.resolve(null),
      issue
        ? db
          .select({ id: routines.id })
          .from(routines)
          .where(
            and(
              eq(routines.companyId, issue.companyId),
              eq(routines.parentIssueId, issue.id),
              inArray(routines.status, ["active", "paused"]),
              eq(routines.status, "active"),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null)
        : Promise.resolve(null),
    ]);
    const activeRoutineContinuation = routineReceiverParent;

    const decision = decideSuccessfulRunHandoff({
      run,
      issue,
      agent,
      livenessState: run.livenessState as RunLivenessState | null,
      detectedProgressSummary,
      taskKey,
      hasActiveExecutionPath: Boolean(activeExecutionPath),
      hasQueuedWake: Boolean(queuedWake),
      hasPendingInteractionOrApproval: Boolean(pendingInteraction || pendingApproval),
      hasPersistedMonitor: Boolean(issue?.monitorNextCheckAt),
      hasExplicitBlockerPath: Boolean(explicitBlocker),
      hasOpenRecoveryIssue: Boolean(openRecoveryIssue),
      hasPauseHold: Boolean(pauseHold),
      isRoutineReceiverParent: Boolean(routineReceiverParent),
      hasActiveRoutineContinuation: Boolean(activeRoutineContinuation),
      budgetBlocked: Boolean(budgetBlock),
      idempotentWakeExists: Boolean(existingWake),
    });

    if (isSuccessfulRunHandoffValidPathSkip(decision) && issue) {
      await resolveRequiredSuccessfulRunHandoffOnValidPath(db, {
        companyId: issue.companyId,
        issueId: issue.id,
        issueIdentifier: issue.identifier,
        agentId: run.agentId,
        runId: run.id,
        skipReason: decision.reason,
      });
    }

    if (decision.kind !== "enqueue" || !issue) return;

    if (hasUnmanagedBackgroundTaskEvidence(parseObject(run.resultJson))) {
      await db
        .update(heartbeatRuns)
        .set({
          livenessReason: UNMANAGED_BACKGROUND_TASK_LIVENESS_REASON,
          resultJson: withUnmanagedBackgroundTaskStopReason(parseObject(run.resultJson)),
          updatedAt: new Date(),
        })
        .where(eq(heartbeatRuns.id, run.id));
    }

    const handoffRun = await enqueueWakeup(decision.targetAgentId, {
      source: "automation",
      triggerDetail: "system",
      reason: FINISH_SUCCESSFUL_RUN_HANDOFF_REASON,
      payload: decision.payload,
      contextSnapshot: decision.contextSnapshot,
      idempotencyKey: decision.idempotencyKey,
      requestedByActorType: "system",
      requestedByActorId: "heartbeat",
    });
    if (!handoffRun) return;

    await addSuccessfulRunHandoffCommentOnce({
      issue,
      run,
      agent,
      detectedProgressSummary: detectedProgressSummary ?? "The run reported progress, but did not choose a next step.",
    });
    await logActivity(db, {
      companyId: issue.companyId,
      actorType: "system",
      actorId: "heartbeat",
      agentId: run.agentId,
      runId: run.id,
      action: "issue.successful_run_handoff_required",
      entityType: "issue",
      entityId: issue.id,
      details: {
        label: "Successful run missing issue disposition",
        sourceRunId: run.id,
        correctiveRunId: handoffRun.id,
        handoffReason: SUCCESSFUL_RUN_MISSING_STATE_REASON,
        missingDisposition: "clear_next_step",
        detectedProgressSummary,
        issue: issueUiLink(issue),
      },
    });
  }

  async function appendRunEvent(
    run: typeof heartbeatRuns.$inferSelect,
    seq: number,
    event: {
      eventType: string;
      stream?: "system" | "stdout" | "stderr";
      level?: "info" | "warn" | "error";
      color?: string;
      message?: string;
      payload?: Record<string, unknown>;
    },
  ) {
    const eventAt = new Date();
    const currentUserRedactionOptions = await getCurrentUserRedactionOptions();
    const sanitizedMessage = event.message
      ? redactCurrentUserText(event.message, currentUserRedactionOptions)
      : event.message;
    const boundedPayload = event.payload
      ? boundHeartbeatRunEventPayloadForStorage(event.payload)
      : event.payload;
    const secretSanitizedPayload = boundedPayload ? redactEventPayload(boundedPayload) : boundedPayload;
    const sanitizedPayload = secretSanitizedPayload
      ? redactCurrentUserValue(secretSanitizedPayload, currentUserRedactionOptions)
      : secretSanitizedPayload;
    const issueId = readRuntimeStatusIssueIdCandidate(run) ?? null;
    const progress = buildRunEventRuntimeProgress({
      eventType: event.eventType,
      message: sanitizedMessage ?? null,
      payload: sanitizedPayload ?? null,
      at: eventAt,
    });

    await db.insert(heartbeatRunEvents).values({
      companyId: run.companyId,
      runId: run.id,
      agentId: run.agentId,
      seq,
      eventType: event.eventType,
      stream: event.stream,
      level: event.level,
      color: event.color,
      message: sanitizedMessage,
      payload: sanitizedPayload,
    });

    publishLiveEvent({
      companyId: run.companyId,
      type: "heartbeat.run.event",
      payload: {
        runId: run.id,
        agentId: run.agentId,
        issueId,
        seq,
        eventType: event.eventType,
        stream: event.stream ?? null,
        level: event.level ?? null,
        color: event.color ?? null,
        message: sanitizedMessage ?? null,
        currentToolName: progress?.currentToolName ?? null,
        lastAssistantSnippet: progress?.lastAssistantSnippet ?? null,
        lastEventAt: (progress?.lastEventAt ?? eventAt).toISOString(),
        payload: sanitizedPayload ?? null,
      },
    });
    if (progress && isHeartbeatRunRuntimeStatusActive(run.status)) {
      const status = setHeartbeatRunRuntimeStatus({
        companyId: run.companyId,
        issueId,
        agentId: run.agentId,
        runId: run.id,
        phase: progress.phase,
        message: progress.message,
        updatedAt: eventAt,
        currentToolName: progress.currentToolName,
        lastAssistantSnippet: progress.lastAssistantSnippet,
        lastEventAt: progress.lastEventAt,
      });
      if (status) publishHeartbeatRunRuntimeProgress(status);
    }
  }

  async function nextRunEventSeq(runId: string) {
    const [row] = await db
      .select({ maxSeq: sql<number | null>`max(${heartbeatRunEvents.seq})` })
      .from(heartbeatRunEvents)
      .where(eq(heartbeatRunEvents.runId, runId));
    return Number(row?.maxSeq ?? 0) + 1;
  }

  async function persistRunProcessMetadata(
    runId: string,
    meta: { pid: number; processGroupId: number | null; startedAt: string },
  ) {
    const startedAt = new Date(meta.startedAt);
    return db
      .update(heartbeatRuns)
      .set({
        processPid: meta.pid,
        processGroupId: meta.processGroupId,
        processStartedAt: Number.isNaN(startedAt.getTime()) ? new Date() : startedAt,
        updatedAt: new Date(),
      })
      .where(eq(heartbeatRuns.id, runId))
      .returning()
      .then((rows) => rows[0] ?? null);
  }

  async function clearDetachedRunWarning(runId: string) {
    const updated = await db
      .update(heartbeatRuns)
      .set({
        error: null,
        errorCode: null,
        updatedAt: new Date(),
      })
      .where(and(eq(heartbeatRuns.id, runId), eq(heartbeatRuns.status, "running"), eq(heartbeatRuns.errorCode, DETACHED_PROCESS_ERROR_CODE)))
      .returning()
      .then((rows) => rows[0] ?? null);
    if (!updated) return null;

    await appendRunEvent(updated, await nextRunEventSeq(updated.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "info",
      message: "Detached child process reported activity; cleared detached warning",
    });
    return updated;
  }

  async function patchRunIssueCommentStatus(
    runId: string,
    patch: Partial<Pick<typeof heartbeatRuns.$inferInsert, "issueCommentStatus" | "issueCommentSatisfiedByCommentId" | "issueCommentRetryQueuedAt">>,
  ) {
    return db
      .update(heartbeatRuns)
      .set({ ...patch, updatedAt: new Date() })
      .where(eq(heartbeatRuns.id, runId))
      .returning()
      .then((rows) => rows[0] ?? null);
  }

  async function findRunIssueComment(runId: string, companyId: string, issueId: string) {
    return db
      .select({
        id: issueComments.id,
      })
      .from(issueComments)
      .where(
        and(
          eq(issueComments.companyId, companyId),
          eq(issueComments.issueId, issueId),
          eq(issueComments.createdByRunId, runId),
        ),
      )
      .orderBy(desc(issueComments.createdAt), desc(issueComments.id))
      .limit(1)
      .then((rows) => rows[0] ?? null);
  }

  async function refreshContinuationSummaryForRun(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
  ) {
    const contextSnapshot = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(contextSnapshot.issueId);
    if (!issueId) return null;
    try {
      return await refreshIssueContinuationSummary({
        db,
        issueId,
        run: {
          id: run.id,
          status: run.status,
          error: run.error,
          errorCode: run.errorCode,
          resultJson: run.resultJson as Record<string, unknown> | null,
          stdoutExcerpt: run.stdoutExcerpt,
          stderrExcerpt: run.stderrExcerpt,
          finishedAt: run.finishedAt,
        },
        agent: {
          id: agent.id,
          name: agent.name,
          adapterType: agent.adapterType,
        },
      });
    } catch (err) {
      logger.warn(
        {
          err,
          runId: run.id,
          issueId,
          agentId: agent.id,
        },
        "failed to refresh issue continuation summary",
      );
      return null;
    }
  }

  async function enqueueMissingIssueCommentRetry(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
    issueId: string,
  ) {
    const invokability = await getAgentInvokability(agent);
    if (!invokability.invokable) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "Missing-comment retry suppressed because the agent is not invokable",
        payload: {
          reason: invokability.reason,
          invalidOrgChain: invokability.invalidOrgChain,
          ...invokability.details,
        },
      });
      return null;
    }

    const contextSnapshot = parseObject(run.contextSnapshot);
    const taskKey = deriveTaskKeyWithHeartbeatFallback(contextSnapshot, null);
    const sessionBefore = await resolveSessionBeforeForWakeup(agent, taskKey);
    const retryContextSnapshot = withRecoveryModelProfileHint({
      ...contextSnapshot,
      retryOfRunId: run.id,
      wakeReason: "missing_issue_comment",
      retryReason: "missing_issue_comment",
      missingIssueCommentForRunId: run.id,
    }, "status_only");
    const responsibleUserId = await resolveResponsibleUserIdForRunContext(run, retryContextSnapshot);
    const now = new Date();

    const retryRun = await db.transaction(async (tx) => {
      await tx.execute(
        sql`select id from issues where company_id = ${run.companyId} and execution_run_id = ${run.id} for update`,
      );

      const issue = await tx
        .select({ id: issues.id })
        .from(issues)
        .where(and(eq(issues.companyId, run.companyId), eq(issues.executionRunId, run.id)))
        .then((rows) => rows[0] ?? null);
      if (!issue) return null;

      const wakeupRequest = await tx
        .insert(agentWakeupRequests)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          source: "automation",
          triggerDetail: "system",
          reason: "missing_issue_comment",
          payload: withRecoveryModelProfileHint({
            issueId,
            retryOfRunId: run.id,
            retryReason: "missing_issue_comment",
          }, "status_only"),
          status: "queued",
          requestedByActorType: "system",
          requestedByActorId: null,
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      const queuedRun = await tx
        .insert(heartbeatRuns)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          invocationSource: "automation",
          triggerDetail: "system",
          status: "queued",
          wakeupRequestId: wakeupRequest.id,
          contextSnapshot: retryContextSnapshot,
          responsibleUserId,
          sessionIdBefore: sessionBefore,
          retryOfRunId: run.id,
          issueCommentStatus: "not_applicable",
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      await tx
        .update(agentWakeupRequests)
        .set({
          runId: queuedRun.id,
          updatedAt: now,
        })
        .where(eq(agentWakeupRequests.id, wakeupRequest.id));

      await tx
        .update(issues)
        .set({
          executionRunId: queuedRun.id,
          executionAgentNameKey: normalizeAgentNameKey(agent.name),
          executionLockedAt: now,
          updatedAt: now,
        })
        .where(eq(issues.id, issue.id));

      await tx
        .update(heartbeatRuns)
        .set({
          issueCommentStatus: "retry_queued",
          issueCommentRetryQueuedAt: now,
          updatedAt: now,
        })
        .where(eq(heartbeatRuns.id, run.id));

      return queuedRun;
    });

    if (!retryRun) return null;

    publishLiveEvent({
      companyId: retryRun.companyId,
      type: "heartbeat.run.queued",
      payload: {
        runId: retryRun.id,
        agentId: retryRun.agentId,
        invocationSource: retryRun.invocationSource,
        triggerDetail: retryRun.triggerDetail,
        wakeupRequestId: retryRun.wakeupRequestId,
      },
    });

    return retryRun;
  }

  async function hasDeferredIssueCommentWake(companyId: string, issueId: string, agentId: string) {
    const deferredPayloads = await db
      .select({ payload: agentWakeupRequests.payload })
      .from(agentWakeupRequests)
      .where(
        and(
          eq(agentWakeupRequests.companyId, companyId),
          eq(agentWakeupRequests.agentId, agentId),
          eq(agentWakeupRequests.status, "deferred_issue_execution"),
          sql`${agentWakeupRequests.payload} ->> 'issueId' = ${issueId}`,
        ),
      );

    return deferredPayloads.some(({ payload }) => {
      const parsedPayload = parseObject(payload);
      const deferredContext = parseObject(parsedPayload[DEFERRED_WAKE_CONTEXT_KEY]);
      return Boolean(deriveCommentId(deferredContext, parsedPayload));
    });
  }

  async function finalizeIssueCommentPolicy(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
  ) {
    const contextSnapshot = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(contextSnapshot.issueId);
    if (!issueId) {
      if (run.issueCommentStatus !== "not_applicable") {
        await patchRunIssueCommentStatus(run.id, {
          issueCommentStatus: "not_applicable",
          issueCommentSatisfiedByCommentId: null,
          issueCommentRetryQueuedAt: null,
        });
      }
      return { outcome: "not_applicable" as const, queuedRun: null };
    }

    const postedComment = await findRunIssueComment(run.id, run.companyId, issueId);
    if (postedComment) {
      await patchRunIssueCommentStatus(run.id, {
        issueCommentStatus: "satisfied",
        issueCommentSatisfiedByCommentId: postedComment.id,
        issueCommentRetryQueuedAt: null,
      });
      return { outcome: "satisfied" as const, queuedRun: null };
    }

    if (readNonEmptyString(contextSnapshot.retryReason) === "missing_issue_comment") {
      await patchRunIssueCommentStatus(run.id, {
        issueCommentStatus: "retry_exhausted",
        issueCommentSatisfiedByCommentId: null,
      });
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "Run ended without an issue comment after one retry; no further comment wake will be queued",
      });
      return { outcome: "retry_exhausted" as const, queuedRun: null };
    }

    if (!shouldRequireIssueCommentForWake(contextSnapshot)) {
      if (run.issueCommentStatus !== "not_applicable") {
        await patchRunIssueCommentStatus(run.id, {
          issueCommentStatus: "not_applicable",
          issueCommentSatisfiedByCommentId: null,
          issueCommentRetryQueuedAt: null,
        });
      }
      return { outcome: "not_applicable" as const, queuedRun: null };
    }

    if (await hasDeferredIssueCommentWake(run.companyId, issueId, run.agentId)) {
      await patchRunIssueCommentStatus(run.id, {
        issueCommentStatus: "not_applicable",
        issueCommentSatisfiedByCommentId: null,
        issueCommentRetryQueuedAt: null,
      });
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "info",
        message: "Run ended without an issue comment; a deferred comment wake already exists for this issue",
      });
      return { outcome: "not_applicable" as const, queuedRun: null };
    }

    const queuedRun = await enqueueMissingIssueCommentRetry(run, agent, issueId);
    if (queuedRun) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "Run ended without an issue comment; queued one follow-up wake to require a comment",
      });
      return { outcome: "retry_queued" as const, queuedRun };
    }

    await patchRunIssueCommentStatus(run.id, {
      issueCommentStatus: "retry_exhausted",
      issueCommentSatisfiedByCommentId: null,
    });
    return { outcome: "retry_exhausted" as const, queuedRun: null };
  }

  async function enqueueProcessLossRetry(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
    now: Date,
  ) {
    const existingRetry = await db
      .select()
      .from(heartbeatRuns)
      .where(and(eq(heartbeatRuns.companyId, run.companyId), eq(heartbeatRuns.retryOfRunId, run.id)))
      .orderBy(asc(heartbeatRuns.createdAt))
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (existingRetry) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "Process-loss retry already exists; skipping duplicate retry enqueue",
        payload: {
          retryRunId: existingRetry.id,
          retryRunStatus: existingRetry.status,
        },
      });
      return existingRetry;
    }

    const invokability = await getAgentInvokability(agent);
    if (!invokability.invokable) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "Process-loss retry suppressed because the agent is not invokable",
        payload: {
          reason: invokability.reason,
          invalidOrgChain: invokability.invalidOrgChain,
          ...invokability.details,
        },
      });
      await releaseIssueExecutionAndPromote(run);
      return null;
    }

    const contextSnapshot = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(contextSnapshot.issueId);
    const retryReason = readNonEmptyString(contextSnapshot.wakeReason) === "issue_monitor_due"
      ? "issue_continuation_needed"
      : "process_lost";
    const taskKey = deriveTaskKeyWithHeartbeatFallback(contextSnapshot, null);
    const sessionBefore = await resolveSessionBeforeForWakeup(agent, taskKey);
    const retryContextSnapshot = withRecoveryModelProfileHint({
      ...contextSnapshot,
      retryOfRunId: run.id,
      wakeReason: "process_lost_retry",
      retryReason,
    }, "normal_model");
    const responsibleUserId = await resolveResponsibleUserIdForRunContext(run, retryContextSnapshot);

    const queued = await db.transaction(async (tx) => {
      const wakeupRequest = await tx
        .insert(agentWakeupRequests)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          source: "automation",
          triggerDetail: "system",
          reason: "process_lost_retry",
          payload: withRecoveryModelProfileHint({
            ...(issueId ? { issueId } : {}),
            retryOfRunId: run.id,
          }, "normal_model"),
          status: "queued",
          requestedByActorType: "system",
          requestedByActorId: null,
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      const retryRun = await tx
        .insert(heartbeatRuns)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          invocationSource: "automation",
          triggerDetail: "system",
          status: "queued",
          wakeupRequestId: wakeupRequest.id,
          contextSnapshot: retryContextSnapshot,
          responsibleUserId,
          sessionIdBefore: sessionBefore,
          retryOfRunId: run.id,
          processLossRetryCount: (run.processLossRetryCount ?? 0) + 1,
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      await tx
        .update(agentWakeupRequests)
        .set({
          runId: retryRun.id,
          updatedAt: now,
        })
        .where(eq(agentWakeupRequests.id, wakeupRequest.id));

      await tx
        .update(heartbeatRuns)
        .set({
          processLossRetryCount: (run.processLossRetryCount ?? 0) + 1,
          updatedAt: now,
        })
        .where(eq(heartbeatRuns.id, run.id));

      if (issueId) {
        await tx
          .update(issues)
          .set({
            checkoutRunId: null,
            executionRunId: retryRun.id,
            executionAgentNameKey: normalizeAgentNameKey(agent.name),
            executionLockedAt: now,
            updatedAt: now,
          })
          .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId), eq(issues.executionRunId, run.id)));
      }

      return retryRun;
    });

    publishLiveEvent({
      companyId: queued.companyId,
      type: "heartbeat.run.queued",
      payload: {
        runId: queued.id,
        agentId: queued.agentId,
        invocationSource: queued.invocationSource,
        triggerDetail: queued.triggerDetail,
        wakeupRequestId: queued.wakeupRequestId,
      },
    });

    await appendRunEvent(queued, 1, {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: "Queued automatic retry after orphaned child process was confirmed dead",
      payload: {
        retryOfRunId: run.id,
      },
    });

    return queued;
  }

  function toHotRestartIntentRun(input: {
    run: typeof heartbeatRuns.$inferSelect;
    adapterType: string;
  }): HotRestartIntentRun {
    const context = parseObject(input.run.contextSnapshot);
    return {
      runId: input.run.id,
      companyId: input.run.companyId,
      agentId: input.run.agentId,
      adapterType: input.adapterType,
      status: input.run.status,
      processPid: input.run.processPid ?? null,
      processGroupId: input.run.processGroupId ?? null,
      issueId: readNonEmptyString(context.issueId),
    };
  }

  async function prepareHotRestartShutdown(signal: "SIGINT" | "SIGTERM", now = new Date()) {
    let intent: Awaited<ReturnType<typeof readHotRestartIntent>>;
    try {
      intent = await readHotRestartIntent();
    } catch (err) {
      logger.warn({ err }, "failed to read hot-restart intent; falling back to normal shutdown drain");
      return { mode: "read_error" as const, skipDrain: false as const, activeRunIds: [] as string[] };
    }

    if (!intent) return { mode: "not_requested" as const, skipDrain: false as const, activeRunIds: [] as string[] };
    if (intent.drainRequired) return { mode: "drain_required" as const, skipDrain: false as const, activeRunIds: [] as string[] };
    if (!shouldHonorHotRestartIntentForProcess(intent)) {
      logger.warn(
        { expectedPid: intent.previousServerPid, currentPid: process.pid },
        "hot-restart intent targets a different server pid; falling back to normal shutdown drain",
      );
      return { mode: "pid_mismatch" as const, skipDrain: false as const, activeRunIds: [] as string[] };
    }

    const activeRuns = await db
      .select({
        run: heartbeatRuns,
        adapterType: agents.adapterType,
      })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(eq(heartbeatRuns.status, "running"));
    const snapshotRuns = activeRuns.map(toHotRestartIntentRun);
    const intentWithVersion = {
      ...intent,
      previousServerVersion: intent.previousServerVersion ?? serverVersion,
    };

    await writeHotRestartShutdownSnapshot({
      intent: intentWithVersion,
      signal,
      activeRuns: snapshotRuns,
      capturedAt: now,
    });

    for (const { run } of activeRuns) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "info",
        message: "Hot restart requested; leaving child process alive for startup adoption",
        payload: {
          signal,
          previousServerPid: intent.previousServerPid,
          previousServerVersion: intentWithVersion.previousServerVersion,
          processPid: run.processPid ?? null,
          processGroupId: run.processGroupId ?? null,
        },
      });
    }

    logger.info(
      { signal, previousServerPid: intent.previousServerPid, activeRunIds: snapshotRuns.map((run) => run.runId) },
      "hot-restart shutdown snapshot captured; skipping graceful run drain",
    );

    return {
      mode: "hot_restart" as const,
      skipDrain: true as const,
      activeRunIds: snapshotRuns.map((run) => run.runId),
    };
  }

  async function reconcileHotRestartAdoption(now = new Date()) {
    let intent: Awaited<ReturnType<typeof readHotRestartIntent>>;
    try {
      intent = await readHotRestartIntent();
    } catch (err) {
      logger.warn({ err }, "failed to read hot-restart intent on startup; skipping adoption");
      return {
        mode: "read_error" as const,
        adoptedRunIds: [] as string[],
        finalizedWhileDownRunIds: [] as string[],
        lostRunIds: [] as string[],
        skippedRunIds: [] as string[],
      };
    }
    if (!intent) {
      return {
        mode: "not_requested" as const,
        adoptedRunIds: [] as string[],
        finalizedWhileDownRunIds: [] as string[],
        lostRunIds: [] as string[],
        skippedRunIds: [] as string[],
      };
    }

    if (!intent.shutdownSnapshot) {
      logger.warn(
        { previousServerPid: intent.previousServerPid },
        "hot-restart intent present but shutdown snapshot is missing; no runs can be adopted",
      );
    }
    const candidates = intent.shutdownSnapshot?.activeRuns ?? [];
    const currentRows = candidates.length > 0
      ? await db
        .select({
          run: heartbeatRuns,
          adapterType: agents.adapterType,
        })
        .from(heartbeatRuns)
        .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
        .where(inArray(heartbeatRuns.id, candidates.map((run) => run.runId)))
      : [];
    const currentByRunId = new Map(currentRows.map((row) => [row.run.id, row]));

    const reportRuns: HotRestartReportRun[] = [];
    const adoptedRunIds: string[] = [];
    const finalizedWhileDownRunIds: string[] = [];
    const lostRunIds: string[] = [];
    const skippedRunIds: string[] = [];

    const classify = (
      candidate: HotRestartIntentRun,
      classification: HotRestartReportRun["classification"],
      reason: string,
      patch?: Partial<HotRestartIntentRun>,
    ) => {
      const run = { ...candidate, ...patch, classification, reason } satisfies HotRestartReportRun;
      reportRuns.push(run);
      if (classification === "adopted") adoptedRunIds.push(candidate.runId);
      else if (classification === "finalized_while_down") finalizedWhileDownRunIds.push(candidate.runId);
      else if (classification === "lost") lostRunIds.push(candidate.runId);
      else skippedRunIds.push(candidate.runId);
    };

    for (const candidate of candidates) {
      const current = currentByRunId.get(candidate.runId);
      if (!current) {
        classify(candidate, "finalized_while_down", "run_row_missing");
        continue;
      }

      const { run, adapterType } = current;
      const patch = {
        adapterType,
        status: run.status,
        processPid: run.processPid ?? candidate.processPid,
        processGroupId: run.processGroupId ?? candidate.processGroupId,
      };

      if (run.status !== "running") {
        classify(candidate, "finalized_while_down", `run_status_${run.status}`, patch);
        continue;
      }

      if (intent.drainRequired) {
        classify(candidate, "skipped", "drain_required", patch);
        continue;
      }

      if (!isTrackedLocalChildProcessAdapter(adapterType)) {
        classify(candidate, "skipped", "adapter_not_local_child_process", patch);
        continue;
      }

      const processPid = run.processPid ?? candidate.processPid;
      const processGroupId = run.processGroupId ?? candidate.processGroupId;
      const processPidAlive = isProcessAlive(processPid);
      const processGroupAlive = isProcessGroupAlive(processGroupId);
      if (!processPid && !processGroupId) {
        classify(candidate, "lost", "missing_process_metadata", patch);
        continue;
      }
      if (!processPidAlive && !processGroupAlive) {
        classify(candidate, "lost", "process_not_alive", patch);
        continue;
      }

      const resultJson = mergeHotRestartAdoptionResultJson(parseObject(run.resultJson), {
        adoptedAt: now,
        previousServerPid: intent.previousServerPid,
        newServerPid: process.pid,
        previousServerVersion: intent.previousServerVersion,
        newServerVersion: serverVersion,
        processPid,
        processGroupId,
      });
      const updated = await db
        .update(heartbeatRuns)
        .set({
          resultJson,
          error: run.errorCode === DETACHED_PROCESS_ERROR_CODE ? null : run.error,
          errorCode: run.errorCode === DETACHED_PROCESS_ERROR_CODE ? null : run.errorCode,
          updatedAt: now,
        })
        .where(and(eq(heartbeatRuns.id, run.id), eq(heartbeatRuns.status, "running")))
        .returning()
        .then((rows) => rows[0] ?? null);

      if (!updated) {
        const latest = await db
          .select({ status: heartbeatRuns.status })
          .from(heartbeatRuns)
          .where(eq(heartbeatRuns.id, run.id))
          .then((rows) => rows[0] ?? null);
        if (latest && latest.status !== "running") {
          classify(candidate, "finalized_while_down", `run_status_${latest.status}`, patch);
        } else {
          classify(candidate, "lost", "adoption_update_not_applied", patch);
        }
        continue;
      }

      await appendRunEvent(updated, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "info",
        message: "Adopted live child process after hot restart",
        payload: {
          previousServerPid: intent.previousServerPid,
          newServerPid: process.pid,
          previousServerVersion: intent.previousServerVersion,
          newServerVersion: serverVersion,
          processPid,
          processGroupId,
        },
      });
      classify(candidate, "adopted", processPidAlive ? "process_pid_alive" : "process_group_alive", patch);
    }

    const report = await writeHotRestartReport({
      version: 1,
      requestedAt: intent.requestedAt,
      completedAt: now.toISOString(),
      drainRequired: intent.drainRequired,
      previousServerPid: intent.previousServerPid,
      newServerPid: process.pid,
      previousServerVersion: intent.previousServerVersion,
      newServerVersion: serverVersion,
      adoptedRunIds,
      finalizedWhileDownRunIds,
      lostRunIds,
      skippedRunIds,
      runs: reportRuns,
    });
    await removeHotRestartIntent();

    logger.info(
      {
        previousServerPid: report.previousServerPid,
        newServerPid: report.newServerPid,
        adoptedRunIds,
        finalizedWhileDownRunIds,
        lostRunIds,
        skippedRunIds,
      },
      "hot-restart adoption report written",
    );

    return {
      mode: "reported" as const,
      adoptedRunIds,
      finalizedWhileDownRunIds,
      lostRunIds,
      skippedRunIds,
    };
  }

  async function drainRunningRunsForShutdown(signal: "SIGINT" | "SIGTERM", now = new Date()) {
    const activeRuns = await db
      .select({
        run: heartbeatRuns,
        agent: agents,
      })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(eq(heartbeatRuns.status, "running"));

    const interruptedRunIds: string[] = [];
    const retryRunIds: string[] = [];

    for (const { run, agent } of activeRuns) {
      const running = runningProcesses.get(run.id);
      try {
        if (running) {
          await terminateHeartbeatRunProcess({
            pid: running.child.pid ?? run.processPid,
            processGroupId: running.processGroupId ?? run.processGroupId,
            graceMs: Math.max(1, running.graceSec) * 1000,
          });
        } else if (run.processPid || run.processGroupId) {
          await terminateHeartbeatRunProcess({
            pid: run.processPid,
            processGroupId: run.processGroupId,
          });
        }
      } finally {
        runningProcesses.delete(run.id);
      }

      const message = `Interrupted by graceful server shutdown (${signal}); retry queued for restart recovery`;
      const interruptedStatus = await setRunStatusIfRunning(run.id, "interrupted", {
        finishedAt: now,
        error: message,
        errorCode: "server_shutdown_interrupted",
        signal,
        resultJson: mergeRunStopMetadataForAgent(agent, "interrupted", {
          resultJson: parseObject(run.resultJson),
          errorCode: "server_shutdown_interrupted",
          errorMessage: message,
        }),
      });
      if (!interruptedStatus.updated || !interruptedStatus.run) continue;
      let interrupted = interruptedStatus.run;
      await setWakeupStatus(run.wakeupRequestId, "cancelled", {
        finishedAt: now,
        error: null,
      });
      interrupted = await classifyAndPersistRunLiveness(interrupted, parseObject(interrupted.resultJson)) ?? interrupted;

      await releaseEnvironmentLeasesForRun({
        runId: interrupted.id,
        companyId: interrupted.companyId,
        agentId: interrupted.agentId,
        status: interrupted.status,
        failureReason: interrupted.error ?? undefined,
      });

      const retry = await enqueueProcessLossRetry(interrupted, agent, now);
      if (!retry) {
        await releaseIssueExecutionAndPromote(interrupted);
      } else {
        retryRunIds.push(retry.id);
      }

      await appendRunEvent(interrupted, await nextRunEventSeq(interrupted.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message,
        payload: {
          signal,
          ...(run.processPid ? { processPid: run.processPid } : {}),
          ...(run.processGroupId ? { processGroupId: run.processGroupId } : {}),
          ...(retry ? { retryRunId: retry.id } : {}),
        },
      });

      await finalizeAgentStatus(run.agentId, "interrupted", message);
      interruptedRunIds.push(interrupted.id);
    }

    if (interruptedRunIds.length > 0) {
      logger.warn(
        { signal, interrupted: interruptedRunIds.length, interruptedRunIds, retryRunIds },
        "interrupted running heartbeat runs for graceful shutdown",
      );
    }

    return {
      interrupted: interruptedRunIds.length,
      interruptedRunIds,
      retryRunIds,
    };
  }

  type ScheduledRetryGate =
    | { allowed: true }
    | {
        allowed: false;
        reason: string;
        errorCode:
          | "agent_not_invokable"
          | "budget_blocked"
          | "issue_not_found"
          | "issue_reassigned"
          | "issue_cancelled"
          | "issue_terminal_status"
          | "issue_not_in_progress"
          | "issue_execution_lock_changed"
          | "issue_review_participant_changed"
          | "issue_paused"
          | "issue_dependencies_blocked";
        issueId: string | null;
        details: Record<string, unknown>;
      };
  type BlockedScheduledRetryGate = Extract<ScheduledRetryGate, { allowed: false }>;

  async function evaluateScheduledRetryGate(input: {
    run: typeof heartbeatRuns.$inferSelect;
    agent: typeof agents.$inferSelect;
    contextSnapshot: Record<string, unknown>;
    retryReason?: string | null;
    enforceIssueExecutionLock?: boolean;
  }): Promise<ScheduledRetryGate> {
    const { run, agent, contextSnapshot } = input;
    const retryReason =
      input.retryReason ?? readNonEmptyString(contextSnapshot.retryReason) ?? run.scheduledRetryReason ?? null;
    const issueId = readNonEmptyString(contextSnapshot.issueId);
    const projectId = readNonEmptyString(contextSnapshot.projectId);

    const budgetBlock = await budgets.getInvocationBlock(run.companyId, run.agentId, {
      issueId,
      projectId,
    });
    if (budgetBlock) {
      return {
        allowed: false,
        reason: budgetBlock.reason,
        errorCode: "budget_blocked",
        issueId,
        details: {
          scopeType: budgetBlock.scopeType,
          scopeId: budgetBlock.scopeId,
        },
      };
    }

    const agentInvokability = await getAgentInvokability(agent);
    if (!agentInvokability.invokable) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because the agent is not invokable",
        errorCode: "agent_not_invokable",
        issueId,
        details: {
          ...agentInvokability.details,
          invalidOrgChain: agentInvokability.invalidOrgChain,
        },
      };
    }

    if (!issueId) return { allowed: true };

    const issue = await db
      .select({
        id: issues.id,
        status: issues.status,
        assigneeAgentId: issues.assigneeAgentId,
        executionRunId: issues.executionRunId,
        executionState: issues.executionState,
      })
      .from(issues)
      .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
      .then((rows) => rows[0] ?? null);

    if (!issue) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because the target issue no longer exists",
        errorCode: "issue_not_found",
        issueId,
        details: { issueId },
      };
    }

    if (issue.assigneeAgentId !== run.agentId) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because issue ownership changed",
        errorCode: "issue_reassigned",
        issueId,
        details: {
          issueId,
          previousAssigneeAgentId: run.agentId,
          currentAssigneeAgentId: issue.assigneeAgentId,
        },
      };
    }

    if (issue.status === "cancelled" || issue.status === "done") {
      return {
        allowed: false,
        reason: `Scheduled retry suppressed because issue reached terminal status (${issue.status})`,
        errorCode: issue.status === "cancelled" ? "issue_cancelled" : "issue_terminal_status",
        issueId,
        details: { issueId, currentStatus: issue.status },
      };
    }

    if (requiresInProgressIssueRetry(retryReason) && issue.status !== "in_progress") {
      return {
        allowed: false,
        reason: `Scheduled retry suppressed because issue is no longer in_progress (current status: ${issue.status})`,
        errorCode: "issue_not_in_progress",
        issueId,
        details: { issueId, currentStatus: issue.status, requiredStatus: "in_progress" },
      };
    }

    if (input.enforceIssueExecutionLock && issue.executionRunId !== run.id) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because the issue execution lock belongs to a different run",
        errorCode: "issue_execution_lock_changed",
        issueId,
        details: {
          issueId,
          expectedExecutionRunId: run.id,
          currentExecutionRunId: issue.executionRunId,
        },
      };
    }

    if (issue.status === "in_review") {
      const executionState = parseIssueExecutionState(issue.executionState);
      const currentParticipant = executionState?.currentParticipant ?? null;
      if (currentParticipant) {
        const participantMatches =
          currentParticipant.type === "agent" && currentParticipant.agentId === run.agentId;
        if (!participantMatches) {
          return {
            allowed: false,
            reason: "Scheduled retry suppressed because the issue is waiting on another review participant",
            errorCode: "issue_review_participant_changed",
            issueId,
            details: {
              issueId,
              currentStageType: executionState?.currentStageType ?? null,
              currentParticipant,
            },
          };
        }
      }
    }

    const activePauseHold = await treeControlSvc.getActivePauseHoldGate(run.companyId, issueId);
    if (activePauseHold) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because the issue is held by an active subtree pause hold",
        errorCode: "issue_paused",
        issueId,
        details: {
          issueId,
          holdId: activePauseHold.holdId,
          rootIssueId: activePauseHold.rootIssueId,
        },
      };
    }

    const dependencyReadiness = await issuesSvc.listDependencyReadiness(run.companyId, [issueId]);
    const readiness = dependencyReadiness.get(issueId);
    if (readiness && !readiness.isDependencyReady) {
      return {
        allowed: false,
        reason: "Scheduled retry suppressed because issue dependencies are still blocked",
        errorCode: "issue_dependencies_blocked",
        issueId,
        details: {
          issueId,
          unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
          unresolvedBlockerCount: readiness.unresolvedBlockerCount,
        },
      };
    }

    return { allowed: true };
  }

  async function cancelScheduledRetryForGate(
    run: typeof heartbeatRuns.$inferSelect,
    gate: Extract<ScheduledRetryGate, { allowed: false }>,
    now: Date,
  ) {
    const cancelled = await db
      .update(heartbeatRuns)
      .set({
        status: "cancelled",
        finishedAt: now,
        error: gate.reason,
        errorCode: gate.errorCode,
        updatedAt: now,
      })
      .where(
        and(
          eq(heartbeatRuns.id, run.id),
          eq(heartbeatRuns.status, "scheduled_retry"),
          lte(heartbeatRuns.scheduledRetryAt, now),
        ),
      )
      .returning()
      .then((rows) => rows[0] ?? null);

    if (!cancelled) return null;

    // Same terminal accounting as the in-transaction promotion gate: this
    // cancel ends a run a GitHub delivery may be parked on, so settle the
    // `deferred` it was counted under (BLO-18859 review follow-up). Reached
    // only when a row was actually cancelled, so a lost race increments
    // nothing.
    const gateGithubReviewReason = githubPrReviewWakeReasonFromRunSnapshot(
      parseObject(cancelled.contextSnapshot),
    );
    if (gateGithubReviewReason !== null) {
      const settledDeliveries = readGithubReviewDeliveryCount(parseObject(cancelled.contextSnapshot));
      for (let i = 0; i < settledDeliveries; i++) {
        recordGithubReviewRequestSuppressed({
          reason: gateGithubReviewReason,
          cause: GITHUB_SUPPRESSION_CAUSE_SCHEDULED_RETRY_GATE,
        });
      }
    }

    if (cancelled.wakeupRequestId) {
      await db
        .update(agentWakeupRequests)
        .set({
          status: "cancelled",
          finishedAt: now,
          error: gate.reason,
          updatedAt: now,
        })
        .where(eq(agentWakeupRequests.id, cancelled.wakeupRequestId));
    }

    if (gate.issueId) {
      await db
        .update(issues)
        .set({
          executionRunId: null,
          executionAgentNameKey: null,
          executionLockedAt: null,
          updatedAt: now,
        })
        .where(
          and(
            eq(issues.companyId, cancelled.companyId),
            eq(issues.id, gate.issueId),
            eq(issues.executionRunId, cancelled.id),
          ),
        );
    }

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: gate.reason,
      payload: {
        ...gate.details,
        scheduledRetryAttempt: cancelled.scheduledRetryAttempt,
        scheduledRetryAt: cancelled.scheduledRetryAt ? new Date(cancelled.scheduledRetryAt).toISOString() : null,
        scheduledRetryReason: cancelled.scheduledRetryReason,
      },
    });

    return cancelled;
  }

  async function promoteScheduledRetryRun(
    dueRun: typeof heartbeatRuns.$inferSelect,
    now: Date,
  ): Promise<
    | { outcome: "promoted"; run: typeof heartbeatRuns.$inferSelect }
    | {
        outcome: "gate_suppressed";
        run: typeof heartbeatRuns.$inferSelect;
        reason: string;
        errorCode: BlockedScheduledRetryGate["errorCode"];
      }
    | { outcome: "not_promoted"; run: typeof heartbeatRuns.$inferSelect | null }
  > {
    const agent = await getAgent(dueRun.agentId);
    if (!agent) {
      const gate = {
        allowed: false as const,
        reason: "Scheduled retry suppressed because the agent no longer exists",
        errorCode: "agent_not_invokable" as const,
        issueId: readNonEmptyString(parseObject(dueRun.contextSnapshot).issueId),
        details: { agentId: dueRun.agentId },
      };
      const cancelled = await cancelScheduledRetryForGate(dueRun, gate, now);
      return cancelled
        ? {
            outcome: "gate_suppressed",
            run: cancelled,
            reason: gate.reason,
            errorCode: gate.errorCode,
          }
        : { outcome: "not_promoted", run: null };
    }

    const contextSnapshot = parseObject(dueRun.contextSnapshot);
    const gate = await evaluateScheduledRetryGate({
      run: dueRun,
      agent,
      contextSnapshot,
      retryReason: dueRun.scheduledRetryReason,
      enforceIssueExecutionLock: requiresIssueExecutionRetryLock(dueRun.scheduledRetryReason),
    });
    if (!gate.allowed) {
      if (
        gate.errorCode === "issue_not_found" &&
        dueRun.scheduledRetryReason !== MAX_TURN_CONTINUATION_RETRY_REASON
      ) {
        // Preserve legacy transient retry behavior for runs that only carry a
        // loose task context rather than a persisted issue row.
      } else if (
        gate.errorCode === "issue_dependencies_blocked" &&
        dueRun.scheduledRetryReason === DEP_BLOCKED_RETRY_REASON
      ) {
        // Re-defer logic handled in the dep-blocked block below instead of cancelling.
      } else {
        const cancelled = await cancelScheduledRetryForGate(dueRun, gate, now);
        return cancelled
          ? {
              outcome: "gate_suppressed",
              run: cancelled,
              reason: gate.reason,
              errorCode: gate.errorCode,
            }
          : { outcome: "not_promoted", run: null };
      }
    }

    // A ccrotate capacity defer must re-check the gate at promotion time: if the
    // pool is still exhausted, re-defer with backoff instead of promoting a run
    // that would dispatch and immediately 429. PEN-382.
    if (dueRun.scheduledRetryReason === CCROTATE_CAPACITY_RETRY_REASON) {
      let capacity: {
        target: "claude" | "codex";
        reason: string;
        resumeAt: Date | null;
        penstockProvider?: string;
        penstockModel?: string;
        penstockRetryAfterSeconds?: number | null;
      } | null = null;
      const penstockCapacity = await checkPenstockAvailabilityForAgent({
        agent,
        now,
        issueId: readNonEmptyString(contextSnapshot.issueId),
        heartbeatRunId: dueRun.id,
      });
      if (!penstockCapacity.allow) {
        capacity = {
          target: "claude",
          reason: penstockCapacity.reason,
          resumeAt: penstockCapacity.resumeAt,
          penstockProvider: penstockCapacity.provider,
          penstockModel: penstockCapacity.model,
          penstockRetryAfterSeconds: penstockCapacity.retryAfterSeconds,
        };
        recordCcrotateCapacityDeferred({
          adapter: agent.adapterType,
          provider: penstockCapacity.provider,
        });
      }
      if (capacity) {
        const nextAttempt = (dueRun.scheduledRetryAttempt ?? 0) + 1;
        if (nextAttempt > CCROTATE_CAPACITY_MAX_RETRY_ATTEMPTS) {
          // The pool never recovered within the retry budget. Terminate the
          // scheduled retry so it surfaces for operator attention instead of
          // looping forever.
          const exhausted = await db
            .update(heartbeatRuns)
            .set({
              status: "cancelled",
              finishedAt: now,
              error: `provider capacity retry exhausted after ${dueRun.scheduledRetryAttempt ?? 0} attempts; pool did not recover`,
              errorCode: "rate_limit_exhausted",
              updatedAt: now,
            })
            .where(
              and(
                eq(heartbeatRuns.id, dueRun.id),
                eq(heartbeatRuns.status, "scheduled_retry"),
                lte(heartbeatRuns.scheduledRetryAt, now),
              ),
            )
            .returning()
            .then((rows) => rows[0] ?? null);
          if (exhausted) {
            // The capacity pool never recovered inside the retry budget, so a
            // GitHub delivery parked here is lost for real, not merely late:
            // the run is cancelled and nothing re-drives it. That is the same
            // user-visible outcome as an exhausted dispatch chain — a posted
            // trigger with no review — so it settles as `dead_lettered` and
            // pages via the existing dead-letter alert, rather than as a
            // policy suppression (BLO-18859 review follow-up).
            const exhaustedSnapshot = parseObject(exhausted.contextSnapshot);
            const exhaustedGithubReviewReason =
              githubPrReviewWakeReasonFromRunSnapshot(exhaustedSnapshot);
            if (exhaustedGithubReviewReason !== null) {
              // Per delivery, not per run: every delivery that coalesced onto
              // this run was counted `deferred`, and all of them die with it.
              const lostDeliveries = readGithubReviewDeliveryCount(exhaustedSnapshot);
              for (let i = 0; i < lostDeliveries; i++) {
                recordGithubReviewRequestDelivery({
                  state: "dead_lettered",
                  reason: exhaustedGithubReviewReason,
                });
              }
            }
            await appendRunEvent(exhausted, await nextRunEventSeq(exhausted.id), {
              eventType: "lifecycle",
              stream: "system",
              level: "warn",
              message: "provider capacity retry exhausted; pool did not recover within the retry budget",
              payload: {
                scheduledRetryAttempt: dueRun.scheduledRetryAttempt ?? 0,
                maxAttempts: CCROTATE_CAPACITY_MAX_RETRY_ATTEMPTS,
                ccrotateTarget: capacity.target,
                providerCapacityReason: capacity.reason,
                ...(capacity.penstockProvider ? { penstockProvider: capacity.penstockProvider } : {}),
                ...(capacity.penstockModel ? { penstockModel: capacity.penstockModel } : {}),
              },
            });
            // Surface the stuck pool as a coalesced, operator-visible issue so a
            // non-recovering pool gets attention instead of only a warn event
            // buried in run history. Best-effort: never break the sweep. PEN-382.
            try {
              await recovery.escalateCcrotateCapacityExhausted({
                companyId: dueRun.companyId,
                ccrotateTarget: capacity.target,
                agentId: dueRun.agentId,
                agentName: agent?.name ?? null,
                runId: exhausted.id,
                attempts: dueRun.scheduledRetryAttempt ?? 0,
              });
            } catch (escalationError) {
              logger.warn(
                {
                  err: escalationError,
                  runId: exhausted.id,
                  ccrotateTarget: capacity.target,
                },
                "ccrotate capacity exhaustion escalation failed",
              );
            }
          }
          return { outcome: "not_promoted", run: exhausted };
        }
        const nextDueAt =
          capacity.resumeAt ?? new Date(now.getTime() + CCROTATE_CAPACITY_DEFAULT_RETRY_DELAY_MS);
        const rescheduled = await db
          .update(heartbeatRuns)
          .set({ scheduledRetryAttempt: nextAttempt, scheduledRetryAt: nextDueAt, updatedAt: now })
          .where(
            and(
              eq(heartbeatRuns.id, dueRun.id),
              eq(heartbeatRuns.status, "scheduled_retry"),
              lte(heartbeatRuns.scheduledRetryAt, now),
            ),
          )
          .returning()
          .then((rows) => rows[0] ?? null);
        if (rescheduled) {
          await appendRunEvent(rescheduled, await nextRunEventSeq(rescheduled.id), {
            eventType: "lifecycle",
            stream: "system",
            level: "info",
            message: "provider capacity still exhausted at promotion; re-deferred with backoff",
            payload: {
              scheduledRetryAttempt: nextAttempt,
              scheduledRetryAt: nextDueAt.toISOString(),
              ccrotateTarget: capacity.target,
              providerCapacityReason: capacity.reason,
              ...(capacity.penstockProvider ? { penstockProvider: capacity.penstockProvider } : {}),
              ...(capacity.penstockModel ? { penstockModel: capacity.penstockModel } : {}),
              ...(capacity.penstockRetryAfterSeconds !== undefined
                ? { penstockRetryAfterSeconds: capacity.penstockRetryAfterSeconds }
                : {}),
            },
          });
        }
        return { outcome: "not_promoted", run: rescheduled };
      }
      const retryContextSnapshot = parseObject(dueRun.contextSnapshot);
      const resultJson = parseObject(dueRun.resultJson);
      const ccrotateTarget =
        readNonEmptyString(retryContextSnapshot.ccrotateTarget) ??
        readNonEmptyString(resultJson.ccrotateTarget) ??
        mapAdapterToCcrotateTarget(agent.adapterType);
      if (ccrotateTarget) {
        try {
          await recovery.closeRecoveredCcrotateCapacityEscalations({
            companyId: dueRun.companyId,
            ccrotateTarget,
            runId: dueRun.id,
            now,
          });
        } catch (closeError) {
          logger.warn(
            { err: closeError, runId: dueRun.id, ccrotateTarget },
            "ccrotate capacity recovery escalation close failed",
          );
        }
      }
    }

    // A dep-blocked defer must re-check dependency readiness at promotion time.
    // If still blocked → re-defer with exponential backoff. If resolved → fall
    // through to normal promotion so the run becomes queued and runs.
    if (dueRun.scheduledRetryReason === DEP_BLOCKED_RETRY_REASON) {
      const depIssueId = readNonEmptyString(parseObject(dueRun.contextSnapshot).issueId);
      if (depIssueId) {
        const readiness = (await issuesSvc.listDependencyReadiness(dueRun.companyId, [depIssueId])).get(depIssueId);
        if (readiness && !readiness.isDependencyReady) {
          const nextAttempt = (dueRun.scheduledRetryAttempt ?? 0) + 1;
          if (nextAttempt > DEP_BLOCKED_MAX_RETRY_ATTEMPTS) {
            const exhausted = await db
              .update(heartbeatRuns)
              .set({
                status: "cancelled",
                finishedAt: now,
                error: `dependency-blocked retry exhausted after ${dueRun.scheduledRetryAttempt ?? 0} attempts; blockers never resolved`,
                errorCode: "issue_dependencies_blocked",
                updatedAt: now,
              })
              .where(
                and(
                  eq(heartbeatRuns.id, dueRun.id),
                  eq(heartbeatRuns.status, "scheduled_retry"),
                  lte(heartbeatRuns.scheduledRetryAt, now),
                ),
              )
              .returning()
              .then((rows) => rows[0] ?? null);
            if (exhausted) {
              incrementDepBlockedMetric("dep_blocked_exhausted");
              await appendRunEvent(exhausted, await nextRunEventSeq(exhausted.id), {
                eventType: "lifecycle",
                stream: "system",
                level: "warn",
                message: "dependency-blocked retry exhausted; blockers never resolved within the retry budget",
                payload: {
                  scheduledRetryAttempt: dueRun.scheduledRetryAttempt ?? 0,
                  maxAttempts: DEP_BLOCKED_MAX_RETRY_ATTEMPTS,
                  unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
                },
              });
              if (exhausted.wakeupRequestId) {
                await db
                  .update(agentWakeupRequests)
                  .set({
                    status: "cancelled",
                    finishedAt: now,
                    error: "Cancelled because dependency-blocked retry exhausted",
                    updatedAt: now,
                  })
                  .where(eq(agentWakeupRequests.id, exhausted.wakeupRequestId));
              }
              await db
                .update(issues)
                .set({
                  executionRunId: null,
                  executionAgentNameKey: null,
                  executionLockedAt: null,
                  updatedAt: now,
                })
                .where(and(eq(issues.id, depIssueId), eq(issues.executionRunId, exhausted.id)));
            }
            return { outcome: "not_promoted", run: exhausted };
          }
          const nextDueAt = new Date(now.getTime() + depBlockedRetryDelayMs(nextAttempt));
          const nextContextSnapshot = {
            ...parseObject(dueRun.contextSnapshot),
            unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
            unresolvedBlockerCount: readiness.unresolvedBlockerCount,
          };
          const rescheduled = await db
            .update(heartbeatRuns)
            .set({
              contextSnapshot: nextContextSnapshot,
              scheduledRetryAttempt: nextAttempt,
              scheduledRetryAt: nextDueAt,
              updatedAt: now,
            })
            .where(
              and(
                eq(heartbeatRuns.id, dueRun.id),
                eq(heartbeatRuns.status, "scheduled_retry"),
                lte(heartbeatRuns.scheduledRetryAt, now),
              ),
            )
            .returning()
            .then((rows) => rows[0] ?? null);
          if (rescheduled) {
            incrementDepBlockedMetric("dep_blocked_redeferred");
            await appendRunEvent(rescheduled, await nextRunEventSeq(rescheduled.id), {
              eventType: "lifecycle",
              stream: "system",
              level: "info",
              message: "dependencies still blocked at promotion; re-deferred with backoff",
              payload: {
                scheduledRetryAttempt: nextAttempt,
                scheduledRetryAt: nextDueAt.toISOString(),
                unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
              },
            });
          }
          return { outcome: "not_promoted", run: rescheduled };
        }
        // Dependencies resolved — fall through to promote the run.
      }
    }

    const promotionIssueId = readNonEmptyString(contextSnapshot.issueId);
    await options.beforeScheduledRetryPromotionUpdateForTest?.(dueRun, now);
    const atomicPromotion = await db.transaction(async (tx) => {
      let promotionGate: BlockedScheduledRetryGate | null = null;

      if (promotionIssueId && requiresIssueExecutionRetryLock(dueRun.scheduledRetryReason)) {
        const lockedIssue = await tx
          .select({
            status: issues.status,
            assigneeAgentId: issues.assigneeAgentId,
            executionRunId: issues.executionRunId,
          })
          .from(issues)
          .where(and(eq(issues.companyId, dueRun.companyId), eq(issues.id, promotionIssueId)))
          .for("update")
          .then((rows) => rows[0] ?? null);

        if (!lockedIssue) {
          promotionGate = {
            allowed: false,
            reason: "Scheduled retry suppressed because the target issue no longer exists",
            errorCode: "issue_not_found",
            issueId: promotionIssueId,
            details: { issueId: promotionIssueId },
          };
        } else if (lockedIssue.assigneeAgentId !== dueRun.agentId) {
          promotionGate = {
            allowed: false,
            reason: "Scheduled retry suppressed because issue ownership changed",
            errorCode: "issue_reassigned",
            issueId: promotionIssueId,
            details: {
              issueId: promotionIssueId,
              previousAssigneeAgentId: dueRun.agentId,
              currentAssigneeAgentId: lockedIssue.assigneeAgentId,
            },
          };
        } else if (lockedIssue.status === "cancelled" || lockedIssue.status === "done") {
          promotionGate = {
            allowed: false,
            reason: `Scheduled retry suppressed because issue reached terminal status (${lockedIssue.status})`,
            errorCode: lockedIssue.status === "cancelled" ? "issue_cancelled" : "issue_terminal_status",
            issueId: promotionIssueId,
            details: { issueId: promotionIssueId, currentStatus: lockedIssue.status },
          };
        } else if (requiresInProgressIssueRetry(dueRun.scheduledRetryReason) && lockedIssue.status !== "in_progress") {
          promotionGate = {
            allowed: false,
            reason: `Scheduled retry suppressed because issue is no longer in_progress (current status: ${lockedIssue.status})`,
            errorCode: "issue_not_in_progress",
            issueId: promotionIssueId,
            details: { issueId: promotionIssueId, currentStatus: lockedIssue.status, requiredStatus: "in_progress" },
          };
        } else if (lockedIssue.executionRunId !== dueRun.id) {
          promotionGate = {
            allowed: false,
            reason: "Scheduled retry suppressed because the issue execution lock belongs to a different run",
            errorCode: "issue_execution_lock_changed",
            issueId: promotionIssueId,
            details: {
              issueId: promotionIssueId,
              expectedExecutionRunId: dueRun.id,
              currentExecutionRunId: lockedIssue.executionRunId,
            },
          };
        }
      }

      if (promotionGate) {
        const cancelled = await tx
          .update(heartbeatRuns)
          .set({
            status: "cancelled",
            finishedAt: now,
            error: promotionGate.reason,
            errorCode: promotionGate.errorCode,
            updatedAt: now,
          })
          .where(
            and(
              eq(heartbeatRuns.id, dueRun.id),
              eq(heartbeatRuns.status, "scheduled_retry"),
              lte(heartbeatRuns.scheduledRetryAt, now),
            ),
          )
          .returning()
          .then((rows) => rows[0] ?? null);
        if (!cancelled) return { outcome: "not_promoted" as const, run: null };

        if (cancelled.wakeupRequestId) {
          await tx
            .update(agentWakeupRequests)
            .set({
              status: "cancelled",
              finishedAt: now,
              error: promotionGate.reason,
              updatedAt: now,
            })
            .where(eq(agentWakeupRequests.id, cancelled.wakeupRequestId));
        }
        await tx
          .update(issues)
          .set({
            executionRunId: null,
            executionAgentNameKey: null,
            executionLockedAt: null,
            updatedAt: now,
          })
          .where(
            and(
              eq(issues.companyId, cancelled.companyId),
              eq(issues.id, promotionIssueId!),
              eq(issues.executionRunId, cancelled.id),
            ),
          );
        return { outcome: "gate_suppressed" as const, run: cancelled, gate: promotionGate };
      }

      const promoted = await tx
        .update(heartbeatRuns)
        .set({
          status: "queued",
          error: null,
          errorCode: null,
          updatedAt: now,
        })
        .where(
          and(
            eq(heartbeatRuns.id, dueRun.id),
            eq(heartbeatRuns.status, "scheduled_retry"),
            lte(heartbeatRuns.scheduledRetryAt, now),
          ),
        )
        .returning()
        .then((rows) => rows[0] ?? null);
      return { outcome: promoted ? "promoted" as const : "not_promoted" as const, run: promoted };
    });

    if (atomicPromotion.outcome === "gate_suppressed") {
      // Terminal sibling of the `promoted` increment below: the run is
      // `cancelled`, so a delivery counted `deferred` at dispatch would
      // otherwise never reach a settled state (BLO-18859 review follow-up).
      // The gate family is policy, not outage, so it lands on a cause the
      // suppression-outage alert deliberately does not select.
      const gateContextSnapshot = parseObject(atomicPromotion.run.contextSnapshot);
      const gateGithubReviewReason = githubPrReviewWakeReasonFromRunSnapshot(gateContextSnapshot);
      if (gateGithubReviewReason !== null) {
        const settledDeliveries = readGithubReviewDeliveryCount(gateContextSnapshot);
        for (let i = 0; i < settledDeliveries; i++) {
          recordGithubReviewRequestSuppressed({
            reason: gateGithubReviewReason,
            cause: GITHUB_SUPPRESSION_CAUSE_SCHEDULED_RETRY_GATE,
          });
        }
      }
      await appendRunEvent(atomicPromotion.run, await nextRunEventSeq(atomicPromotion.run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: atomicPromotion.gate.reason,
        payload: {
          ...atomicPromotion.gate.details,
          scheduledRetryAttempt: atomicPromotion.run.scheduledRetryAttempt,
          scheduledRetryAt: atomicPromotion.run.scheduledRetryAt
            ? new Date(atomicPromotion.run.scheduledRetryAt).toISOString()
            : null,
          scheduledRetryReason: atomicPromotion.run.scheduledRetryReason,
        },
      });
      return {
        outcome: "gate_suppressed",
        run: atomicPromotion.run,
        reason: atomicPromotion.gate.reason,
        errorCode: atomicPromotion.gate.errorCode,
      };
    }

    const promoted = atomicPromotion.run;
    if (!promoted) return { outcome: "not_promoted", run: null };

    if (promoted.scheduledRetryReason === DEP_BLOCKED_RETRY_REASON) {
      incrementDepBlockedMetric("dep_blocked_promoted");
    }

    // BLO-18859 review follow-up: close out the `deferred` this run was counted
    // under when the capacity gate parked it. The delivery was late, not lost,
    // and until this increment existed a successfully-delayed review sat at
    // `received=1, deferred=1, queued=0` forever — indistinguishable from loss.
    //
    // Exactly-once per *delivery*, which is the granularity the rest of the
    // funnel uses: the promoting UPDATE is conditional on the row still being
    // `scheduled_retry`, so a concurrent promoter's UPDATE matches no rows and
    // returns null above — and every delivery that coalesced onto this run
    // bumped the tally as it was counted `deferred`. Replaying the tally here
    // is what keeps `received = queued + suppressed + dead_lettered + in-flight`
    // closed when N deliveries settle as one run.
    const promotedContextSnapshot = parseObject(promoted.contextSnapshot);
    const promotedGithubReviewReason = githubPrReviewWakeReasonFromRunSnapshot(promotedContextSnapshot);
    if (promotedGithubReviewReason !== null) {
      const settledDeliveries = readGithubReviewDeliveryCount(promotedContextSnapshot);
      for (let i = 0; i < settledDeliveries; i++) {
        recordGithubReviewRequestDelivery({ state: "queued", reason: promotedGithubReviewReason });
      }
    }

    await appendRunEvent(promoted, await nextRunEventSeq(promoted.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "info",
      message: "Scheduled retry became due and was promoted to the queued run pool",
      payload: {
        scheduledRetryAttempt: promoted.scheduledRetryAttempt,
        scheduledRetryAt: promoted.scheduledRetryAt ? new Date(promoted.scheduledRetryAt).toISOString() : null,
        scheduledRetryReason: promoted.scheduledRetryReason,
      },
    });

    publishLiveEvent({
      companyId: promoted.companyId,
      type: "heartbeat.run.queued",
      payload: {
        runId: promoted.id,
        agentId: promoted.agentId,
        invocationSource: promoted.invocationSource,
        triggerDetail: promoted.triggerDetail,
        wakeupRequestId: promoted.wakeupRequestId,
      },
    });

    return { outcome: "promoted", run: promoted };
  }

  async function scheduleBoundedRetryForRun(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
    opts?: {
      now?: Date;
      random?: () => number;
      retryReason?: string;
      wakeReason?: string;
      maxAttempts?: number;
      delayMs?: number;
    },
  ) {
    const now = opts?.now ?? new Date();
    const retryReason = opts?.retryReason ?? BOUNDED_TRANSIENT_HEARTBEAT_RETRY_REASON;
    const wakeReason = opts?.wakeReason ?? BOUNDED_TRANSIENT_HEARTBEAT_RETRY_WAKE_REASON;
    const maxAttempts = Math.max(0, Math.floor(opts?.maxAttempts ?? BOUNDED_TRANSIENT_HEARTBEAT_RETRY_MAX_ATTEMPTS));
    const nextAttempt = (run.scheduledRetryAttempt ?? 0) + 1;
    const transientRecovery =
      retryReason === BOUNDED_TRANSIENT_HEARTBEAT_RETRY_REASON
        ? readTransientRecoveryContractFromRun(run)
        : null;
    // Pick the schedule curve based on the recovery family. Rate-limit gets
    // a flat short delay (gate is the actual decider); generic transient
    // upstream gets the original exponential backoff. Upstream's explicit
    // opts.delayMs takes precedence (test-only override). For custom retry
    // reasons (e.g. capacity_blocked), opts.maxAttempts sets the cap.
    const isRateLimitFamily = transientRecovery?.errorFamily === "rate_limit_exhausted";
    const maxAttemptsForFamily = isRateLimitFamily
      ? RATE_LIMIT_HEARTBEAT_RETRY_MAX_ATTEMPTS
      : maxAttempts;
    const computedBaseSchedule = opts?.delayMs != null
      ? nextAttempt <= maxAttemptsForFamily
        ? {
            attempt: nextAttempt,
            baseDelayMs: Math.max(0, Math.floor(opts.delayMs)),
            delayMs: Math.max(0, Math.floor(opts.delayMs)),
            dueAt: new Date(now.getTime() + Math.max(0, Math.floor(opts.delayMs))),
            maxAttempts: maxAttemptsForFamily,
          }
        : null
      : nextAttempt <= maxAttemptsForFamily
        ? isRateLimitFamily
          ? computeRateLimitHeartbeatRetrySchedule(nextAttempt, now, opts?.random)
          : computeBoundedTransientHeartbeatRetrySchedule(nextAttempt, now, opts?.random)
        : null;
    const baseSchedule = computedBaseSchedule
      ? { ...computedBaseSchedule, maxAttempts: maxAttemptsForFamily }
      : null;
    const codexTransientFallbackMode =
      agent.adapterType === "codex_local" && transientRecovery?.errorFamily === "transient_upstream"
        ? resolveCodexTransientFallbackMode(nextAttempt)
        : null;
    const transientRetryNotBefore = transientRecovery?.retryNotBefore ?? null;
    const contextSnapshot = parseObject(run.contextSnapshot);
    const issueId = readNonEmptyString(contextSnapshot.issueId);

    if (!baseSchedule) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: `Bounded retry exhausted after ${run.scheduledRetryAttempt ?? 0} scheduled attempts; no further automatic retry will be queued`,
        payload: {
          retryReason,
          // See the scheduled-retry event: carry the failing errorCode so an
          // exhausted, code-specific failure surfaces its cause (e.g.
          // pr_review_output_missing) directly in the exhaustion event.
          ...(run.errorCode ? { errorCode: run.errorCode } : {}),
          retryFamily: transientRecovery?.errorFamily ?? null,
          scheduledRetryAttempt: run.scheduledRetryAttempt ?? 0,
          maxAttempts: maxAttemptsForFamily,
        },
      });
      if (retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON) {
        await escalatePlanApprovalResumeFailureNeedsAttention({
          run,
          issueId,
          attempt: Math.min(run.scheduledRetryAttempt ?? maxAttempts, maxAttempts),
          maxAttempts,
        }).catch((error) => {
          logger.warn(
            { err: error, runId: run.id, issueId },
            "failed to escalate exhausted plan-approval resume failure",
          );
        });
      }
      // BLO-17456: a PR-review chain that exhausts here leaves its required
      // status context unposted, so the PR sits on "Expected — waiting for
      // status" with nothing signalling that no result is coming. Queue a
      // durable status delivery so stale writes are guarded by a final
      // GitHub-evidence read and transient GitHub/token failures can retry.
      // Opt-in and swallowed so status delivery can never alter exhaustion
      // handling.
      await queueExhaustedPrReviewGateStatus(run, contextSnapshot).catch((error) => {
        logger.warn(
          { err: error, runId: run.id },
          "failed to queue exhausted PR-review gate status",
        );
      });
      return {
        outcome: "retry_exhausted" as const,
        attempt: nextAttempt,
        maxAttempts: maxAttemptsForFamily,
      };
    }

    if (retryReason !== MAX_TURN_CONTINUATION_RETRY_REASON) {
      const invokability = await getAgentInvokability(agent);
      if (!invokability.invokable) {
        await appendRunEvent(run, await nextRunEventSeq(run.id), {
          eventType: "lifecycle",
          stream: "system",
          level: "warn",
          message: "Scheduled retry suppressed because the agent is not invokable",
          payload: {
            retryReason,
            scheduledRetryAttempt: nextAttempt,
            maxAttempts,
            reason: invokability.reason,
            invalidOrgChain: invokability.invalidOrgChain,
            ...invokability.details,
          },
        });
        return {
          outcome: "not_scheduled" as const,
          reason: "Scheduled retry suppressed because the agent is not invokable",
          errorCode: "agent_not_invokable" as const,
          issueId,
        };
      }
    }

    const schedule =
      transientRetryNotBefore && transientRetryNotBefore.getTime() > baseSchedule.dueAt.getTime()
        ? {
            ...baseSchedule,
            dueAt: transientRetryNotBefore,
            delayMs: Math.max(0, transientRetryNotBefore.getTime() - now.getTime()),
          }
        : baseSchedule;

    const requiresIssueGate =
      requiresIssueExecutionRetryLock(retryReason) ||
      retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON;
    if (requiresIssueGate) {
      const gate = await evaluateScheduledRetryGate({
        run,
        agent,
        contextSnapshot,
        retryReason,
        enforceIssueExecutionLock: requiresIssueExecutionRetryLock(retryReason),
      });
      if (!gate.allowed) {
        await appendRunEvent(run, await nextRunEventSeq(run.id), {
          eventType: "lifecycle",
          stream: "system",
          level: "warn",
          message: gate.reason,
          payload: {
            retryReason,
            scheduledRetryAttempt: nextAttempt,
            maxAttempts,
            ...gate.details,
          },
        });
        return {
          outcome: "not_scheduled" as const,
          reason: gate.reason,
          errorCode: gate.errorCode,
          issueId: gate.issueId,
        };
      }
    }
    const taskKey = deriveTaskKeyWithHeartbeatFallback(contextSnapshot, null);
    const sessionBefore = await resolveSessionBeforeForWakeup(agent, taskKey);
    const interactionContinuationPayload = retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON
      ? {
          mutation: "interaction",
          interactionId: readNonEmptyString(contextSnapshot.interactionId),
          interactionKind: readNonEmptyString(contextSnapshot.interactionKind),
          interactionStatus: readNonEmptyString(contextSnapshot.interactionStatus),
          continuationPolicy: readNonEmptyString(contextSnapshot.continuationPolicy),
        }
      : {};
    const workspaceValidationRetryPayload =
      retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON && isWorkspaceValidationFailedRun(run)
        ? readWorkspaceValidationPayloadFromRun(run)
        : null;
    const shouldQuarantineWorkspaceForRetry =
      workspaceValidationRetryPayload !== null &&
      Object.keys(workspaceValidationRetryPayload).length > 0;
    const retryContextSnapshot: Record<string, unknown> = withRecoveryModelProfileHint({
      ...contextSnapshot,
      retryOfRunId: run.id,
      wakeReason,
      retryReason,
      ...(shouldQuarantineWorkspaceForRetry
        ? {
            workspaceValidationRecovery: {
              strategy: "quarantine_failed_workspace_and_retry_clean",
              sourceRunId: run.id,
              reason: readNonEmptyString(workspaceValidationRetryPayload?.reason) ?? WORKSPACE_VALIDATION_FAILURE_CODE,
              fingerprint: readNonEmptyString(workspaceValidationRetryPayload?.fingerprint),
              failedExecutionWorkspaceId: readNonEmptyString(workspaceValidationRetryPayload?.executionWorkspaceId),
            },
          }
        : {}),
      ...(transientRecovery ? { errorFamily: transientRecovery.errorFamily } : {}),
      scheduledRetryAttempt: schedule.attempt,
      scheduledRetryAt: schedule.dueAt.toISOString(),
      ...(transientRetryNotBefore ? { transientRetryNotBefore: transientRetryNotBefore.toISOString() } : {}),
      ...(transientRecovery?.errorFamily === "provider_quota" && transientRetryNotBefore
        ? { providerQuotaRetryNotBefore: transientRetryNotBefore.toISOString() }
        : {}),
      ...(codexTransientFallbackMode ? { codexTransientFallbackMode } : {}),
    }, "normal_model");
    const responsibleUserId = await resolveResponsibleUserIdForRunContext(run, retryContextSnapshot);
    const continuationRetryIdempotencyKey = retryReason === MAX_TURN_CONTINUATION_RETRY_REASON
      ? `max-turn-continuation:${run.companyId}:${issueId ?? "no-issue"}:${run.id}:${schedule.attempt}`
      : retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON
        ? `interaction-continuation:${run.companyId}:${issueId ?? "no-issue"}:${run.id}:${schedule.attempt}`
        : null;

    type ScheduledRetryTransactionResult =
      | {
          outcome: "scheduled";
          run: typeof heartbeatRuns.$inferSelect;
          reusedExisting: boolean;
        }
      | {
          outcome: "not_scheduled";
          reason: string;
          errorCode:
            | "issue_not_found"
            | "issue_reassigned"
            | "issue_cancelled"
            | "issue_terminal_status"
            | "issue_not_in_progress"
            | "issue_execution_lock_changed";
          issueId: string | null;
          details: Record<string, unknown>;
        };

    const scheduleResult = await db.transaction(async (tx): Promise<ScheduledRetryTransactionResult> => {
      if (retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON) {
        if (issueId) {
          await tx.execute(
            sql`select id from issues where company_id = ${run.companyId} and id = ${issueId} for update`,
          );
        } else {
          await tx.execute(
            sql`select id from heartbeat_runs where company_id = ${run.companyId} and id = ${run.id} for update`,
          );
        }

        const existingContinuation = await tx
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.companyId, run.companyId),
              eq(heartbeatRuns.retryOfRunId, run.id),
              eq(heartbeatRuns.scheduledRetryReason, retryReason),
              eq(heartbeatRuns.scheduledRetryAttempt, schedule.attempt),
              inArray(heartbeatRuns.status, [...MAX_TURN_CONTINUATION_LIVE_RUN_STATUSES]),
              issueId
                ? sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' = ${issueId}`
                : sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' is null`,
            ),
          )
          .orderBy(asc(heartbeatRuns.createdAt), asc(heartbeatRuns.id))
          .limit(1)
          .then((rows) => rows[0] ?? null);

        if (existingContinuation) {
          if (existingContinuation.wakeupRequestId) {
            const existingWakeup = await tx
              .select({ coalescedCount: agentWakeupRequests.coalescedCount })
              .from(agentWakeupRequests)
              .where(eq(agentWakeupRequests.id, existingContinuation.wakeupRequestId))
              .then((rows) => rows[0] ?? null);

            await tx
              .update(agentWakeupRequests)
              .set({
                coalescedCount: (existingWakeup?.coalescedCount ?? 0) + 1,
                updatedAt: now,
              })
              .where(eq(agentWakeupRequests.id, existingContinuation.wakeupRequestId));
          }

          return {
            outcome: "scheduled",
            run: existingContinuation,
            reusedExisting: true,
          };
        }
      }

      if (requiresIssueExecutionRetryLock(retryReason)) {
        if (issueId) {
          await tx.execute(
            sql`select id from issues where company_id = ${run.companyId} and id = ${issueId} for update`,
          );
        } else {
          await tx.execute(
            sql`select id from heartbeat_runs where company_id = ${run.companyId} and id = ${run.id} for update`,
          );
        }

        const existingContinuation = await tx
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.companyId, run.companyId),
              eq(heartbeatRuns.retryOfRunId, run.id),
              eq(heartbeatRuns.scheduledRetryReason, retryReason),
              eq(heartbeatRuns.scheduledRetryAttempt, schedule.attempt),
              inArray(heartbeatRuns.status, [...MAX_TURN_CONTINUATION_LIVE_RUN_STATUSES]),
              issueId
                ? sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' = ${issueId}`
                : sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' is null`,
            ),
          )
          .orderBy(asc(heartbeatRuns.createdAt), asc(heartbeatRuns.id))
          .limit(1)
          .then((rows) => rows[0] ?? null);

        if (existingContinuation) {
          if (existingContinuation.wakeupRequestId) {
            const existingWakeup = await tx
              .select({ coalescedCount: agentWakeupRequests.coalescedCount })
              .from(agentWakeupRequests)
              .where(eq(agentWakeupRequests.id, existingContinuation.wakeupRequestId))
              .then((rows) => rows[0] ?? null);

            await tx
              .update(agentWakeupRequests)
              .set({
                coalescedCount: (existingWakeup?.coalescedCount ?? 0) + 1,
                updatedAt: now,
              })
              .where(eq(agentWakeupRequests.id, existingContinuation.wakeupRequestId));
          }

          return {
            outcome: "scheduled",
            run: existingContinuation,
            reusedExisting: true,
          };
        }

        if (issueId) {
          const lockedIssue = await tx
            .select({
              id: issues.id,
              status: issues.status,
              assigneeAgentId: issues.assigneeAgentId,
              executionRunId: issues.executionRunId,
            })
            .from(issues)
            .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
            .then((rows) => rows[0] ?? null);

          if (!lockedIssue) {
            return {
              outcome: "not_scheduled",
              reason: "Scheduled retry suppressed because the target issue no longer exists",
              errorCode: "issue_not_found",
              issueId,
              details: { issueId },
            };
          }

          if (lockedIssue.assigneeAgentId !== run.agentId) {
            return {
              outcome: "not_scheduled",
              reason: "Scheduled retry suppressed because issue ownership changed",
              errorCode: "issue_reassigned",
              issueId,
              details: {
                issueId,
                previousAssigneeAgentId: run.agentId,
                currentAssigneeAgentId: lockedIssue.assigneeAgentId,
              },
            };
          }

          if (lockedIssue.status === "cancelled" || lockedIssue.status === "done") {
            return {
              outcome: "not_scheduled",
              reason: `Scheduled retry suppressed because issue reached terminal status (${lockedIssue.status})`,
              errorCode: lockedIssue.status === "cancelled" ? "issue_cancelled" : "issue_terminal_status",
              issueId,
              details: { issueId, currentStatus: lockedIssue.status },
            };
          }

          if (requiresInProgressIssueRetry(retryReason) && lockedIssue.status !== "in_progress") {
            return {
              outcome: "not_scheduled",
              reason: `Scheduled retry suppressed because issue is no longer in_progress (current status: ${lockedIssue.status})`,
              errorCode: "issue_not_in_progress",
              issueId,
              details: { issueId, currentStatus: lockedIssue.status, requiredStatus: "in_progress" },
            };
          }

          if (lockedIssue.executionRunId !== run.id) {
            return {
              outcome: "not_scheduled",
              reason: "Scheduled retry suppressed because the issue execution lock belongs to a different run",
              errorCode: "issue_execution_lock_changed",
              issueId,
              details: {
                issueId,
                expectedExecutionRunId: run.id,
                currentExecutionRunId: lockedIssue.executionRunId,
              },
            };
          }
        }
      }

      const wakeupRequest = await tx
        .insert(agentWakeupRequests)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          source: "automation",
          triggerDetail: "system",
          reason: wakeReason,
          payload: withRecoveryModelProfileHint({
            ...(issueId ? { issueId } : {}),
            retryOfRunId: run.id,
            ...interactionContinuationPayload,
            retryReason,
            ...(transientRecovery ? { errorFamily: transientRecovery.errorFamily } : {}),
            scheduledRetryAttempt: schedule.attempt,
            scheduledRetryAt: schedule.dueAt.toISOString(),
            ...(transientRetryNotBefore ? { transientRetryNotBefore: transientRetryNotBefore.toISOString() } : {}),
            ...(transientRecovery?.errorFamily === "provider_quota" && transientRetryNotBefore
              ? { providerQuotaRetryNotBefore: transientRetryNotBefore.toISOString() }
              : {}),
            ...(codexTransientFallbackMode ? { codexTransientFallbackMode } : {}),
          }, "normal_model"),
          status: "queued",
          requestedByActorType: "system",
          requestedByActorId: null,
          idempotencyKey: continuationRetryIdempotencyKey,
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      const scheduledRun = await tx
        .insert(heartbeatRuns)
        .values({
          companyId: run.companyId,
          agentId: run.agentId,
          invocationSource: "automation",
          triggerDetail: "system",
          status: "scheduled_retry",
          wakeupRequestId: wakeupRequest.id,
          contextSnapshot: retryContextSnapshot,
          responsibleUserId,
          sessionIdBefore: sessionBefore,
          retryOfRunId: run.id,
          scheduledRetryAt: schedule.dueAt,
          scheduledRetryAttempt: schedule.attempt,
          scheduledRetryReason: retryReason,
          continuationAttempt: readContinuationAttempt(retryContextSnapshot.livenessContinuationAttempt),
          updatedAt: now,
        })
        .returning()
        .then((rows) => rows[0]);

      await tx
        .update(agentWakeupRequests)
        .set({
          runId: scheduledRun.id,
          updatedAt: now,
        })
        .where(eq(agentWakeupRequests.id, wakeupRequest.id));

      let detachWorkspaceFromIssue = false;
      if (issueId && shouldQuarantineWorkspaceForRetry) {
        const issueWorkspace = await tx
          .select({
            id: issues.id,
            companyId: issues.companyId,
            executionWorkspaceId: issues.executionWorkspaceId,
          })
          .from(issues)
          .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
          .for("update")
          .then((rows) => rows[0] ?? null);
        const failedExecutionWorkspaceId =
          readNonEmptyString(workspaceValidationRetryPayload?.executionWorkspaceId) ??
          readNonEmptyString(issueWorkspace?.executionWorkspaceId);

        if (issueWorkspace && failedExecutionWorkspaceId) {
          const failedWorkspace = await tx
            .select({
              id: executionWorkspaces.id,
              companyId: executionWorkspaces.companyId,
              sourceIssueId: executionWorkspaces.sourceIssueId,
              status: executionWorkspaces.status,
              metadata: executionWorkspaces.metadata,
            })
            .from(executionWorkspaces)
            .where(and(
              eq(executionWorkspaces.id, failedExecutionWorkspaceId),
              eq(executionWorkspaces.companyId, run.companyId),
            ))
            .for("update")
            .then((rows) => rows[0] ?? null);

          const workspaceBelongsToIssue =
            failedWorkspace
              ? failedWorkspace.sourceIssueId === issueId
              : false;

          if (
            failedWorkspace &&
            workspaceBelongsToIssue &&
            issueWorkspace.executionWorkspaceId === failedExecutionWorkspaceId
          ) {
            const existingMetadata = parseObject(failedWorkspace.metadata);
            const quarantine = {
              reason: WORKSPACE_VALIDATION_FAILURE_CODE,
              retryReason,
              sourceRunId: run.id,
              retryRunId: scheduledRun.id,
              issueId,
              sourceIssueId: failedWorkspace.sourceIssueId ?? null,
              quarantinedAt: now.toISOString(),
              workspaceValidation: workspaceValidationRetryPayload ?? {},
            };
            await tx
              .update(executionWorkspaces)
              .set({
                status: "archived",
                closedAt: now,
                cleanupEligibleAt: null,
                cleanupReason: WORKSPACE_VALIDATION_FAILURE_CODE,
                metadata: {
                  ...existingMetadata,
                  workspaceValidationQuarantine: quarantine,
                },
                updatedAt: now,
              })
              .where(and(
                eq(executionWorkspaces.id, failedWorkspace.id),
                eq(executionWorkspaces.companyId, run.companyId),
              ));

            await logActivity(tx as unknown as Db, {
              companyId: run.companyId,
              actorType: "system",
              actorId: "heartbeat",
              agentId: run.agentId,
              runId: run.id,
              action: "execution_workspace.workspace_validation_quarantined",
              entityType: "execution_workspace",
              entityId: failedWorkspace.id,
              details: quarantine,
            });
            detachWorkspaceFromIssue = issueWorkspace.executionWorkspaceId === failedExecutionWorkspaceId;
          }
        }
      }

      if (issueId) {
        await tx
          .update(issues)
          .set({
            executionRunId: scheduledRun.id,
            executionAgentNameKey: normalizeAgentNameKey(agent.name),
            executionLockedAt: now,
            ...(detachWorkspaceFromIssue
              ? {
                  executionWorkspaceId: null,
                  executionWorkspacePreference: null,
                }
              : {}),
            updatedAt: now,
          })
          .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId), eq(issues.executionRunId, run.id)));
      }

      return {
        outcome: "scheduled",
        run: scheduledRun,
        reusedExisting: false,
      };
    });

    if (scheduleResult.outcome === "not_scheduled") {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: scheduleResult.reason,
        payload: {
          retryReason,
          scheduledRetryAttempt: nextAttempt,
          maxAttempts,
          ...scheduleResult.details,
        },
      });
      return {
        outcome: "not_scheduled" as const,
        reason: scheduleResult.reason,
        errorCode: scheduleResult.errorCode,
        issueId: scheduleResult.issueId,
      };
    }

    const retryRun = scheduleResult.run;
    const dueAt = retryRun.scheduledRetryAt ? new Date(retryRun.scheduledRetryAt) : schedule.dueAt;

    if (scheduleResult.reusedExisting) {
      await appendRunEvent(run, await nextRunEventSeq(run.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "info",
        message: `Reused existing continuation retry ${retryRun.scheduledRetryAttempt}/${schedule.maxAttempts}`,
        payload: {
          retryRunId: retryRun.id,
          retryReason,
          idempotencyKey: continuationRetryIdempotencyKey,
          scheduledRetryAttempt: retryRun.scheduledRetryAttempt,
          scheduledRetryAt: dueAt.toISOString(),
        },
      });

      return {
        outcome: "scheduled" as const,
        run: retryRun,
        dueAt,
        attempt: retryRun.scheduledRetryAttempt,
        maxAttempts: schedule.maxAttempts,
        reusedExisting: true,
      };
    }

    await appendRunEvent(run, await nextRunEventSeq(run.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: `Scheduled bounded retry ${schedule.attempt}/${schedule.maxAttempts} for ${schedule.dueAt.toISOString()}`,
      payload: {
        retryRunId: retryRun.id,
        retryReason,
        // Carry the failing errorCode so a recurring, code-specific failure
        // (e.g. pr_review_output_missing evidence-loss) is distinguishable from
        // a generic transient blip in the retry event alone, without having to
        // cross-reference the originating run's errorCode.
        ...(run.errorCode ? { errorCode: run.errorCode } : {}),
        ...(transientRecovery ? { errorFamily: transientRecovery.errorFamily } : {}),
        scheduledRetryAttempt: schedule.attempt,
        scheduledRetryAt: schedule.dueAt.toISOString(),
        baseDelayMs: schedule.baseDelayMs,
        delayMs: schedule.delayMs,
        ...(transientRetryNotBefore ? { transientRetryNotBefore: transientRetryNotBefore.toISOString() } : {}),
        ...(transientRecovery?.errorFamily === "provider_quota" && transientRetryNotBefore
          ? { providerQuotaRetryNotBefore: transientRetryNotBefore.toISOString() }
          : {}),
        ...(codexTransientFallbackMode ? { codexTransientFallbackMode } : {}),
      },
    });

    if (retryReason === INTERACTION_CONTINUATION_INFRA_RETRY_REASON) {
      await recordPlanApprovalResumeFailureRetry({
        run,
        issueId,
        retryRunId: retryRun.id,
        attempt: schedule.attempt,
        maxAttempts: schedule.maxAttempts,
      }).catch((error) => {
        logger.warn(
          { err: error, runId: run.id, issueId, retryRunId: retryRun.id },
          "failed to record plan-approval resume retry failure",
        );
      });
    }

    return {
      outcome: "scheduled" as const,
      run: retryRun,
      dueAt,
      attempt: schedule.attempt,
      maxAttempts: schedule.maxAttempts,
    };
  }

  async function scheduleInteractionContinuationInfrastructureRetryIfEligible(
    run: typeof heartbeatRuns.$inferSelect,
    agent: typeof agents.$inferSelect,
  ) {
    if (!run.wakeupRequestId) return null;
    if (!isResolvedInteractionContinuationWakeContext(run.contextSnapshot)) return null;
    if (!isRetryableInteractionContinuationInfrastructureFailure(run)) {
      const context = parseObject(run.contextSnapshot);
      const issueId = readNonEmptyString(context.issueId);
      await escalatePlanApprovalResumeFailureNeedsAttention({
        run,
        issueId,
        attempt: Math.min(run.scheduledRetryAttempt ?? INTERACTION_CONTINUATION_INFRA_MAX_ATTEMPTS, INTERACTION_CONTINUATION_INFRA_MAX_ATTEMPTS),
        maxAttempts: INTERACTION_CONTINUATION_INFRA_MAX_ATTEMPTS,
      }).catch((error) => {
        logger.warn(
          { err: error, runId: run.id, issueId },
          "failed to escalate non-retryable plan-approval resume failure",
        );
      });
      return null;
    }

    return scheduleBoundedRetryForRun(run, agent, {
      retryReason: INTERACTION_CONTINUATION_INFRA_RETRY_REASON,
      wakeReason: INTERACTION_CONTINUATION_INFRA_WAKE_REASON,
      maxAttempts: INTERACTION_CONTINUATION_INFRA_MAX_ATTEMPTS,
    });
  }

  async function promoteDueScheduledRetries(now = new Date()) {
    const cutoff = await getWorktreeExecutionCutoff();
    const dueRuns = await db
      .select()
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.status, "scheduled_retry"),
          lte(heartbeatRuns.scheduledRetryAt, now),
          cutoff ? gte(heartbeatRuns.createdAt, cutoff) : undefined,
        ),
      )
      .orderBy(asc(heartbeatRuns.scheduledRetryAt), asc(heartbeatRuns.createdAt), asc(heartbeatRuns.id))
      .limit(50);

    const promotedRunIds: string[] = [];

    for (const dueRun of dueRuns) {
      const result = await promoteScheduledRetryRun(dueRun, now);
      if (result.outcome === "promoted") {
        promotedRunIds.push(result.run.id);
      }
    }

    return {
      promoted: promotedRunIds.length,
      runIds: promotedRunIds,
    };
  }

  async function getIssueRetryRun(
    companyId: string,
    issueId: string,
    statuses: Array<"scheduled_retry" | "queued" | "running" | "cancelled">,
  ) {
    if (statuses.length === 0) return null;
    return db
      .select({
        run: heartbeatRuns,
        agentName: agents.name,
      })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(
        and(
          eq(heartbeatRuns.companyId, companyId),
          inArray(heartbeatRuns.status, statuses),
          sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' = ${issueId}`,
          sql`${heartbeatRuns.retryOfRunId} is not null`,
        ),
      )
      .orderBy(desc(heartbeatRuns.updatedAt), desc(heartbeatRuns.createdAt), desc(heartbeatRuns.id))
      .limit(1)
      .then((rows) => rows[0] ?? null);
  }

  function summarizeIssueScheduledRetryRun(
    row: { run: typeof heartbeatRuns.$inferSelect; agentName: string | null },
  ) {
    return {
      runId: row.run.id,
      status: row.run.status as "scheduled_retry" | "queued" | "running" | "cancelled",
      agentId: row.run.agentId,
      agentName: row.agentName,
      retryOfRunId: row.run.retryOfRunId,
      scheduledRetryAt: row.run.scheduledRetryAt,
      scheduledRetryAttempt: row.run.scheduledRetryAttempt,
      scheduledRetryReason: row.run.scheduledRetryReason,
      error: row.run.error,
      errorCode: row.run.errorCode,
    };
  }

  async function retryScheduledRetryNow(input: {
    issueId: string;
    actor?: { actorType?: "user" | "agent" | "system"; actorId?: string | null };
    now?: Date;
  }) {
    const now = input.now ?? new Date();
    const issue = await db
      .select({ id: issues.id, companyId: issues.companyId })
      .from(issues)
      .where(eq(issues.id, input.issueId))
      .then((rows) => rows[0] ?? null);
    if (!issue) throw notFound("Issue not found");

    const scheduled = await getIssueRetryRun(issue.companyId, issue.id, ["scheduled_retry"]);
    if (!scheduled) {
      const alreadyPromoted = await getIssueRetryRun(issue.companyId, issue.id, ["queued", "running"]);
      if (alreadyPromoted) {
        return {
          outcome: "already_promoted" as const,
          message: "Scheduled retry was already promoted",
          scheduledRetry: summarizeIssueScheduledRetryRun(alreadyPromoted),
        };
      }
      return {
        outcome: "no_scheduled_retry" as const,
        message: "No live scheduled retry exists for this issue",
        scheduledRetry: null,
      };
    }

    const contextSnapshot = {
      ...parseObject(scheduled.run.contextSnapshot),
      scheduledRetryAt: now.toISOString(),
      retryNowRequestedAt: now.toISOString(),
      retryNowRequestedByActorType: input.actor?.actorType ?? null,
      retryNowRequestedByActorId: input.actor?.actorId ?? null,
    };

    const updated = await db.transaction(async (tx) => {
      const row = await tx
        .update(heartbeatRuns)
        .set({
          scheduledRetryAt: now,
          contextSnapshot,
          updatedAt: now,
        })
        .where(and(eq(heartbeatRuns.id, scheduled.run.id), eq(heartbeatRuns.status, "scheduled_retry")))
        .returning()
        .then((rows) => rows[0] ?? null);
      if (!row) return null;

      if (row.wakeupRequestId) {
        const wakeupPayload = {
          ...(parseObject(
            await tx
              .select({ payload: agentWakeupRequests.payload })
              .from(agentWakeupRequests)
              .where(eq(agentWakeupRequests.id, row.wakeupRequestId))
              .then((rows) => rows[0]?.payload ?? null),
          )),
          scheduledRetryAt: now.toISOString(),
          retryNowRequestedAt: now.toISOString(),
        };
        await tx
          .update(agentWakeupRequests)
          .set({
            payload: wakeupPayload,
            updatedAt: now,
          })
          .where(eq(agentWakeupRequests.id, row.wakeupRequestId));
      }

      return row;
    });

    if (!updated) {
      const alreadyPromoted = await getIssueRetryRun(issue.companyId, issue.id, ["queued", "running"]);
      if (alreadyPromoted) {
        return {
          outcome: "already_promoted" as const,
          message: "Scheduled retry was already promoted",
          scheduledRetry: summarizeIssueScheduledRetryRun(alreadyPromoted),
        };
      }
      return {
        outcome: "no_scheduled_retry" as const,
        message: "No live scheduled retry exists for this issue",
        scheduledRetry: null,
      };
    }

    await appendRunEvent(updated, await nextRunEventSeq(updated.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "info",
      message: "Scheduled retry was requested to run now",
      payload: {
        issueId: issue.id,
        scheduledRetryAttempt: updated.scheduledRetryAttempt,
        scheduledRetryAt: updated.scheduledRetryAt ? new Date(updated.scheduledRetryAt).toISOString() : null,
        scheduledRetryReason: updated.scheduledRetryReason,
        requestedByActorType: input.actor?.actorType ?? null,
        requestedByActorId: input.actor?.actorId ?? null,
      },
    });

    const promotion = await promoteScheduledRetryRun(updated, now);
    const promotedRow = await getIssueRetryRun(issue.companyId, issue.id, ["queued", "running", "cancelled"]);
    const scheduledRetry = promotedRow
      ? summarizeIssueScheduledRetryRun(promotedRow)
      : summarizeIssueScheduledRetryRun({ run: promotion.run ?? updated, agentName: scheduled.agentName });

    if (promotion.outcome === "promoted") {
      return {
        outcome: "promoted" as const,
        message: "Scheduled retry was promoted to the queued run pool",
        scheduledRetry,
      };
    }
    if (promotion.outcome === "gate_suppressed") {
      return {
        outcome: "gate_suppressed" as const,
        message: promotion.reason,
        scheduledRetry,
      };
    }
    return {
      outcome: "already_promoted" as const,
      message: "Scheduled retry was already promoted",
      scheduledRetry,
    };
  }

  function parseHeartbeatPolicy(agent: typeof agents.$inferSelect) {
    return resolveHeartbeatPolicyForRuntimeConfig(agent.runtimeConfig);
  }

  function normalizeOptionalNonNegativeInteger(value: unknown) {
    if (value === null || value === undefined || value === "") return null;
    const normalized = Math.floor(asNumber(value, 0));
    return normalized >= 0 ? normalized : null;
  }

  function currentUtcDayWindow(now = new Date()) {
    const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0, 0));
    const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1, 0, 0, 0, 0));
    return { start, end };
  }

  async function getHeartbeatDailyCapBlock(
    agent: typeof agents.$inferSelect,
    policy: ReturnType<typeof parseHeartbeatPolicy>,
    options: { checkRunCap?: boolean; checkCostCap?: boolean; excludeRunId?: string | null } = {},
    client: Pick<Db, "select"> = db,
  ) {
    const checkRunCap = options.checkRunCap ?? true;
    const checkCostCap = options.checkCostCap ?? true;
    const { start, end } = currentUtcDayWindow();
    if (checkRunCap && policy.maxDailyRuns !== null) {
      const conditions = [
        eq(heartbeatRuns.companyId, agent.companyId),
        eq(heartbeatRuns.agentId, agent.id),
        gte(heartbeatRuns.startedAt, start),
        lt(heartbeatRuns.startedAt, end),
        notInArray(heartbeatRuns.status, ["queued", "scheduled_retry"]),
      ];
      if (options.excludeRunId) {
        conditions.push(sql`${heartbeatRuns.id} <> ${options.excludeRunId}`);
      }
      const [row] = await client
        .select({ total: sql<number>`count(*)::integer` })
        .from(heartbeatRuns)
        .where(and(...conditions));
      const observed = Number(row?.total ?? 0);
      if (observed >= policy.maxDailyRuns) {
        return {
          reason: "heartbeat.daily_run_limit",
          observed,
          limit: policy.maxDailyRuns,
        };
      }
    }

    if (checkCostCap && policy.maxDailyCostCents !== null) {
      const [row] = await client
        .select({ total: sql<number>`coalesce(sum(${costEvents.costCents})::bigint, 0)` })
        .from(costEvents)
        .where(
          and(
            eq(costEvents.companyId, agent.companyId),
            eq(costEvents.agentId, agent.id),
            gte(costEvents.occurredAt, start),
            lt(costEvents.occurredAt, end),
          ),
        );
      const observed = Number(row?.total ?? 0);
      if (observed >= policy.maxDailyCostCents) {
        return {
          reason: "heartbeat.daily_cost_limit",
          observed,
          limit: policy.maxDailyCostCents,
        };
      }
    }

    return null;
  }

  async function cancelQueuedRunForHeartbeatDailyCap(
    run: typeof heartbeatRuns.$inferSelect,
    dailyCapBlock: NonNullable<Awaited<ReturnType<typeof getHeartbeatDailyCapBlock>>>,
  ) {
    const now = new Date();
    const reason = "Cancelled because the agent reached a per-day heartbeat budget cap before adapter invocation";
    const cancelled = await setRunStatus(run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: dailyCapBlock.reason,
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: dailyCapBlock.reason,
        observed: dailyCapBlock.observed,
        limit: dailyCapBlock.limit,
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "heartbeat_daily_cap_gate",
        timeoutFired: false,
      },
    });
    if (!cancelled) return null;

    await setWakeupStatus(run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: reason,
    });

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: reason,
      payload: {
        reason: dailyCapBlock.reason,
        observed: dailyCapBlock.observed,
        limit: dailyCapBlock.limit,
      },
    });

    await releaseIssueExecutionAndPromote(cancelled, { suppressImmediateRecovery: true });

    return cancelled;
  }

  async function hasActionableTimerWork(agent: typeof agents.$inferSelect) {
    const row = await db
      .select({ id: issues.id })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, agent.companyId),
          eq(issues.assigneeAgentId, agent.id),
          isNull(issues.assigneeUserId),
          isNull(issues.hiddenAt),
          inArray(issues.status, [...TIMER_ACTIONABLE_ISSUE_STATUSES]),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    return Boolean(row);
  }

  async function markTimerHeartbeatChecked(agentId: string, source: WakeupOptions["source"]) {
    if (source !== "timer") return;
    await db
      .update(agents)
      .set({
        lastHeartbeatAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(agents.id, agentId));
  }

  function parseMaxTurnContinuationPolicy(agent: typeof agents.$inferSelect): MaxTurnContinuationPolicy {
    const runtimeConfig = parseObject(agent.runtimeConfig);
    const heartbeat = parseObject(runtimeConfig.heartbeat);
    const configured = parseObject(heartbeat.maxTurnContinuation);
    const rawMaxAttempts = Math.floor(asNumber(configured.maxAttempts, MAX_TURN_CONTINUATION_DEFAULT_MAX_ATTEMPTS));
    const rawDelayMs = Math.floor(asNumber(configured.delayMs, MAX_TURN_CONTINUATION_DEFAULT_DELAY_MS));

    return {
      enabled: asBoolean(configured.enabled, true),
      maxAttempts: Math.max(0, Math.min(MAX_TURN_CONTINUATION_MAX_ATTEMPTS_CAP, rawMaxAttempts)),
      delayMs: Math.max(0, Math.min(MAX_TURN_CONTINUATION_MAX_DELAY_MS, rawDelayMs)),
    };
  }

  function issueRunPriorityRank(priority: string | null | undefined) {
    switch (priority) {
      case "critical":
        return 0;
      case "high":
        return 1;
      case "medium":
        return 2;
      case "low":
        return 3;
      default:
        return 4;
    }
  }

  async function listQueuedRunDependencyReadiness(
    companyId: string,
    queuedRuns: Array<typeof heartbeatRuns.$inferSelect>,
  ) {
    const issueIds = [...new Set(
      queuedRuns
        .map((run) => readNonEmptyString(parseObject(run.contextSnapshot).issueId))
        .filter((issueId): issueId is string => Boolean(issueId && UUID_PATTERN.test(issueId))),
    )];
    if (issueIds.length === 0) {
      return new Map<string, Awaited<ReturnType<typeof issuesSvc.getDependencyReadiness>>>();
    }
    return issuesSvc.listDependencyReadiness(companyId, issueIds);
  }

  async function countRunningRunsForAgent(agentId: string) {
    const [{ count }] = await db
      .select({ count: sql<number>`count(*)` })
      .from(heartbeatRuns)
      .where(and(eq(heartbeatRuns.agentId, agentId), eq(heartbeatRuns.status, "running")));
    return Number(count ?? 0);
  }

  async function listRunningRunsForAgent(agentId: string) {
    return db
      .select({
        id: heartbeatRuns.id,
        contextSnapshot: heartbeatRuns.contextSnapshot,
        startedAt: heartbeatRuns.startedAt,
        lastOutputAt: heartbeatRuns.lastOutputAt,
        lastUsefulActionAt: heartbeatRuns.lastUsefulActionAt,
      })
      .from(heartbeatRuns)
      .where(and(eq(heartbeatRuns.agentId, agentId), eq(heartbeatRuns.status, "running")));
  }

  async function hasAdapterInvocationEvent(runId: string) {
    const row = await db
      .select({ id: heartbeatRunEvents.id })
      .from(heartbeatRunEvents)
      .where(and(eq(heartbeatRunEvents.runId, runId), eq(heartbeatRunEvents.eventType, "adapter.invoke")))
      .limit(1)
      .then((rows) => rows[0] ?? null);
    return row !== null;
  }

  async function claimQueuedRun(run: typeof heartbeatRuns.$inferSelect, companyAgents?: AgentOrgRow[]) {
    if (run.status !== "queued") return run;
    const agent = await getAgent(run.agentId);
    if (!agent) {
      await cancelRunInternal(run.id, "Cancelled because the agent no longer exists");
      return null;
    }
    const invokability = companyAgents
      ? evaluateAgentInvokability(toAgentOrgRow(agent), companyAgents)
      : await getAgentInvokability(agent);
    if (!invokability.invokable) {
      await cancelRunInternal(run.id, `Cancelled because the agent is not invokable: ${invokability.reason}`);
      return null;
    }

    const context = parseObject(run.contextSnapshot);
    if (isK8sIsolationRetryDeferred(context)) {
      return null;
    }
    const budgetBlock = await budgets.getInvocationBlock(run.companyId, run.agentId, {
      issueId: readNonEmptyString(context.issueId),
      projectId: readNonEmptyString(context.projectId),
    });
    if (budgetBlock) {
      await cancelRunInternal(run.id, budgetBlock.reason);
      return null;
    }

    const dailyCapBlock = await getHeartbeatDailyCapBlock(agent, parseHeartbeatPolicy(agent), {
      excludeRunId: run.id,
      checkRunCap: true,
      checkCostCap: true,
    });
    if (dailyCapBlock) {
      await cancelQueuedRunForHeartbeatDailyCap(run, dailyCapBlock);
      return null;
    }

    const issueId = readNonEmptyString(context.issueId);
    // The scan and readiness collectors UUID-screen this value so one malformed
    // row cannot abort a whole dispatch pass. Screening alone, though, leaves
    // the row itself queued forever: it is skipped by every batch lookup, then
    // reaches the single-issue readiness call below, which still binds it to a
    // uuid column and raises 22P02 on every pass for as long as the row exists.
    // An id that cannot be a uuid can never resolve to an issue, so prune it
    // here instead — this ticket's contract is that invalid queued rows
    // converge to zero, not merely that they stop being fatal. CAS on
    // status='queued' so concurrent passes yield one transition and one event.
    if (issueId && !UUID_PATTERN.test(issueId)) {
      const now = new Date();
      const outcome = await setRunStatusIfQueued(run.id, "cancelled", {
        finishedAt: now,
        error: `Queued run context references an unparseable issue id: ${issueId}`,
        errorCode: "invalid_context_issue_id",
      });
      if (outcome.updated) {
        await setWakeupStatus(run.wakeupRequestId, "skipped", {
          finishedAt: now,
          error: "Queued run context references an unparseable issue id",
        });
        logger.warn(
          { runId: run.id, agentId: run.agentId, issueId },
          "claimQueuedRun: cancelled queued run with an unparseable context issue id",
        );
      }
      return null;
    }
    if (issueId) {
      const activePauseHold = await treeControlSvc.getActivePauseHoldGate(run.companyId, issueId);
      const treeHoldInteractionWake = activePauseHold && await isVerifiedIssueTreeControlInteractionWake(db, {
        companyId: run.companyId,
        issueId,
        agentId: run.agentId,
        runId: run.id,
        wakeupRequestId: run.wakeupRequestId,
        contextSnapshot: context,
      });
      if (activePauseHold && !treeHoldInteractionWake) {
        await cancelRunInternal(run.id, "Cancelled because issue is held by an active subtree pause hold");
        await logActivity(db, {
          companyId: run.companyId,
          actorType: "system",
          actorId: "system",
          agentId: run.agentId,
          runId: run.id,
          action: "issue.tree_hold_run_interrupted",
          entityType: "heartbeat_run",
          entityId: run.id,
          issueId: issueId,
          details: {
            issueId,
            holdId: activePauseHold.holdId,
            rootIssueId: activePauseHold.rootIssueId,
            source: "heartbeat.claim_queued_run",
            securityPrinciples: ["Complete Mediation", "Fail Securely", "Secure Defaults"],
          },
        });
        return null;
      }

      const dependencyReadiness = await issuesSvc.listDependencyReadiness(run.companyId, [issueId]);
      const readiness = dependencyReadiness.get(issueId);
      const unresolvedBlockerCount = readiness?.unresolvedBlockerCount ?? 0;
      if (unresolvedBlockerCount > 0 && !allowsIssueInteractionWake(context)) {
        await cancelQueuedRunForBlockedDependencies(run, issueId, readiness?.unresolvedBlockerIssueIds ?? []);
        logger.info({ runId: run.id, issueId, unresolvedBlockerCount }, "claimQueuedRun: cancelled blocked queued run");
        return null;
      }

      const staleness = await evaluateQueuedRunStaleness(run, issueId, context);
      if (staleness.stale) {
        await cancelQueuedRunForStaleIssue(run, issueId, staleness);
        logger.info(
          { runId: run.id, issueId, errorCode: staleness.errorCode },
          "claimQueuedRun: cancelled stale queued run",
        );
        return null;
      }
    }

    const claimedAt = new Date();
    const responsibleUserId = await resolveResponsibleUserIdForRun({
      run,
      contextSnapshot: context,
      issueContext: issueId ? await getIssueExecutionContext(run.companyId, issueId) : null,
      routineEnvContext: { routineId: null, env: null, responsibleUserId: null },
    });
    const prReviewTaskKey = readNonEmptyString(context.taskKey) ?? run.contextTaskKey;
    const exclusivePrReviewTaskKey = prReviewTaskKey && isPrReviewRetryContext(context)
      ? prReviewTaskKey
      : null;
    const initiallyClaimed = hasExternalLifecycle(agent.adapterType)
      ? (await claimRunWithExternalRuntimeSlotPool(
          db,
          run.id,
          claimedAt,
          resolveExternalLifecycleConcurrency(parseHeartbeatPolicy(agent)).effectiveMaxConcurrentRuns,
          exclusivePrReviewTaskKey ? { exclusivePrReviewTaskKey } : {},
        ))?.run ?? null
      : exclusivePrReviewTaskKey
      ? await db.transaction(async (tx) => {
          if (!(await canClaimPrReviewTask(tx, exclusivePrReviewTaskKey))) return null;
          return tx
            .update(heartbeatRuns)
            .set({
              status: "running",
              error: null,
              errorCode: null,
              responsibleUserId,
              startedAt: run.startedAt ?? claimedAt,
              updatedAt: claimedAt,
            })
            .where(and(eq(heartbeatRuns.id, run.id), eq(heartbeatRuns.status, "queued")))
            .returning()
            .then((rows) => rows[0] ?? null);
        })
      : await db
        .update(heartbeatRuns)
        .set({
          status: "running",
          error: null,
          errorCode: null,
          responsibleUserId,
          startedAt: run.startedAt ?? claimedAt,
          updatedAt: claimedAt,
        })
        .where(and(eq(heartbeatRuns.id, run.id), eq(heartbeatRuns.status, "queued")))
        .returning()
        .then((rows) => rows[0] ?? null);
    const claimed = initiallyClaimed && hasExternalLifecycle(agent.adapterType)
      ? await db
          .update(heartbeatRuns)
          .set({ responsibleUserId, updatedAt: claimedAt })
          .where(eq(heartbeatRuns.id, initiallyClaimed.id))
          .returning()
          .then((rows) => rows[0] ?? initiallyClaimed)
      : initiallyClaimed;
    if (!claimed) return null;

    publishLiveEvent({
      companyId: claimed.companyId,
      type: "heartbeat.run.status",
      payload: {
        runId: claimed.id,
        agentId: claimed.agentId,
        status: claimed.status,
        invocationSource: claimed.invocationSource,
        triggerDetail: claimed.triggerDetail,
        error: claimed.error ?? null,
        errorCode: claimed.errorCode ?? null,
        startedAt: claimed.startedAt ? new Date(claimed.startedAt).toISOString() : null,
        finishedAt: claimed.finishedAt ? new Date(claimed.finishedAt).toISOString() : null,
      },
    });
    publishRunLifecyclePluginEvent(claimed);

    await setWakeupStatus(claimed.wakeupRequestId, "claimed", { claimedAt });

    // Fix A (lazy locking): stamp executionRunId now that the run is actually running,
    // not at queue time. Guard is idempotent — safe if called more than once.
    const claimedContext = parseObject(claimed.contextSnapshot);
    const claimedIssueId = readNonEmptyString(claimedContext.issueId);
    const claimedWakeReason = readNonEmptyString(claimedContext.wakeReason);
    if (claimedIssueId && claimedWakeReason !== "source_scoped_recovery_action") {
      const routineLockOwner = await findOpenRoutineExecutionLockOwnerForIssue(claimed.companyId, claimedIssueId);
      if (routineLockOwner) {
        await cancelClaimedRunForRoutineExecutionDuplicate({
          run: claimed,
          issueId: claimedIssueId,
          lockOwner: routineLockOwner,
        });
        logger.info(
          {
            runId: claimed.id,
            issueId: claimedIssueId,
            ownerIssueId: routineLockOwner.id,
            ownerExecutionRunId: routineLockOwner.executionRunId,
          },
          "claimQueuedRun: cancelled duplicate routine execution run",
        );
        return null;
      }

      const claimedAgent = await getAgent(claimed.agentId);
      const issueLockRequired = !allowsIssueInteractionWake(claimedContext);
      let claimedIssueLock: Pick<typeof issues.$inferSelect, "id" | "executionRunId"> | null = null;
      try {
        claimedIssueLock = await db
          .update(issues)
          .set({
            executionRunId: claimed.id,
            executionAgentNameKey: normalizeAgentNameKey(claimedAgent?.name),
            executionLockedAt: claimedAt,
            updatedAt: claimedAt,
          })
          .where(
            and(
              eq(issues.id, claimedIssueId),
              eq(issues.companyId, claimed.companyId),
              // Mention/context runs can touch an issue, but only the current assignee
              // owns the issue execution lock shown as the active run.
              eq(issues.assigneeAgentId, claimed.agentId),
              or(isNull(issues.executionRunId), eq(issues.executionRunId, claimed.id)),
            ),
          )
          .returning({ id: issues.id, executionRunId: issues.executionRunId })
          .then((rows) => rows[0] ?? null);
      } catch (error) {
        if (!isOpenRoutineExecutionUniqueViolation(error)) throw error;
        const racedLockOwner = await findOpenRoutineExecutionLockOwnerForIssue(claimed.companyId, claimedIssueId);
        if (!racedLockOwner) throw error;
        await cancelClaimedRunForRoutineExecutionDuplicate({
          run: claimed,
          issueId: claimedIssueId,
          lockOwner: racedLockOwner,
        });
        logger.info(
          {
            runId: claimed.id,
            issueId: claimedIssueId,
            ownerIssueId: racedLockOwner.id,
            ownerExecutionRunId: racedLockOwner.executionRunId,
          },
          "claimQueuedRun: cancelled duplicate routine execution run after lock race",
        );
        return null;
      }

      if (issueLockRequired && !claimedIssueLock) {
        await cancelClaimedRunForIssueLockNotAcquired(claimed, claimedIssueId);
        logger.info(
          {
            runId: claimed.id,
            issueId: claimedIssueId,
            agentId: claimed.agentId,
          },
          "claimQueuedRun: cancelled run because issue execution lock was not acquired",
        );
        return null;
      }
    }

    return claimed;
  }

  async function cancelQueuedRunForBlockedDependencies(
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
    unresolvedBlockerIssueIds: string[],
  ) {
    const now = new Date();
    const reason =
      "Cancelled because issue dependencies are still blocked; Paperclip will wake the assignee when blockers resolve";
    const cancelled = await setRunStatus(run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: "issue_dependencies_blocked",
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: "issue_dependencies_blocked",
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "dependency_gate",
        timeoutFired: false,
      },
    });
    if (!cancelled) return null;

    await setWakeupStatus(run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: reason,
    });

    await db
      .update(issues)
      .set({
        executionRunId: null,
        executionAgentNameKey: null,
        executionLockedAt: null,
        updatedAt: now,
      })
      .where(
        and(
          eq(issues.companyId, run.companyId),
          eq(issues.id, issueId),
          eq(issues.executionRunId, run.id),
        ),
      );

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: reason,
      payload: {
        issueId,
        unresolvedBlockerIssueIds,
      },
    });

    return cancelled;
  }

  type QueuedRunStaleness =
    | { stale: false }
    | {
        stale: true;
        reason: string;
        errorCode:
          | "issue_not_found"
          | "issue_assignee_changed"
          | "issue_terminal_status"
          | "issue_not_in_progress"
          | "issue_execution_lock_changed"
          | "issue_review_participant_changed"
          | "issue_continuation_waiting_on_review";
        details: Record<string, unknown>;
      };

  async function evaluateQueuedRunStaleness(
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
    context: Record<string, unknown>,
  ): Promise<QueuedRunStaleness> {
    const issue = await db
      .select({
        id: issues.id,
        status: issues.status,
        assigneeAgentId: issues.assigneeAgentId,
        executionRunId: issues.executionRunId,
        executionState: issues.executionState,
      })
      .from(issues)
      .where(and(eq(issues.id, issueId), eq(issues.companyId, run.companyId)))
      .then((rows) => rows[0] ?? null);

    if (!issue) {
      return {
        stale: true,
        errorCode: "issue_not_found",
        reason: "Cancelled because the target issue no longer exists",
        details: { issueId },
      };
    }

    const wakeCommentId = deriveCommentId(context, null);
    const isInteractionWake = allowsIssueInteractionWake(context);
    const resumeIntent = context.resumeIntent === true || context.followUpRequested === true;
    const wakeReason = readNonEmptyString(context.wakeReason);
    const retryReason = readNonEmptyString(context.retryReason) ?? run.scheduledRetryReason ?? null;
    // Source-scoped recovery wakes target the recovery owner, who is by design
    // a different agent than the source issue's current assignee (the recovery
    // owner is the chain-of-command parent of the failed assignee). The
    // assignee-changed staleness branch below would otherwise cancel every
    // such wake on arrival. Two later call sites in this file already exempt
    // this wake reason for the same reason — see
    // shouldAutoCheckoutIssueForWake (returns false for
    // source_scoped_recovery_action) and the claimQueuedRun post-claim
    // issue-lock block (skips lock stamping for source_scoped_recovery_action).
    // Without this pre-claim exemption those later exemptions are unreachable.
    const isRecoveryOwnerWake = wakeReason === "source_scoped_recovery_action";
    const interactionResolvedAt = readNonEmptyString(context.interactionResolvedAt);
    const hasResolvedInteractionEvidence = interactionResolvedAt !== null && !Number.isNaN(Date.parse(interactionResolvedAt));

    if (
      issue.status === "in_progress" &&
      !wakeCommentId &&
      !hasResolvedInteractionEvidence &&
      (wakeReason === "issue_continuation_needed" || retryReason === "issue_continuation_needed")
    ) {
      const queuedWake = parseObject(context.paperclipWake);
      const queuedContinuationSummary =
        readNonEmptyString(parseObject(context.paperclipContinuationSummary).body) ??
        readNonEmptyString(parseObject(queuedWake.continuationSummary).body);
      const currentContinuationSummary = queuedContinuationSummary
        ? null
        : await getIssueContinuationSummaryDocument(db, issueId);
      const continuationSummaryBody = queuedContinuationSummary ?? currentContinuationSummary?.body ?? null;
      if (continuationSummaryParksExecutor(continuationSummaryBody)) {
        return {
          stale: true,
          errorCode: "issue_continuation_waiting_on_review",
          reason:
            "Cancelled because the continuation summary says the executor should wait for reviewer feedback or approval before more work starts",
          details: {
            issueId,
            wakeReason,
            retryReason,
            nextAction: continuationSummaryBody,
          },
        };
      }
    }

    const reviewExecutionState = issue.status === "in_review"
      ? parseIssueExecutionState(issue.executionState)
      : null;
    const reviewParticipant = reviewExecutionState?.currentParticipant ?? null;
    const isCurrentReviewParticipant = reviewParticipant?.type === "agent" &&
      reviewParticipant.agentId === run.agentId;

    if (
      issue.assigneeAgentId !== run.agentId &&
      !isInteractionWake &&
      !isRecoveryOwnerWake &&
      !isCurrentReviewParticipant
    ) {
      return {
        stale: true,
        errorCode: "issue_assignee_changed",
        reason:
          "Cancelled because issue assignee changed before the queued run could start; the new owner will be woken instead",
        details: {
          issueId,
          previousAssigneeAgentId: run.agentId,
          currentAssigneeAgentId: issue.assigneeAgentId,
        },
      };
    }

    if (issue.status === "done" || issue.status === "cancelled") {
      if (!resumeIntent && !wakeCommentId) {
        return {
          stale: true,
          errorCode: "issue_terminal_status",
          reason: `Cancelled because issue reached terminal status (${issue.status}) before the queued run could start`,
          details: { issueId, currentStatus: issue.status },
        };
      }
    }

    if (requiresInProgressIssueRetry(retryReason) && issue.status !== "in_progress") {
      return {
        stale: true,
        errorCode: "issue_not_in_progress",
        reason: `Cancelled because retry issue is no longer in_progress (current status: ${issue.status}) before the queued run could start`,
        details: { issueId, currentStatus: issue.status, requiredStatus: "in_progress" },
      };
    }

    if (requiresIssueExecutionRetryLock(retryReason) && issue.executionRunId !== run.id) {
      return {
        stale: true,
        errorCode: "issue_execution_lock_changed",
        reason: "Cancelled because retry no longer owns the issue execution lock before the queued run could start",
        details: {
          issueId,
          expectedExecutionRunId: run.id,
          currentExecutionRunId: issue.executionRunId,
        },
      };
    }

    if (issue.status === "in_review") {
      const currentParticipant = reviewExecutionState?.currentParticipant ?? null;
      if (currentParticipant) {
        const participantMatches =
          currentParticipant.type === "agent" && currentParticipant.agentId === run.agentId;
        if (!participantMatches && !wakeCommentId) {
          return {
            stale: true,
            errorCode: "issue_review_participant_changed",
            reason:
              "Cancelled because the in-review participant changed before the queued run could start; the current participant will be woken instead",
            details: {
              issueId,
              currentStageType: reviewExecutionState?.currentStageType ?? null,
              currentParticipant,
            },
          };
        }
      }
    }

    return { stale: false };
  }

  async function cancelQueuedRunForStaleIssue(
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
    staleness: Extract<QueuedRunStaleness, { stale: true }>,
  ) {
    const now = new Date();
    // BLO-20396: CAS on status='queued'. This gate now runs eagerly for every
    // scanned row (not just rows the dispatch walk reaches), so concurrent
    // passes can target the same row — only the winner may emit the
    // cancellation event and release the issue lock.
    const outcome = await setRunStatusIfQueued(run.id, "cancelled", {
      finishedAt: now,
      error: staleness.reason,
      errorCode: staleness.errorCode,
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: staleness.errorCode,
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "stale_queued_run_gate",
        timeoutFired: false,
      },
    });
    if (!outcome.updated) return null;
    const cancelled = outcome.run;

    await setWakeupStatus(run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: staleness.reason,
    });

    await db
      .update(issues)
      .set({
        executionRunId: null,
        executionAgentNameKey: null,
        executionLockedAt: null,
        updatedAt: now,
      })
      .where(
        and(
          eq(issues.companyId, run.companyId),
          eq(issues.id, issueId),
          eq(issues.executionRunId, run.id),
        ),
      );

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: staleness.reason,
      payload: staleness.details,
    });

    return cancelled;
  }

  function isOpenRoutineExecutionUniqueViolation(error: unknown) {
    return Boolean(
      error &&
        typeof error === "object" &&
        "code" in error &&
        (error as { code?: string }).code === "23505" &&
        "constraint" in error &&
        (error as { constraint?: string }).constraint === "issues_open_routine_execution_uq",
    );
  }

  async function findOpenRoutineExecutionLockOwnerForIssue(companyId: string, issueId: string) {
    const target = await db
      .select({
        id: issues.id,
        originKind: issues.originKind,
        originId: issues.originId,
        originFingerprint: issues.originFingerprint,
      })
      .from(issues)
      .where(and(eq(issues.id, issueId), eq(issues.companyId, companyId)))
      .limit(1)
      .then((rows) => rows[0] ?? null);

    if (!target || target.originKind !== "routine_execution" || !target.originId) return null;

    return db
      .select({
        id: issues.id,
        identifier: issues.identifier,
        executionRunId: issues.executionRunId,
      })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, companyId),
          eq(issues.originKind, "routine_execution"),
          eq(issues.originId, target.originId),
          eq(issues.originFingerprint, target.originFingerprint),
          inArray(issues.status, OPEN_ROUTINE_EXECUTION_ISSUE_STATUSES),
          isNull(issues.hiddenAt),
          isNotNull(issues.executionRunId),
          ne(issues.id, issueId),
        ),
      )
      .orderBy(desc(issues.updatedAt), desc(issues.createdAt))
      .limit(1)
      .then((rows) => rows[0] ?? null);
  }

  async function cancelClaimedRunForRoutineExecutionDuplicate(input: {
    run: typeof heartbeatRuns.$inferSelect;
    issueId: string;
    lockOwner: NonNullable<Awaited<ReturnType<typeof findOpenRoutineExecutionLockOwnerForIssue>>>;
  }) {
    const now = new Date();
    const reason =
      "Cancelled because another open routine execution issue already owns this dispatch lock; the owner run will continue the work";
    const cancelled = await setRunStatus(input.run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: "routine_execution_duplicate_suppressed",
      resultJson: {
        ...parseObject(input.run.resultJson),
        stopReason: "routine_execution_duplicate_suppressed",
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "routine_execution_duplicate_gate",
        timeoutFired: false,
      },
    });
    if (!cancelled) return null;

    await setWakeupStatus(input.run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: reason,
    });

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "info",
      message: reason,
      payload: {
        issueId: input.issueId,
        ownerIssueId: input.lockOwner.id,
        ownerIdentifier: input.lockOwner.identifier,
        ownerExecutionRunId: input.lockOwner.executionRunId,
      },
    });

    return cancelled;
  }

  async function cancelClaimedRunForIssueLockNotAcquired(
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
  ) {
    const now = new Date();
    const reason =
      "Cancelled because the run could not acquire the issue execution lock; a current or historical run owns the lock";
    const cancelled = await setRunStatus(run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: "issue_execution_lock_not_acquired",
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: "issue_execution_lock_not_acquired",
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "issue_execution_lock_gate",
        timeoutFired: false,
      },
    });
    if (!cancelled) return null;

    await setWakeupStatus(run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: reason,
    });

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "warn",
      message: reason,
      payload: {
        issueId,
        agentId: run.agentId,
      },
    });

    return cancelled;
  }

  // Two wakeup paths can each insert a queued heartbeat_run for the same
  // (agentId, issueId) on the same tick (user-clicked Retry + dependency
  // fanout + scheduled tick, etc.). Without dedupe, startNextQueuedRunForAgent
  // claims and dispatches both, the second loses the per-issue k8s Job
  // creation race, and surfaces a misleading
  // `Concurrent run blocked: orphaned Job ...` failure in the UI. Cancel the
  // loser at claim time so the surviving sibling does the work cleanly.
  async function cancelQueuedRunForDuplicateDispatch(
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
  ) {
    const now = new Date();
    const reason =
      "Cancelled because a sibling run is already dispatched for this issue; the surviving run will continue the work";
    // BLO-20396: gate on status='queued'. Overlapping dispatch passes used to
    // each report cancelling the same row (the by-id write always "succeeds"),
    // and could stomp a row a concurrent pass had already claimed to `running`.
    // Losing the CAS means someone else already handled this row — stay silent.
    const outcome = await setRunStatusIfQueued(run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: "duplicate_dispatch_suppressed",
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: "duplicate_dispatch_suppressed",
        effectiveTimeoutSec: 0,
        timeoutConfigured: false,
        timeoutSource: "duplicate_dispatch_gate",
        timeoutFired: false,
      },
    });
    if (!outcome.updated) return null;
    const cancelled = outcome.run;

    await setWakeupStatus(run.wakeupRequestId, "skipped", {
      finishedAt: now,
      error: reason,
    });

    await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
      eventType: "lifecycle",
      stream: "system",
      level: "info",
      message: reason,
      payload: { issueId, agentId: run.agentId },
    });

    return cancelled;
  }

  function truncateAgentErrorReason(reason: string | null | undefined): string | null {
    if (!reason) return null;
    const trimmed = reason.trim();
    if (!trimmed) return null;
    return trimmed.length > 500 ? `${trimmed.slice(0, 499)}…` : trimmed;
  }

  /**
   * Last-resort reason for an agent we are about to latch into `error` with
   * nothing to say about why (BLO-19085).
   *
   * `status: error` + `errorReason: null` is the worst state this service can
   * produce: the agent stops, and the record carries no diagnosis, so nothing
   * surfaces the cause and no operator can act. OCMBackendEngineer sat that way
   * for ~15h on 2026-07-30 because the external-runtime reconciler dropped a
   * reason it was already holding. Callers passing a real reason is the fix;
   * this is the floor under them, so a future caller that forgets still leaves
   * a trail back to the run.
   */
  function fallbackAgentErrorReason(
    outcome: "failed" | "timed_out" | string,
    options?: { errorCode?: string | null; runId?: string | null },
  ): string {
    const parts = [`unknown ${outcome} failure: the finalizing path supplied no reason`];
    if (options?.errorCode) parts.push(`errorCode ${options.errorCode}`);
    parts.push(options?.runId ? `see run ${options.runId}` : "no run id was supplied either");
    return parts.join("; ");
  }

  async function finalizeAgentStatus(
    agentId: string,
    outcome: "succeeded" | "interrupted" | "failed" | "cancelled" | "timed_out",
    failureReason?: string | null,
    options?: {
      keepIdleOnFailure?: boolean;
      errorCode?: string | null;
      retryNotBefore?: Date | null;
      /** Run that drove this transition, so a fallback reason can point at it. */
      runId?: string | null;
    },
  ) {
    const existing = await getAgent(agentId);
    if (!existing) return;

    if (existing.status === "paused" || existing.status === "terminated") {
      return;
    }

    const isFirstHeartbeat = !existing.lastHeartbeatAt;

    const runningCount = await countRunningRunsForAgent(agentId);
    // Provider quota exhaustion / Anthropic cap hit is a transient,
    // self-recovering condition — keep the agent idle so the dashboard
    // doesn't show a spurious error AND fire the on-limit hook so
    // ccrotate gets a chance to rotate to a base-tier account.
    //
    // Both error codes route here:
    //  - `provider_quota_exhausted`: legacy/pluggable adapter signal.
    //  - `rate_limit_exhausted`: set by isRateLimitExhausted() when the
    //    run hits 429, 401-cap, or "you've hit your limit" cap text.
    //    Without unifying these, rate-limit-flagged runs flipped agents
    //    to error and the on-limit hook never fired (cluster sat silent
    //    until the cap window rolled — observed 2026-05-05 16:08-17:30Z).
    const recoverable =
      options?.errorCode === "provider_quota_exhausted" ||
      options?.errorCode === "rate_limit_exhausted" ||
      options?.errorCode === "provider_quota";
    const nextStatus =
      runningCount > 0
        ? "running"
        : outcome === "succeeded" ||
          outcome === "interrupted" ||
          outcome === "cancelled" ||
          recoverable ||
          (outcome === "failed" && options?.keepIdleOnFailure)
          ? "idle"
          : "error";

    const updated = await db
      .update(agents)
      .set({
        status: nextStatus,
        // Persist a human-readable reason on the agent record when it enters
        // error so operators see it on the agent page without digging into run
        // events; clear it whenever the agent leaves error.
        //
        // BLO-19085: never write `error` with a null reason. If the caller gave
        // us nothing usable, synthesize one that names the outcome and points at
        // the run, so the agent page always answers "why did this stop?".
        errorReason:
          nextStatus === "error"
            ? (truncateAgentErrorReason(failureReason) ??
              truncateAgentErrorReason(
                fallbackAgentErrorReason(outcome, {
                  errorCode: options?.errorCode,
                  runId: options?.runId,
                }),
              ))
            : null,
        lastHeartbeatAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(agents.id, agentId))
      .returning()
      .then((rows) => rows[0] ?? null);

    if (isFirstHeartbeat && updated) {
      const tc = getTelemetryClient();
      if (tc) trackAgentFirstHeartbeat(tc, { agentRole: updated.role, agentId: updated.id });
    }

    if (updated) {
      publishLiveEvent({
        companyId: updated.companyId,
        type: "agent.status",
        payload: {
          agentId: updated.id,
          status: updated.status,
          lastHeartbeatAt: updated.lastHeartbeatAt
            ? new Date(updated.lastHeartbeatAt).toISOString()
            : null,
          outcome,
        },
      });
    }

    if (recoverable) {
      const hookAgentId = existing.id;
      const hookCompanyId = existing.companyId;
      void runQuotaExhaustedHook({
        db,
        agentId: hookAgentId,
        companyId: hookCompanyId,
        runId: null,
        adapterType: existing.adapterType,
        errorCode: options?.errorCode ?? "provider_quota_exhausted",
        onSuccess: () =>
          enqueueWakeup(hookAgentId, {
            source: "automation",
            triggerDetail: "system",
            reason: "provider_quota_exhausted_recovered",
            requestedByActorType: "system",
            requestedByActorId: "quota-exhausted-hook",
          })
            .then(() => undefined)
            .catch((err) => {
              logger.warn(
                { err, agentId: hookAgentId },
                "failed to wake agent after quota-exhausted hook",
              );
            }),
      }).catch((err) => {
        logger.warn(
          { err, agentId: hookAgentId },
          "quota-exhausted hook crashed",
        );
      });
    }
  }

  function mergeRunStopMetadataForAgent(
    agent: Pick<typeof agents.$inferSelect, "adapterType" | "adapterConfig">,
    outcome: "succeeded" | "interrupted" | "failed" | "cancelled" | "timed_out",
    options?: {
      resultJson?: Record<string, unknown> | null;
      errorCode?: string | null;
      errorMessage?: string | null;
    },
  ) {
    const stopMetadata = buildHeartbeatRunStopMetadata({
      adapterType: agent.adapterType,
      adapterConfig: parseObject(agent.adapterConfig),
      outcome,
      errorCode: options?.errorCode ?? null,
      errorMessage: options?.errorMessage ?? null,
    });
    return mergeHeartbeatRunStopMetadata(options?.resultJson ?? null, stopMetadata);
  }

  function countValue(value: unknown) {
    const parsed = Number(value ?? 0);
    return Number.isFinite(parsed) ? Math.max(0, Math.floor(parsed)) : 0;
  }

  function dateValue(value: unknown) {
    if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
    if (typeof value === "string" || typeof value === "number") {
      const parsed = new Date(value);
      return Number.isNaN(parsed.getTime()) ? null : parsed;
    }
    return null;
  }

  function latestDate(...values: unknown[]) {
    let latest: Date | null = null;
    for (const value of values) {
      const parsed = dateValue(value);
      if (!parsed) continue;
      if (!latest || parsed.getTime() > latest.getTime()) latest = parsed;
    }
    return latest;
  }

  async function buildRunLivenessInput(
    run: typeof heartbeatRuns.$inferSelect,
    resultJson: Record<string, unknown> | null | undefined,
  ): Promise<RunLivenessClassificationInput> {
    const context = parseObject(run.contextSnapshot);
    const contextIssueId = readNonEmptyString(context.issueId);
    const continuationAttempt = asNumber(context.continuationAttempt, run.continuationAttempt ?? 0);

    const issue = contextIssueId
      ? await db
        .select({
          status: issues.status,
          title: issues.title,
          description: issues.description,
        })
        .from(issues)
        .where(and(eq(issues.companyId, run.companyId), eq(issues.id, contextIssueId)))
        .then((rows) => rows[0] ?? null)
      : null;

    const [commentStats] = contextIssueId
      ? await db
        .select({
          count: sql<number>`count(*)::int`,
          latestAt: sql<Date | null>`max(${issueComments.createdAt})`,
        })
        .from(issueComments)
        .where(
          and(
            eq(issueComments.companyId, run.companyId),
            eq(issueComments.issueId, contextIssueId),
            eq(issueComments.createdByRunId, run.id),
            isNull(issueComments.deletedAt),
          ),
        )
      : [{ count: 0, latestAt: null }];

    const issueCommentBodies = contextIssueId
      ? await db
        .select({ body: issueComments.body })
        .from(issueComments)
        .where(
          and(
            eq(issueComments.companyId, run.companyId),
            eq(issueComments.issueId, contextIssueId),
            eq(issueComments.createdByRunId, run.id),
          ),
        )
        .orderBy(desc(issueComments.createdAt), desc(issueComments.id))
        .limit(5)
        .then((rows) => rows.reverse().map((row) => row.body))
      : [];

    const continuationSummary = contextIssueId
      ? await getIssueContinuationSummaryDocument(db, contextIssueId)
      : null;

    const [documentStats] = contextIssueId
      ? await db
        .select({
          count: sql<number>`count(*)::int`,
          planCount: sql<number>`count(*) filter (where ${issueDocuments.key} = 'plan')::int`,
          latestAt: sql<Date | null>`max(${documentRevisions.createdAt})`,
        })
        .from(documentRevisions)
        .innerJoin(issueDocuments, eq(documentRevisions.documentId, issueDocuments.documentId))
        .where(
          and(
            eq(documentRevisions.companyId, run.companyId),
            eq(documentRevisions.createdByRunId, run.id),
            eq(issueDocuments.companyId, run.companyId),
            eq(issueDocuments.issueId, contextIssueId),
            sql`${issueDocuments.key} != ${ISSUE_CONTINUATION_SUMMARY_DOCUMENT_KEY}`,
          ),
        )
      : [{ count: 0, planCount: 0, latestAt: null }];

    const [workProductStats] = contextIssueId
      ? await db
        .select({
          count: sql<number>`count(*)::int`,
          latestAt: sql<Date | null>`max(${issueWorkProducts.createdAt})`,
        })
        .from(issueWorkProducts)
        .where(
          and(
            eq(issueWorkProducts.companyId, run.companyId),
            eq(issueWorkProducts.issueId, contextIssueId),
            eq(issueWorkProducts.createdByRunId, run.id),
          ),
        )
      : [{ count: 0, latestAt: null }];

    const [workspaceOperationStats] = await db
      .select({
        count: sql<number>`count(*)::int`,
        latestAt: sql<Date | null>`max(${workspaceOperations.startedAt})`,
      })
      .from(workspaceOperations)
      .where(and(eq(workspaceOperations.companyId, run.companyId), eq(workspaceOperations.heartbeatRunId, run.id)));

    const [activityStats] = await db
      .select({
        count: sql<number>`count(*)::int`,
        latestAt: sql<Date | null>`max(${activityLog.createdAt})`,
      })
      .from(activityLog)
      .where(
        and(
          eq(activityLog.companyId, run.companyId),
          eq(activityLog.runId, run.id),
          notInArray(activityLog.action, LIVENESS_BOOKKEEPING_ACTIVITY_ACTIONS),
        ),
      );

    const [eventStats] = await db
      .select({
        count: sql<number>`count(*) filter (where ${heartbeatRunEvents.eventType} not in ('lifecycle', 'adapter.invoke', 'error'))::int`,
        latestAt: sql<Date | null>`max(${heartbeatRunEvents.createdAt}) filter (where ${heartbeatRunEvents.eventType} not in ('lifecycle', 'adapter.invoke', 'error'))`,
      })
      .from(heartbeatRunEvents)
      .where(and(eq(heartbeatRunEvents.companyId, run.companyId), eq(heartbeatRunEvents.runId, run.id)));

    return {
      runStatus: run.status,
      issue,
      resultJson: resultJson ?? run.resultJson ?? null,
      issueCommentBodies,
      continuationSummaryBody: continuationSummary?.body ?? null,
      stdoutExcerpt: run.stdoutExcerpt ?? null,
      stderrExcerpt: run.stderrExcerpt ?? null,
      error: run.error ?? null,
      errorCode: run.errorCode ?? null,
      continuationAttempt,
      evidence: {
        issueCommentsCreated: countValue(commentStats?.count),
        documentRevisionsCreated: countValue(documentStats?.count),
        planDocumentRevisionsCreated: countValue(documentStats?.planCount),
        workProductsCreated: countValue(workProductStats?.count),
        workspaceOperationsCreated: countValue(workspaceOperationStats?.count),
        activityEventsCreated: countValue(activityStats?.count),
        toolOrActionEventsCreated: countValue(eventStats?.count),
        latestEvidenceAt: latestDate(
          commentStats?.latestAt,
          documentStats?.latestAt,
          workProductStats?.latestAt,
          workspaceOperationStats?.latestAt,
          activityStats?.latestAt,
          eventStats?.latestAt,
        ),
      },
    };
  }

  async function classifyAndPersistRunLiveness(
    run: typeof heartbeatRuns.$inferSelect,
    resultJson?: Record<string, unknown> | null,
  ) {
    const classification = classifyRunLiveness(await buildRunLivenessInput(run, resultJson));
    return db
      .update(heartbeatRuns)
      .set({
        livenessState: classification.livenessState,
        livenessReason: classification.livenessReason,
        continuationAttempt: classification.continuationAttempt,
        lastUsefulActionAt: classification.lastUsefulActionAt,
        nextAction: classification.nextAction,
        updatedAt: new Date(),
      })
      .where(eq(heartbeatRuns.id, run.id))
      .returning()
      .then((rows) => rows[0] ?? null);
  }

  function externalLifecycleTerminalOutcome(
    jobStatus: AgentJobRunStatus | null,
    preserveRecordedOutcome = false,
  ) {
    if (!jobStatus) {
      if (preserveRecordedOutcome) {
        return {
          status: "succeeded" as const,
          wakeupStatus: "completed" as const,
          errorCode: null,
          error: null,
          recoveryReason: "job_missing_recorded_outcome_preserved",
          jobPhase: "missing",
          jobReason: null,
          jobMessage: null,
        };
      }
      return {
        status: "failed" as const,
        wakeupStatus: "failed" as const,
        errorCode: "job_missing",
        error: "External lifecycle Job is missing while heartbeat run is still running",
        recoveryReason: "job_missing",
        jobPhase: "missing",
        jobReason: null,
        jobMessage: null,
      };
    }

    if (jobStatus.phase === "succeeded") {
      return {
        status: "succeeded" as const,
        wakeupStatus: "completed" as const,
        errorCode: null,
        error: null,
        recoveryReason: "job_complete",
        jobPhase: "succeeded",
        jobReason: jobStatus.reason ?? null,
        jobMessage: jobStatus.message ?? null,
      };
    }

    if (jobStatus.phase === "failed") {
      const reason = readNonEmptyString(jobStatus.reason) ?? "job_failed";
      const message = readNonEmptyString(jobStatus.message);
      return {
        status: "failed" as const,
        wakeupStatus: "failed" as const,
        errorCode: "job_failed",
        error: message
          ? `External lifecycle Job failed: ${reason}: ${message}`
          : `External lifecycle Job failed: ${reason}`,
        recoveryReason: "job_failed",
        jobPhase: "failed",
        jobReason: reason,
        jobMessage: message,
      };
    }

    return null;
  }

  async function deleteExactExternalRuntimeJob(
    run: Pick<typeof heartbeatRuns.$inferSelect, "id" | "agentId">,
  ) {
    const reservation = await getActiveExternalRuntimeReservation(db, run.id);
    if (!reservation?.jobName || !reservation.jobUid) {
      logger.error(
        { runId: run.id, reservationId: reservation?.id ?? null },
        "refusing external-runtime Job deletion without persisted name and UID",
      );
      return "mismatch" as const;
    }
    return deleteAgentJobExact({
      runId: run.id,
      agentId: run.agentId,
      name: reservation.jobName,
      uid: reservation.jobUid,
    });
  }

  /**
   * Best-effort capture of the failed Job's pod-level terminal state.
   *
   * The Job `Failed` condition only ever says "backoff limit reached" — it names
   * no container and carries no exit code — so without this a recurrence leaves
   * no evidence once the pod is GC'd. Never throws and never blocks
   * finalization; a null result simply means the run record keeps the
   * Job-level fields it always had.
   */
  async function captureFailedJobContainerDiagnostics(
    run: Pick<typeof heartbeatRuns.$inferSelect, "id">,
    jobStatus: AgentJobRunStatus | null,
  ) {
    try {
      const jobName = readNonEmptyString(jobStatus?.name) ??
        readNonEmptyString((await getActiveExternalRuntimeReservation(db, run.id))?.jobName);
      if (!jobName) return null;
      return await captureAgentJobFailureDiagnostics(jobName);
    } catch (error) {
      logger.warn(
        { runId: run.id, error: error instanceof Error ? error.message : String(error) },
        "failed-Job container diagnostics capture failed; finalizing without them",
      );
      return null;
    }
  }

  async function finalizeExternalLifecycleTerminalRun(input: {
    run: typeof heartbeatRuns.$inferSelect;
    adapterType: string;
    adapterConfig: unknown;
    jobStatus: AgentJobRunStatus | null;
    now: Date;
    staleKill?: boolean;
  }) {
    let preserveRecordedOutcome = false;
    let prReviewIncompleteOverride: {
      errorCode: string;
      errorMessage: string;
    } | null = null;
    if (!input.staleKill && !input.jobStatus) {
      let reviewEvidence = evaluatePrReviewCompletionEvidence(
        parseObject(input.run.contextSnapshot),
        { resultJson: parseObject(input.run.resultJson) },
      );
      const claimedReview =
        reviewEvidence.status === "posted_review" || reviewEvidence.status === "already_reviewed";
      if (reviewEvidence.status === "missing" || claimedReview) {
        const verification = await verifyGithubReviewerEvidence(
          parseObject(input.run.contextSnapshot),
        );
        await appendRunEvent(input.run, await nextRunEventSeq(input.run.id), {
          eventType: "lifecycle",
          stream: "system",
          level: verification.status === "unavailable" ? "warn" : "info",
          message:
            verification.status === "found"
              ? `GitHub-verified ${verification.via} by the reviewer App during missing-Job recovery`
              : `GitHub reviewer-evidence check did not preserve missing-Job recovery: ${verification.status === "unavailable" ? verification.reason : "no_evidence_found"}`,
          payload: {
            repoFullName: verification.repoFullName,
            prNumber: verification.prNumber,
            headSha: verification.headSha,
            outcome: verification.status,
            ...(verification.status === "found" ? { via: verification.via } : {}),
            ...(verification.status === "unavailable" ? { reason: verification.reason } : {}),
          },
        });
        if (verification.status === "found") {
          reviewEvidence = { status: "posted_review" };
        } else if (verification.status === "unavailable") {
          reviewEvidence = unavailablePrReviewVerification(verification.reason);
        } else if (claimedReview) {
          reviewEvidence = {
            status: "missing",
            errorCode: "pr_review_output_missing",
            errorMessage:
              "PR reviewer run claimed a posted review, but GitHub has no exact-head review from a trusted reviewer identity",
          };
        }
      }
      prReviewIncompleteOverride =
        reviewEvidence.status === "missing" || reviewEvidence.status === "auth_expired"
          ? reviewEvidence
          : null;
      preserveRecordedOutcome = reviewEvidence.status === "posted_review" ||
        reviewEvidence.status === "already_reviewed" ||
        reviewEvidence.status === "archived_repo_skipped" ||
        reviewEvidence.status === "self_review_skipped";
    }
    const baseTerminalOutcome = input.staleKill
      ? {
          status: "failed" as const,
          wakeupStatus: "failed" as const,
          errorCode: "external_lifecycle_stale_killed",
          error:
            "External lifecycle Job force-terminated after prolonged silence (no useful action for >= EXTERNAL_LIFECYCLE_HARD_STALE_MS)",
          recoveryReason: "external_lifecycle_stale_killed",
          jobPhase: input.jobStatus?.phase ?? "active",
          jobReason: input.jobStatus?.reason ?? null,
          jobMessage: input.jobStatus?.message ?? null,
        }
      : externalLifecycleTerminalOutcome(input.jobStatus, preserveRecordedOutcome);
    const terminalOutcome =
      baseTerminalOutcome && prReviewIncompleteOverride && !input.staleKill
        ? {
            ...baseTerminalOutcome,
            errorCode: prReviewIncompleteOverride.errorCode,
            error: prReviewIncompleteOverride.errorMessage,
          }
        : baseTerminalOutcome;
    if (!terminalOutcome) return false;

    const adapterInvocationStarted = terminalOutcome.errorCode === "job_failed"
      ? await hasAdapterInvocationEvent(input.run.id)
      : null;

    // Read the pod's terminal container state while the pod still exists. This
    // is the only point in the lifecycle where it is still available.
    const containerDiagnostics = terminalOutcome.errorCode === "job_failed"
      ? await captureFailedJobContainerDiagnostics(input.run, input.jobStatus)
      : null;

    const resultJson = mergeRunStopMetadataForAgent(
      { adapterType: input.adapterType, adapterConfig: parseObject(input.adapterConfig) },
      terminalOutcome.status,
      {
        resultJson: {
          ...parseObject(input.run.resultJson),
          externalLifecycleRecovery: {
            reason: terminalOutcome.recoveryReason,
            jobPhase: terminalOutcome.jobPhase,
            jobReason: terminalOutcome.jobReason,
            jobMessage: terminalOutcome.jobMessage,
            ...(adapterInvocationStarted !== null ? { adapterInvocationStarted } : {}),
            ...(containerDiagnostics ? { containerDiagnostics } : {}),
          },
        },
        errorCode: terminalOutcome.errorCode,
        errorMessage: terminalOutcome.error,
      },
    );

    let finalizedRun: Awaited<ReturnType<typeof setRunStatus>>;
    let terminalJobQuiesced = input.jobStatus?.phase !== "active";
    if (input.staleKill) {
      // BLO-13176: claim the run terminally BEFORE the destructive Job delete.
      // The force-kill deleted the Job first and only then set status, so two
      // overlapping reaper passes (or the startup + periodic reapers racing)
      // could both select the still-`running` row and both force-kill it — the
      // `deletedJobs:0` thrash: repeated "force-killed live-but-silent" warns for
      // a runId whose Job was already deleted on the first pass. A compare-and-
      // swap on status=running means only one pass wins the transition; the
      // losers no-op. If the Job delete then fails, the run is already terminal
      // and cleanupTerminalExternalLifecycleJobs reaps its lingering Job next pass.
      const claim = await setRunStatusIfRunning(input.run.id, terminalOutcome.status, {
        error: terminalOutcome.error,
        errorCode: terminalOutcome.errorCode,
        finishedAt: input.now,
        resultJson,
      });
      if (!claim.updated) return false;
      finalizedRun = claim.run;
      // BLO-12996: the Job is still phase:active but the run has been silent
      // past EXTERNAL_LIFECYCLE_HARD_STALE_MS. Force-terminate the live Job so
      // the slot (and node CPU) is reclaimed and the dispatcher's
      // hasActiveJobForAgent gate stops blocking newly-queued high-priority work.
      try {
        const deleted = await deleteExactExternalRuntimeJob(input.run);
        terminalJobQuiesced = deleted === "deleted" || deleted === "missing";
        logger.warn(
          { runId: input.run.id, adapterType: input.adapterType, deletionResult: deleted },
          "reapOrphanedRuns: force-killed live-but-silent external-lifecycle Job (hard-stale)",
        );
      } catch (error) {
        logger.warn(
          {
            runId: input.run.id,
            adapterType: input.adapterType,
            error: error instanceof Error ? error.message : String(error),
          },
          "reapOrphanedRuns: failed to force-kill hard-stale external-lifecycle Job",
        );
      }
    } else {
      const claim = await setRunStatusIfRunning(input.run.id, terminalOutcome.status, {
        error: terminalOutcome.error,
        errorCode: terminalOutcome.errorCode,
        finishedAt: input.now,
        resultJson,
      });
      if (!claim.updated) return false;
      finalizedRun = claim.run;
    }
    await setWakeupStatus(input.run.wakeupRequestId, terminalOutcome.wakeupStatus, {
      finishedAt: input.now,
      error: terminalOutcome.error,
    });

    if (!finalizedRun) finalizedRun = await getRun(input.run.id);
    if (!finalizedRun) return true;

    finalizedRun = await classifyAndPersistRunLiveness(finalizedRun, resultJson) ?? finalizedRun;

    // BLO-10448: job_missing (and any other automatically-retryable terminal
    // errorCode) is stamped here, in the vanished-Job reconciler — NOT on the
    // adapter -> liveness path that consults shouldScheduleAutomaticRunRetry at
    // the end of evaluateRunLiveness. Without consulting it here too, a pr_review
    // run whose external-lifecycle Job vanished before completion was finalized
    // terminal with no retry, silently dropping the review (observed on the Ally
    // reviewer path). Mirror the liveness retry decision so the bounded re-queue
    // fires for these reconciler-finalized failures as well. Non-pr / non-retryable
    // codes return false from the predicate and stay terminal (BLO-7913 leak guard).
    const finalizationAgent = await getAgent(finalizedRun.agentId);
    if (
      terminalOutcome.status === "failed" &&
      shouldScheduleAutomaticRunRetry(finalizedRun) &&
      finalizationAgent
    ) {
      await scheduleBoundedRetryForRun(
        finalizedRun,
        finalizationAgent,
        resolveAutomaticRunRetryOpts(finalizedRun),
      );
      finalizedRun = (await getRun(finalizedRun.id)) ?? finalizedRun;
    }

    await releaseEnvironmentLeasesForRun({
      runId: finalizedRun.id,
      companyId: finalizedRun.companyId,
      agentId: finalizedRun.agentId,
      status: finalizedRun.status,
      failureReason: finalizedRun.error ?? undefined,
    });
    if (terminalJobQuiesced) {
      await releaseExternalRuntimeReservation(db, {
        runId: finalizedRun.id,
        reason: terminalOutcome.errorCode ?? terminalOutcome.status,
      });
    }
    // BLO-19085: pass the reason we already computed. Omitting it latched the
    // agent into `error` with `errorReason: null` while the very same
    // `terminalOutcome` (e.g. "External lifecycle Job is missing while heartbeat
    // run is still running" / job_missing) sat on the run record one frame away.
    await finalizeAgentStatus(input.run.agentId, terminalOutcome.status, terminalOutcome.error, {
      errorCode: terminalOutcome.errorCode,
      runId: input.run.id,
    });
    const promotedRunDispatched = await releaseIssueExecutionAndPromote(finalizedRun);
    await handleRunLivenessContinuation(finalizedRun);
    if (finalizationAgent) {
      await handleSuccessfulRunHandoff(finalizedRun, finalizationAgent);
    }
    await appendRunEvent(finalizedRun, await nextRunEventSeq(finalizedRun.id), {
      eventType: "lifecycle",
      stream: "system",
      level: terminalOutcome.status === "succeeded" ? "info" : "error",
      message: terminalOutcome.error ?? "External lifecycle Job completed",
      payload: {
        externalLifecycleRecovery: true,
        jobPhase: terminalOutcome.jobPhase,
        jobReason: terminalOutcome.jobReason,
        jobMessage: terminalOutcome.jobMessage,
      },
    });
    if (!promotedRunDispatched) {
      await startNextQueuedRunForAgent(input.run.agentId);
    }
    runningProcesses.delete(input.run.id);
    activeRunExecutions.delete(input.run.id);
    externalRunReattachedAt.delete(input.run.id);
    await environmentsSvc.releaseLeasesForRun(
      input.run.id,
      terminalOutcome.status === "succeeded" ? "released" : "failed",
    );

    return true;
  }

  function runTimestampMs(value: Date | string | null | undefined): number {
    if (!value) return 0;
    const timestamp = new Date(value).getTime();
    return Number.isFinite(timestamp) ? timestamp : 0;
  }

  // Deliberately EXCLUDES updatedAt. updatedAt is a generic "row was touched"
  // timestamp that unrelated subsystems (silent-active-run review, board
  // recovery, liveness backfill) bump every ~minute on a run under review.
  // Including it let a dead pre-adapter orphan masquerade as "recently active"
  // and evade the reaper indefinitely (BLO-8827 — a 4h+ stuck opencode_k8s run
  // observed 2026-06-03, kept alive by the very review meant to recover it).
  // Genuine run activity = streamed output + lifecycle timestamps only.
  function externalLifecycleRecentRefTime(
    run: Pick<
      typeof heartbeatRuns.$inferSelect,
      "id" | "lastOutputAt" | "startedAt" | "createdAt" | "finishedAt"
    >,
  ): number {
    return Math.max(
      runTimestampMs(run.lastOutputAt),
      runTimestampMs(run.finishedAt),
      runTimestampMs(run.startedAt),
      runTimestampMs(run.createdAt),
      externalRunReattachedAt.get(run.id) ?? 0,
    );
  }

  function isExternalLifecycleRunInRecentGrace(
    run: Pick<
      typeof heartbeatRuns.$inferSelect,
      "id" | "lastOutputAt" | "updatedAt" | "startedAt" | "createdAt" | "finishedAt"
    >,
    now: Date,
    graceMs = EXTERNAL_LIFECYCLE_RECENT_RUN_GRACE_MS,
  ): boolean {
    const refTime = externalLifecycleRecentRefTime(run);
    return refTime > 0 && now.getTime() - refTime < graceMs;
  }

  // BLO-13176: classify whether an external-lifecycle run's backing k8s Job is
  // still alive, using the kube signal the reaper already gathered this pass.
  // Returns "alive" only on positive evidence of an active Job, "dead" only on
  // positive evidence the Job is gone/terminal, and "unknown" when the signal is
  // missing or a snapshot miss can't be disambiguated. Callers must treat
  // "unknown" conservatively (apply a silence floor) rather than kill a
  // possibly-live pod — the whole point of the ticket is that a slow-provisioning
  // pre-adapter run looks silent but is not orphaned.
  async function resolveExternalLifecycleJobLiveness(
    run: Pick<typeof heartbeatRuns.$inferSelect, "id" | "externalRunId">,
    jobRunStatuses: Map<string, AgentJobRunStatus> | null,
    liveJobRunIds: Set<string> | null,
  ): Promise<"alive" | "dead" | "unknown"> {
    const persistedJobName = run.externalRunId?.trim() || null;
    if (jobRunStatuses !== null) {
      const snap = jobRunStatuses.get(run.id) ?? null;
      if (snap) return snap.phase === "active" ? "alive" : "dead";
      // Absent from the rich snapshot: could be a false negative (kube list
      // timeout / eventual consistency / Job not yet visible). Confirm via the
      // exact persisted Job name before concluding anything.
      if (persistedJobName) {
        const exact = await readAgentJobRunStatusByName(persistedJobName);
        if (exact) return exact.phase === "active" ? "alive" : "dead";
      }
      return "unknown";
    }
    if (liveJobRunIds !== null) {
      if (liveJobRunIds.has(run.id)) return "alive";
      // Absent from the list snapshot is NOT proof of death (2026-05-23 RCA:
      // partial snapshots produced ~6.5/hr false process_lost). Confirm by name.
      if (persistedJobName) {
        const exact = await readAgentJobRunStatusByName(persistedJobName);
        if (exact) return exact.phase === "active" ? "alive" : "dead";
      }
      return "unknown";
    }
    return "unknown";
  }

  async function cleanupTerminalExternalLifecycleJobs(
    jobRunStatuses: Map<string, AgentJobRunStatus> | null,
    now = new Date(),
  ): Promise<string[]> {
    if (!jobRunStatuses) return [];
    const activeJobRunIds = [...jobRunStatuses.entries()]
      .filter(([, status]) => status.phase === "active")
      .map(([runId]) => runId)
      .filter(Boolean);
    if (activeJobRunIds.length === 0) return [];

    const terminalRuns = await db
      .select({
        run: heartbeatRuns,
        adapterType: agents.adapterType,
      })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(
        and(
          inArray(heartbeatRuns.id, activeJobRunIds),
          inArray(heartbeatRuns.status, [...HEARTBEAT_RUN_TERMINAL_STATUSES]),
        ),
      );

    const cleanedRunIds: string[] = [];
    for (const { run, adapterType } of terminalRuns) {
      if (!hasExternalLifecycle(adapterType)) continue;
      if (isExternalLifecycleRunInRecentGrace(run, now)) {
        logger.debug(
          { runId: run.id, status: run.status, adapterType },
          "reapOrphanedRuns: preserving recent terminal external-lifecycle Job",
        );
        continue;
      }
      const reservation = await getActiveExternalRuntimeReservation(db, run.id);
      const observed = jobRunStatuses.get(run.id);
      const reservationReconciles =
        Boolean(reservation?.jobName)
        && Boolean(reservation?.jobUid)
        && observed?.name === reservation?.jobName
        && observed?.uid === reservation?.jobUid;

      if (reservationReconciles) {
        try {
          const deleted = await deleteExactExternalRuntimeJob(run);
          if (deleted !== "deleted" && deleted !== "missing") continue;
          cleanedRunIds.push(run.id);
          logger.warn(
            { runId: run.id, status: run.status, adapterType, deletionResult: deleted },
            "reapOrphanedRuns: deleted live external-lifecycle Job for terminal heartbeat run",
          );
          await appendRunEvent(run, await nextRunEventSeq(run.id), {
            eventType: "lifecycle",
            stream: "system",
            level: "warn",
            message: "Deleted live external-lifecycle Job because heartbeat run is already terminal",
            payload: {
              status: run.status,
              adapterType,
            },
          });
        } catch (error) {
          logger.warn(
            {
              runId: run.id,
              status: run.status,
              adapterType,
              error: error instanceof Error ? error.message : String(error),
            },
            "reapOrphanedRuns: failed to delete live external-lifecycle Job for terminal heartbeat run",
          );
        }
        continue;
      }

      // BLO-16473: the exact reservation identity is gone or stale (e.g. an
      // earlier finalize-time delete threw, or the reservation was already
      // released without the Job actually being torn down) — the loop above
      // used to just log an error and give up forever here, leaking the Job
      // (and its Pod) indefinitely. That live-but-terminal Job then permanently
      // holds `hasActiveJobForAgent` true, so the agent's dispatcher wedges:
      // `startNextQueuedRunForAgent` sees runningCount === 0 but an active Job
      // and refuses to claim any new queued run, forever. Fall back to
      // deleting by the Job's `paperclip.io/run-id` label, which is stamped at
      // creation and immutable — as safe an identity check as the reservation
      // row, but independent of that row still existing.
      logger.warn(
        { runId: run.id, reservationId: reservation?.id ?? null, observed },
        "terminal Job cleanup: reservation identity did not reconcile; falling back to run-id label match",
      );
      try {
        const deletedCount = await deleteAgentJobsForRun(run.id);
        if (deletedCount === null) continue;
        cleanedRunIds.push(run.id);
        logger.warn(
          { runId: run.id, status: run.status, adapterType, deletedCount },
          "reapOrphanedRuns: deleted live external-lifecycle Job for terminal heartbeat run (run-id fallback)",
        );
        await appendRunEvent(run, await nextRunEventSeq(run.id), {
          eventType: "lifecycle",
          stream: "system",
          level: "warn",
          message:
            "Deleted live external-lifecycle Job via run-id fallback because heartbeat run is already terminal and no reservation identity reconciled",
          payload: {
            status: run.status,
            adapterType,
          },
        });
      } catch (error) {
        logger.warn(
          {
            runId: run.id,
            status: run.status,
            adapterType,
            error: error instanceof Error ? error.message : String(error),
          },
          "reapOrphanedRuns: failed to delete live external-lifecycle Job via run-id fallback for terminal heartbeat run",
        );
      }
    }
    return cleanedRunIds;
  }

  async function reconcileReleasePendingExternalRuntimeReservations(
    jobRunStatuses: Map<string, AgentJobRunStatus> | null,
    ambiguousRunIds: ReadonlySet<string> = new Set(),
  ) {
    const pending = await db
      .select({
        reservation: externalRuntimeReservations,
        runStatus: heartbeatRuns.status,
      })
      .from(externalRuntimeReservations)
      .innerJoin(heartbeatRuns, eq(heartbeatRuns.id, externalRuntimeReservations.runId))
      .where(
        and(
          isNull(externalRuntimeReservations.releasedAt),
          or(
            eq(externalRuntimeReservations.state, "release_pending"),
            and(
              inArray(externalRuntimeReservations.state, ["reserved", "launching"]),
              isNull(externalRuntimeReservations.expectedJobName),
              isNull(externalRuntimeReservations.jobName),
              isNull(externalRuntimeReservations.jobUid),
              inArray(heartbeatRuns.status, [...HEARTBEAT_RUN_TERMINAL_STATUSES]),
            ),
            // BLO-18995: an *identified* reservation (a Job name was recorded)
            // whose run reached a terminal status without the normal
            // finalize-time release running — the canonical case is
            // `drainRunningRunsForShutdown` marking a running run
            // `interrupted` on SIGTERM, which never releases the reservation.
            // The two branches above cannot see it: it is not
            // `release_pending`, and it is `launched` with a non-null
            // `jobName`. The row then keeps `released_at IS NULL` forever and
            // the partial unique index
            // `external_runtime_reservations_active_slot_idx (agent_id,
            // slot_id) WHERE released_at IS NULL` blocks that slot
            // permanently, so every worker restart with a run in flight
            // ratchets the agent's effective concurrency down by one. Observed
            // in production: four agents each stuck a slot for 1-5 days (Ally
            // 4/5 slots, Release Engineer 1/2).
            //
            // Selecting the row here is safe because it does not release it:
            // the loop below still verifies the recorded Job is genuinely gone
            // or finished (exact `readAgentJobRunStatusByName` lookup plus
            // jobUid identity match) and skips any reservation whose Job is
            // still `active`. A Job that outlives the worker therefore keeps
            // its slot until it actually terminates.
            and(
              inArray(externalRuntimeReservations.state, ["reserved", "launching", "launched"]),
              or(
                isNotNull(externalRuntimeReservations.jobName),
                isNotNull(externalRuntimeReservations.jobUid),
              ),
              inArray(heartbeatRuns.status, [...HEARTBEAT_RUN_TERMINAL_STATUSES]),
            ),
          ),
        ),
      );
    for (const { reservation, runStatus } of pending) {
      if (activeRunExecutions.has(reservation.runId)) continue;
      if (ambiguousRunIds.has(reservation.runId)) continue;
      const observed = jobRunStatuses?.get(reservation.runId) ?? null;
      const launchedIdentityMatches = Boolean(
        reservation.jobName
        && reservation.jobUid
        && observed?.name === reservation.jobName
        && observed.uid === reservation.jobUid,
      );
      if (observed && reservation.jobName && !launchedIdentityMatches) {
        logger.error(
          { reservationId: reservation.id, runId: reservation.runId, observed },
          "refusing reservation release because observed Job identity does not match",
        );
        continue;
      }
      if (observed?.phase === "active") continue;

      let terminalOrMissing = launchedIdentityMatches;
      const jobName = reservation.jobName ?? reservation.expectedJobName;
      const isolationSetupGraceActive =
        !jobName &&
        (reservation.isolationMode === "shared" || reservation.isolationMode === "workspace") &&
        Date.now() - new Date(reservation.updatedAt).getTime() < EXTERNAL_LIFECYCLE_RECENT_RUN_GRACE_MS;
      if (isolationSetupGraceActive) continue;
      // Both bundled external adapters await onMeta before createNamespacedJob.
      // onMeta persists expectedJobName, so no name is durable proof that Job
      // creation was never crossed, even if the dispatcher crashed afterward.
      if (!jobName && externalRuntimeReservationCanRelease(reservation, null, true)) {
        terminalOrMissing = true;
      }
      if (!terminalOrMissing && jobName) {
        const exact = await readAgentJobRunStatusByName(jobName);
        terminalOrMissing = Boolean(
          exact
          && exact.phase !== "active"
          && (
            !reservation.jobUid
            || exact.phase === "missing"
            || exact.uid === reservation.jobUid
          ),
        );
      }
      if (!terminalOrMissing) continue;

      const terminalPrelaunchOrphan =
        reservation.state === "reserved" || reservation.state === "launching";
      const released = await releaseExternalRuntimeReservation(db, {
        runId: reservation.runId,
        reason:
          reservation.releaseReason ??
          (terminalPrelaunchOrphan ? "terminal_prelaunch_orphan" : "job_terminal_or_missing"),
      });
      if (released && terminalPrelaunchOrphan) {
        logger.warn(
          {
            reservationId: reservation.id,
            runId: reservation.runId,
            runStatus,
            reservationState: reservation.state,
          },
          "released prelaunch external-runtime reservation left behind by terminal run",
        );
      }
    }
  }

  async function cleanupManagedJobsWithoutRun(now: Date, inventory?: Awaited<ReturnType<typeof listManagedAgentJobs>>) {
    const jobs = inventory === undefined ? await listManagedAgentJobs() : inventory;
    if (!jobs) return [];
    const graceMs = 5 * 60 * 1000;
    const oldJobs = jobs
      .filter((job) =>
        job.runId
        && job.agentId
        && job.createdAt
        && now.getTime() - job.createdAt.getTime() >= graceMs
      )
      .sort((a, b) => a.createdAt!.getTime() - b.createdAt!.getTime());
    const runIds = [...new Set(oldJobs.map((job) => job.runId).filter((runId): runId is string => Boolean(runId)))];
    if (runIds.length === 0) return [];
    const existingRunIds = new Set(
      await db
        .select({ id: heartbeatRuns.id })
        .from(heartbeatRuns)
        .where(inArray(heartbeatRuns.id, runIds))
        .then((rows) => rows.map((row) => row.id)),
    );
    const candidates = oldJobs
      .filter((job) => job.runId && !existingRunIds.has(job.runId))
      .slice(0, 25);
    const deleted: string[] = [];
    for (const job of candidates) {
      const result = await deleteAgentJobExact({
        runId: job.runId!,
        agentId: job.agentId!,
        name: job.name,
        uid: job.uid,
      });
      if (result === "deleted" || result === "missing") deleted.push(job.name);
    }
    return deleted;
  }

  async function cleanupOrphanedManagedPods(
    now: Date,
    liveJobRunIds: Set<string> | null,
    inventory?: ManagedAgentPod[] | null,
  ): Promise<string[]> {
    // Cold-boot / kube-blind guard (BLO-12564): never reap while the kube view
    // may be incomplete right after worker boot.
    if (
      coldBootReattachGraceMs > 0
      && now.getTime() - workerBootAt.getTime() < coldBootReattachGraceMs
    ) {
      return [];
    }
    const pods = inventory === undefined ? await listManagedAgentPods() : inventory;
    if (!pods) return []; // kube-blind → no-op (BLO-12564)

    const candidates = pods.filter(
      (pod) =>
        hasExternalLifecycle(pod.adapterType ?? "")
        && pod.runId
        && pod.agentId
        && pod.uid
        && pod.name
        && pod.createdAt
        && now.getTime() - pod.createdAt.getTime() >= ORPHANED_MANAGED_POD_REAP_GRACE_MS
        && !pod.deletionTimestamp
        && pod.isActiveOrTerminating,
    );
    if (candidates.length === 0) return [];

    const runIds = [...new Set(candidates.map((p) => p.runId).filter((id): id is string => Boolean(id)))];
    // Which of these runs are still LIVE (non-terminal) in the DB? Those pods are
    // protected — the per-run reap loop / dispatcher owns them.
    const liveRunIds = new Set(
      (
        await db
          .select({ id: heartbeatRuns.id, status: heartbeatRuns.status })
          .from(heartbeatRuns)
          .where(inArray(heartbeatRuns.id, runIds))
      )
        .filter((row) => !TERMINAL_RUN_STATUSES.has(row.status))
        .map((row) => row.id),
    );

    const toReap = candidates
      .filter((pod) => {
        if (liveRunIds.has(pod.runId!)) return false; // run still active in DB
        if (liveJobRunIds && liveJobRunIds.has(pod.runId!)) return false; // live Job (positive-liveness, BLO-13176)
        return true;
      })
      .sort((a, b) => (a.createdAt!.getTime()) - (b.createdAt!.getTime()))
      .slice(0, 25);

    const reaped: string[] = [];
    for (const pod of toReap) {
      const result = await deleteAgentPodExact({
        name: pod.name,
        uid: pod.uid,
        runId: pod.runId!,
        agentId: pod.agentId!,
      });
      if (result === "deleted" || result === "missing") {
        reaped.push(pod.name);
        logger.warn(
          {
            agentId: pod.agentId,
            podName: pod.name,
            runId: pod.runId,
            adapterType: pod.adapterType,
            phase: pod.phase,
            ageMs: now.getTime() - pod.createdAt!.getTime(),
          },
          "reaped orphaned managed agent pod: run terminal/absent + no live Job, pod still Running (BLO-16850)",
        );
        recordOrphanedManagedPodReaped({ adapterType: pod.adapterType ?? undefined });
      }
    }
    return reaped;
  }

  async function releaseExternalRuntimeReservationIfQuiesced(runId: string, reason: string) {
    const reservation = await getActiveExternalRuntimeReservation(db, runId);
    if (!reservation) return null;

    const jobName = reservation.jobName ?? reservation.expectedJobName;
    const status = jobName ? await readAgentJobRunStatusByName(jobName) : null;
    if (
      reservation.jobUid
      && status
      && status.phase !== "missing"
      && status.uid !== reservation.jobUid
    ) return null;
    if (!externalRuntimeReservationCanRelease(reservation, status?.phase ?? null, true)) return null;

    return releaseExternalRuntimeReservation(db, { runId, reason });
  }

  async function resumeRunningExternalRuntimeRuns() {
    const jobs = await listManagedAgentJobs();
    const rows = await db
      .select({ run: heartbeatRuns, adapterType: agents.adapterType })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(eq(heartbeatRuns.status, "running"));
    let resumed = 0;
    for (const { run, adapterType } of rows) {
      if (
        !hasExternalLifecycle(adapterType)
        || activeRunExecutions.has(run.id)
        || reattachingExternalRuns.has(run.id)
      ) continue;
      const reservation = await getActiveExternalRuntimeReservation(db, run.id);
      if (reservation?.state !== "launched" || !reservation.jobName || !reservation.jobUid) continue;
      const reconciled = jobs === null
        ? null
        : matchExactAgentJob(jobs, {
            runId: run.id,
            agentId: run.agentId,
            name: reservation.jobName,
            uid: reservation.jobUid,
          });
      if (reconciled && reconciled.kind !== "exact") continue;
      const observed = reconciled?.kind === "exact"
        ? reconciled.job
        : await readAgentJobRunStatusByName(reservation.jobName);
      if (observed?.phase !== "active" || observed.uid !== reservation.jobUid) continue;
      resumed += 1;
      reattachingExternalRuns.add(run.id);
      externalRunReattachedAt.set(run.id, Date.now());
      void executeRun(run.id)
        .catch((error) => {
          logger.error({ error, runId: run.id }, "failed to reattach external-runtime execution");
        })
        .finally(() => reattachingExternalRuns.delete(run.id));
    }
    return resumed;
  }

  async function reapOrphanedRuns(opts?: { staleThresholdMs?: number; suppressDispatchAfterReap?: boolean }) {
    const staleThresholdMs = opts?.staleThresholdMs ?? 0;
    const now = new Date();

    // Find all runs stuck in "running" state (queued runs are legitimately waiting; resumeQueuedRuns handles them)
    const activeRuns = await db
      .select({
        run: heartbeatRuns,
        adapterType: agents.adapterType,
        adapterConfig: agents.adapterConfig,
      })
      .from(heartbeatRuns)
      .innerJoin(agents, eq(heartbeatRuns.agentId, agents.id))
      .where(eq(heartbeatRuns.status, "running"));

    const monitorIssueIds = [...new Set(activeRuns.flatMap(({ run }) => {
      const runContext = parseObject(run.contextSnapshot);
      if (readNonEmptyString(runContext.wakeReason) !== "issue_monitor_due") return [];
      const issueId = readNonEmptyString(runContext.issueId);
      return issueId ? [issueId] : [];
    }))];
    const monitorIssues = monitorIssueIds.length > 0
      ? await db
        .select({
          id: issues.id,
          companyId: issues.companyId,
          monitorNextCheckAt: issues.monitorNextCheckAt,
        })
        .from(issues)
        .where(inArray(issues.id, monitorIssueIds))
      : [];
    const monitorNextCheckAtByIssue = new Map(
      monitorIssues.map((issue) => [
        `${issue.companyId}:${issue.id}`,
        issue.monitorNextCheckAt,
      ]),
    );

    const reaped: string[] = [];

    // Query the kube API once for namespace-wide agent Job state. Active runs
    // use it for liveness; terminal runs use it to clean up live historical
    // Jobs that would otherwise keep blocking future dispatches. Returns null
    // when the API is unavailable (local dev, RBAC missing, transient failure).
    const hasExternalCandidates = activeRuns.some((row) => hasExternalLifecycle(row.adapterType));
    let managedJobs = await listManagedAgentJobs();
    await cleanupManagedJobsWithoutRun(now, managedJobs);
    const activeReservations = activeRuns.length > 0
      ? await db
        .select()
        .from(externalRuntimeReservations)
        .where(and(
          inArray(externalRuntimeReservations.runId, activeRuns.map(({ run }) => run.id)),
          isNull(externalRuntimeReservations.releasedAt),
        ))
      : [];
    const reservationsByRunId = new Map(activeReservations.map((reservation) => [reservation.runId, reservation]));
    const duplicateJobsCleanedRunIds = new Set<string>();

    // A persisted launched reservation is the sole authority for which Job may
    // drive a run. Delete duplicate non-owners one at a time with their observed
    // UID, then rebuild the inventory view without Jobs confirmed gone.
    if (managedJobs) {
      const jobsByRun = new Map<string, typeof managedJobs>();
      for (const job of managedJobs) {
        if (!job.runId) continue;
        jobsByRun.set(job.runId, [...(jobsByRun.get(job.runId) ?? []), job]);
      }
      const removedJobUids = new Set<string>();
      for (const [runId, candidates] of jobsByRun) {
        if (candidates.length <= 1) continue;
        const reservation = reservationsByRunId.get(runId);
        if (
          reservation?.state !== "launched"
          || !reservation.jobName
          || !reservation.jobUid
        ) continue;
        const owner = candidates.find((job) =>
          job.agentId === reservation.agentId
          && job.name === reservation.jobName
          && job.uid === reservation.jobUid
        );
        for (const candidate of candidates) {
          if (candidate === owner || !candidate.agentId) continue;
          const deleted = await deleteAgentJobExact({
            runId,
            agentId: candidate.agentId,
            name: candidate.name,
            uid: candidate.uid,
          });
          if (deleted === "deleted" || deleted === "missing") {
            removedJobUids.add(candidate.uid);
            duplicateJobsCleanedRunIds.add(runId);
          }
        }
      }
      if (removedJobUids.size > 0) {
        managedJobs = managedJobs.filter((job) => !removedJobUids.has(job.uid));
      }
    }

    const jobRunStatuses = managedJobs !== null
      ? indexUniqueAgentJobRunStatuses(managedJobs)
      : await listAgentJobRunStatuses();
    const ambiguousExternalRunIds = new Set<string>();
    if (managedJobs) {
      const jobsByRun = new Map<string, typeof managedJobs>();
      for (const job of managedJobs) {
        if (!job.runId) continue;
        const candidates = jobsByRun.get(job.runId) ?? [];
        candidates.push(job);
        jobsByRun.set(job.runId, candidates);
      }
      for (const [runId, candidates] of jobsByRun) {
        if (candidates.length !== 1) ambiguousExternalRunIds.add(runId);
      }
    }
    const replacementPendingRunIds = new Set(
      activeReservations
        .filter((reservation) => {
          const updatedAt = new Date(reservation.updatedAt).getTime();
          return (
            reservation.state === "launching" &&
            reservation.jobName === null &&
            reservation.jobUid === null &&
            reservation.launchedAt === null &&
            Number.isFinite(updatedAt) &&
            now.getTime() - updatedAt < EXTERNAL_LIFECYCLE_STALE_MS
          );
        })
        .map((reservation) => reservation.runId),
    );

    // BLO-16184: emit the process_lost run-volume DENOMINATOR every reap cycle so
    // a "0 process_lost" reading can never be silently trusted at low run volume.
    // Set reset-then-set so a genuine drop to 0 is written explicitly, not stale.
    // (The kube-null-blindness denominator is emitted below once liveJobRunIds is
    // resolved, so it reflects true blindness rather than a recovered primary miss.)
    const externalRunningByAdapter: Record<string, number> = {};
    for (const { adapterType } of activeRuns) {
      if (hasExternalLifecycle(adapterType)) {
        externalRunningByAdapter[adapterType] = (externalRunningByAdapter[adapterType] ?? 0) + 1;
      }
    }
    setExternalLifecycleRunningRuns(externalRunningByAdapter);

    // BLO-8746/BLO-8827 Phase A: stamp the backing k8s Job name onto each
    // running external-lifecycle run's external_run_id so the run row is
    // self-describing — run→Job is navigable without a live kube query, and
    // process_pid (always NULL for these runs) stops being mistaken for a
    // liveness signal. Best-effort: only when the Job is known and the value
    // actually changed, so this adds no write churn on a steady fleet.
    if (jobRunStatuses) {
      for (const { run } of activeRuns) {
        if (ambiguousExternalRunIds.has(run.id)) continue;
        const jobStatus = jobRunStatuses.get(run.id);
        const jobName = jobStatus?.name ?? null;
        const jobUid = jobStatus?.uid ?? null;
        if (jobStatus && (!jobName || !jobUid)) {
          logger.error(
            { runId: run.id, jobName, jobUid },
            "refusing unidentifiable external-runtime Job status",
          );
          ambiguousExternalRunIds.add(run.id);
          jobRunStatuses.delete(run.id);
        } else if (jobName && jobUid) {
          try {
            // Read at the stamp decision point rather than trusting the earlier
            // reservation inventory. An in-process retry can re-arm ownership
            // after that snapshot; a terminal Job from the consumed attempt must
            // never be rebound onto its replacement reservation.
            const reservation = await getActiveExternalRuntimeReservation(db, run.id);
            const reservationUpdatedAt = reservation
              ? new Date(reservation.updatedAt).getTime()
              : Number.NaN;
            const terminalAttemptStillOwned = Boolean(
              jobStatus?.phase !== "active" &&
              reservation?.state === "launching" &&
              reservation.jobName === null &&
              reservation.jobUid === null &&
              reservation.launchedAt === null &&
              Number.isFinite(reservationUpdatedAt) &&
              now.getTime() - reservationUpdatedAt < EXTERNAL_LIFECYCLE_STALE_MS
            );
            if (terminalAttemptStillOwned) continue;
            if (managedJobs) {
              const exact = matchExactAgentJob(managedJobs, {
                runId: run.id,
                agentId: run.agentId,
                name: jobName,
                uid: jobUid,
              });
              if (exact.kind !== "exact") throw new Error(`Managed Job identity is ${exact.kind}`);
            }
            if (!reservation) throw new Error(`No active external-runtime reservation for run ${run.id}`);
            const stamped = await recordExternalRuntimeJobIdentity(db, {
              runId: run.id,
              reservationId: reservation.id,
              slotId: reservation.slotId,
              jobName,
              jobUid,
              now,
            });
            if (!stamped) {
              // Lost the create/stamp race between the read above and the
              // stamp: the reservation was released out from under this exact
              // observed Job. Compensate immediately rather than letting the
              // Job leak until a later terminal-cleanup pass, which can only
              // reconcile through a reservation that no longer exists.
              const compensated = await deleteAgentJobExact({
                runId: run.id,
                agentId: run.agentId,
                name: jobName,
                uid: jobUid,
              });
              logger.error(
                { runId: run.id, agentId: run.agentId, jobName, jobUid, compensated },
                "external-runtime reservation was gone when reconciling an observed launched Job; deleted the exact Job to prevent a post-terminal orphan",
              );
              ambiguousExternalRunIds.add(run.id);
              jobRunStatuses.delete(run.id);
            }
          } catch (error) {
            logger.error(
              { runId: run.id, jobName, jobUid: jobStatus?.uid ?? null, error },
              "external-runtime reservation Job identity mismatch",
            );
            ambiguousExternalRunIds.add(run.id);
            jobRunStatuses.delete(run.id);
          }
        }
      }
    }

    const cleanedTerminalJobRunIds = await cleanupTerminalExternalLifecycleJobs(jobRunStatuses, now);
    reaped.push(...cleanedTerminalJobRunIds);
    await reconcileReleasePendingExternalRuntimeReservations(jobRunStatuses, ambiguousExternalRunIds);
    const liveJobRunIds =
      jobRunStatuses !== null
        ? new Set(
            [...jobRunStatuses.entries()]
              .filter(([, status]) => status.phase === "active")
              .map(([runId]) => runId),
          )
        : hasExternalCandidates
          ? await listLiveAgentJobRunIds()
          : null;

    // BLO-16184 DENOMINATOR #2: the reaper is truly blind only when it has no
    // live-Job data at all for this cycle -- the primary status list AND the
    // fallback live-id list both returned null (kube API unavailable). Keying on
    // liveJobRunIds (not jobRunStatuses) avoids a false SignalBlind when the
    // primary miss is recovered by the fallback call. While blind the reaper
    // falls back to the staleness heuristic, so any concurrent low process_lost
    // count is unreliable.
    if (hasExternalCandidates && liveJobRunIds === null) {
      recordProcessLostLivenessNull();
    }

    // BLO-16850: sweep still-Running external-lifecycle pods whose run has
    // finalized (terminal/absent) with no live Job. Non-fatal — a sweep failure
    // must never abort the per-run reap below.
    try {
      await cleanupOrphanedManagedPods(now, liveJobRunIds);
    } catch (error) {
      logger.warn(
        { error: error instanceof Error ? error.message : String(error) },
        "orphaned managed-pod sweep failed (non-fatal)",
      );
    }

    for (const { run, adapterType, adapterConfig } of activeRuns) {
      if (runningProcesses.has(run.id)) continue;
      if (ambiguousExternalRunIds.has(run.id)) continue;
      if (duplicateJobsCleanedRunIds.has(run.id)) continue;

      // External-lifecycle adapters (k8s Jobs etc.) manage their own run
      // completion once adapter invocation has actually started. A claimed
      // run with no adapter.invoke event has no known external Job yet, so it
      // must stay eligible for startup/periodic recovery.
      const externalLifecycleRun = hasExternalLifecycle(adapterType);

      // For non-external adapters, the in-process await is authoritative --
      // the run is being driven by `executeRun` in this very pod, and the
      // reaper must not race it. For external-lifecycle adapters the kube
      // Job is the source of truth: the in-process await can be hung on a
      // preRun hook timeout that left grandchildren holding pipes, on an MCP
      // RPC that never timed out, or on a Job that vanished without
      // notifying the awaiting code. In those cases the run sits in the
      // `activeRunExecutions` Set forever, quarantined from the reaper. Let
      // the silence/Job-liveness check below decide for external lifecycle.
      if (activeRunExecutions.has(run.id) && !externalLifecycleRun) continue;
      const externalLifecycleStarted = externalLifecycleRun
        ? await hasAdapterInvocationEvent(run.id)
        : false;
      const externalLifecyclePreAdapter = externalLifecycleRun && !externalLifecycleStarted;
      // BLO-16181: retain the pre-adapter Job liveness the loop resolves below so
      // the process_lost mint can persist whether the Job was confirmed dead vs
      // merely unconfirmable (kube unavailable). Stays null for started runs.
      let preAdapterJobLiveness: ProcessLossJobLiveness = null;
      if (externalLifecyclePreAdapter) {
        // Within the short pre-adapter grace, always skip: the run just created
        // its DB row + k8s Job and has not had time to reach adapter.invoke.
        if (isExternalLifecycleRunInRecentGrace(run, now, EXTERNAL_LIFECYCLE_PRE_ADAPTER_STALE_MS)) {
          continue;
        }
        // A claimed external-runtime run can legitimately spend longer than the
        // five-minute run-row grace in workspace/preRun preparation before it
        // reaches markExternalRuntimeReservationLaunching(). While its active
        // reservation is still reserved/launching and no launched Job identity
        // exists, that reservation is durable proof that the in-flight executor
        // still owns the launch. Give that owner the normal external-lifecycle
        // stale window before treating the run as orphaned. The bound is measured
        // from reservedAt (not updatedAt), so unrelated reservation writes cannot
        // renew the shield indefinitely and ancient reservation-only orphans still
        // converge through the existing process_lost path.
        const reservation = reservationsByRunId.get(run.id);
        const reservationReservedAt = reservation
          ? new Date(reservation.reservedAt).getTime()
          : 0;
        const activePrelaunchReservation = Boolean(
          reservation
          && (reservation.state === "reserved" || reservation.state === "launching")
          && reservation.jobName === null
          && reservation.jobUid === null
          && Number.isFinite(reservationReservedAt)
          && reservationReservedAt > 0
          && now.getTime() - reservationReservedAt < EXTERNAL_LIFECYCLE_STALE_MS,
        );
        if (activePrelaunchReservation) {
          continue;
        }
        // BLO-13176: past the grace, DO NOT blindly declare the run orphaned.
        // Workspace provisioning (image pull, repo clone, opencode/claude cold
        // boot) can exceed 5 min while the k8s Job is perfectly alive and simply
        // has not emitted adapter.invoke yet. The old code fell straight through
        // to the `process_lost` finalize here, force-killing live `2/2 Running`
        // pods — the fleet-wide "Process lost before external adapter invocation"
        // seen 2026-07-02 (BLO-12825 run 6d4843b2 reaped at ~5 min with a live
        // pod, which starved a critical issue for days). Only POSITIVE evidence
        // of a live Job protects the run; "dead"/"unknown" keep the pre-existing
        // fall-through so genuinely-orphaned pre-adapter runs and the
        // kube-unavailable degraded path still reap exactly as before. This
        // mirrors the 2026-05-23 guard that already protects live-but-quiet
        // STARTED runs below.
        const preAdapterLiveness = await resolveExternalLifecycleJobLiveness(
          run,
          jobRunStatuses,
          liveJobRunIds,
        );
        preAdapterJobLiveness = preAdapterLiveness;
        if (preAdapterLiveness === "alive") {
          // Job is alive: leave a still-provisioning run alone. The one
          // exception is a run wedged pre-adapter past the hard ceiling (45 min)
          // — no longer "slow setup" but a stuck Job holding the agent's only
          // dispatch slot. Force-kill it (same treatment as a hard-stale STARTED
          // run) so newly-queued work can dispatch.
          const preAdapterRefTime = externalLifecycleRecentRefTime(run);
          const preAdapterHardStale =
            !preAdapterRefTime ||
            now.getTime() - preAdapterRefTime >= EXTERNAL_LIFECYCLE_HARD_STALE_MS;
          if (preAdapterHardStale) {
            const finalized = await finalizeExternalLifecycleTerminalRun({
              run,
              adapterType,
              adapterConfig,
              jobStatus: null,
              now,
              staleKill: true,
            });
            if (finalized) {
              reaped.push(run.id);
              continue;
            }
          }
          continue;
        }
        // Unknown kube state is protected only by the bounded cold-boot grace
        // below. Once that expires, an old pre-adapter run must converge.
      }
      let confirmedMissingExternalJob = false;
      if (externalLifecycleRun && externalLifecycleStarted) {
        const persistedSignalRef = run.lastUsefulActionAt
          ? new Date(run.lastUsefulActionAt).getTime()
          : run.lastOutputAt
          ? new Date(run.lastOutputAt).getTime()
          : run.startedAt
          ? new Date(run.startedAt).getTime()
          : 0;
        const lastSignalRef = Math.max(
          persistedSignalRef,
          externalRunReattachedAt.get(run.id) ?? 0,
        );
        const isSilent = !lastSignalRef || now.getTime() - lastSignalRef >= EXTERNAL_LIFECYCLE_STALE_MS;
        // BLO-12996: a much longer floor that gates the *destructive* kill of a
        // still-active Job (vs. isSilent, which only gates non-destructive
        // reaping of absent/terminal Jobs and slot-gate counting).
        const isHardStale =
          !lastSignalRef || now.getTime() - lastSignalRef >= EXTERNAL_LIFECYCLE_HARD_STALE_MS;

        if (jobRunStatuses !== null) {
          let jobStatus = jobRunStatuses.get(run.id) ?? null;
          const persistedJobName = run.externalRunId?.trim() || null;
          if (!jobStatus && persistedJobName) {
            const exactJobStatus = await readAgentJobRunStatusByName(persistedJobName);
            if (exactJobStatus?.phase === "missing") {
              confirmedMissingExternalJob = true;
            } else if (exactJobStatus) {
              jobStatus = exactJobStatus;
            }
          }

          if (jobStatus && jobStatus.phase !== "active") {
            // A terminal Job is usually authoritative, but the owning adapter
            // still needs a short window to parse final output, classify a
            // provider throttle, and launch an in-run replacement. The Ally
            // canaries exposed the reaper finalizing BackoffLimitExceeded while
            // executeRun was deliberately sleeping between those attempts.
            // The cleared reservation identity is durable proof that the owner
            // consumed this terminal attempt and is preparing its replacement.
            // Normal terminal Jobs remain immediately authoritative.
            if (replacementPendingRunIds.has(run.id)) {
              logger.debug(
                { runId: run.id, jobName: jobStatus.name ?? persistedJobName, jobPhase: jobStatus.phase },
                "reapOrphanedRuns: deferring terminal external Job to active adapter owner",
              );
              continue;
            }
            const finalized = await finalizeExternalLifecycleTerminalRun({
              run,
              adapterType,
              adapterConfig,
              jobStatus,
              now,
            });
            if (finalized) {
              reaped.push(run.id);
              continue;
            }
          }

          if (!jobStatus) {
            // A named Job can legitimately disappear in the final moments of an
            // external-lifecycle run: TTL/controller cleanup may win the race
            // while the adapter is still parsing final output and running
            // postRun hooks. Preserve the silence floor only while this worker
            // still owns the adapter invocation, or when the exact-name lookup
            // could not positively confirm deletion. After a worker restart,
            // activeRunExecutions is empty for a vanished Job and there is no
            // adapter left that can persist the terminal result; waiting for the
            // generic silence floor would unnecessarily hold the agent slot.
            if (
              !isSilent
              && (
                activeRunExecutions.has(run.id)
                || !confirmedMissingExternalJob
              )
            ) continue;
            const finalized = await finalizeExternalLifecycleTerminalRun({
              run,
              adapterType,
              adapterConfig,
              jobStatus: null,
              now,
            });
            if (finalized) {
              reaped.push(run.id);
              continue;
            }
          }

          // BLO-12996: the Job is present and still phase:active, but the run
          // has emitted no useful action past EXTERNAL_LIFECYCLE_HARD_STALE_MS.
          // The 2026-05-23 guard (below) rightly refuses to kill a live-but-
          // quiet Job at the 15-min soft floor, but a run silent for 45+ min is
          // a stuck zombie that blocks all dispatch for this agent (the
          // hasActiveJobForAgent gate in startNextQueuedRunForAgent). Force-kill
          // it so newly-queued high-priority work can dispatch.
          if (jobStatus && jobStatus.phase === "active" && isHardStale) {
            const finalized = await finalizeExternalLifecycleTerminalRun({
              run,
              adapterType,
              adapterConfig,
              jobStatus,
              now,
              staleKill: true,
            });
            if (finalized) {
              reaped.push(run.id);
              continue;
            }
          }

          continue;
        } else if (liveJobRunIds !== null) {
          // Job-alive is the strongest liveness signal we have for external
          // adapters. Do not kill a live-but-quiet agent just because stdout is
          // stale; only use the silence floor when the Job is absent or kube
          // status is unavailable.
          //
          // kube API path. Two sub-cases:
          //   - Job IS in our snapshot: the execution pod is alive; skip.
          //   - Job is NOT in our snapshot: previously we reaped
          //     immediately, but the snapshot can be a false negative
          //     (kube API list timeout returning a partial set, eventual
          //     consistency, in-flight Job not yet visible). RCA
          //     2026-05-23: this produced ~6.5/hr fleet-wide false
          //     `process_lost` events on live agents that were still
          //     streaming output. We now require the same silence floor
          //     in this branch — genuine "Job deleted by helm/operator"
          //     cases still get reaped after EXTERNAL_LIFECYCLE_STALE_MS
          //     of silence, but a healthy long-running agent whose Job
          //     just didn't make this snapshot is no longer killed.
          if (liveJobRunIds.has(run.id)) {
            // BLO-12996: Job is alive in the snapshot but the run has been
            // silent past the hard ceiling — force-kill to free the slot.
            // Below the hard floor we still honor the 2026-05-23 guard and
            // leave a live-but-quiet Job alone.
            if (isHardStale) {
              const finalized = await finalizeExternalLifecycleTerminalRun({
                run,
                adapterType,
                adapterConfig,
                jobStatus: null,
                now,
                staleKill: true,
              });
              if (finalized) {
                reaped.push(run.id);
                continue;
              }
            }
            continue;
          } else {
            if (!isSilent) continue;
          }
        } else {
          // Fallback: kube API unavailable (local dev or transient
          // failure). Same silence floor as the kube-up path.
          if (!isSilent) continue;
        }
      }

      // Apply staleness threshold to avoid false positives. For
      // external-lifecycle runs, key on genuine activity rather than updatedAt:
      // review/recovery churn bumps updatedAt every ~minute and would otherwise
      // shield a dead run from this gate forever (BLO-8827). Local adapters keep
      // updatedAt — their liveness is tracked via process pid/group, not Jobs.
      if (staleThresholdMs > 0 && !confirmedMissingExternalJob) {
        const refTime = externalLifecycleRun
          ? externalLifecycleRecentRefTime(run)
          : run.updatedAt
            ? new Date(run.updatedAt).getTime()
            : 0;
        if (now.getTime() - refTime < staleThresholdMs) continue;
      }

      const tracksLocalChild = isTrackedLocalChildProcessAdapter(adapterType);
      const processPidAlive = tracksLocalChild && run.processPid && isProcessAlive(run.processPid);
      const processGroupAlive = tracksLocalChild && run.processGroupId && isProcessGroupAlive(run.processGroupId);
      if (
        (processPidAlive || processGroupAlive) &&
        readHotRestartAdoptionMetadata(parseObject(run.resultJson))
      ) {
        continue;
      }
      if (processPidAlive) {
        if (run.errorCode !== DETACHED_PROCESS_ERROR_CODE) {
          const detachedMessage = `Lost in-memory process handle, but child pid ${run.processPid} is still alive`;
          const detachedRun = await setRunStatus(run.id, "running", {
            error: detachedMessage,
            errorCode: DETACHED_PROCESS_ERROR_CODE,
          });
          if (detachedRun) {
            await appendRunEvent(detachedRun, await nextRunEventSeq(detachedRun.id), {
              eventType: "lifecycle",
              stream: "system",
              level: "warn",
              message: detachedMessage,
              payload: {
                processPid: run.processPid,
              },
            });
          }
        }
        continue;
      }

      let descendantOnlyCleanup = false;
      if (processGroupAlive) {
        descendantOnlyCleanup = true;
        await terminateHeartbeatRunProcess({
          pid: run.processPid,
          processGroupId: run.processGroupId,
        });
      }

      // BLO-12563: if this pod is shutting down (stopDispatch() set dispatchStopped),
      // do NOT mint process_lost for a mid-setup external-lifecycle run — the setup
      // drain is making it adoptable and the next pod will re-adopt or reap it. This
      // fences the reap side of the shutdown quiesce: clearInterval() cannot cancel a
      // reaper tick that is already executing, so guard the finalize itself.
      if (dispatchStopped && externalLifecyclePreAdapter) {
        continue;
      }

      const runContext = parseObject(run.contextSnapshot);
      const monitorIssueId = readNonEmptyString(runContext.issueId);
      const monitorNextCheckAt = monitorIssueId
        ? monitorNextCheckAtByIssue.get(`${run.companyId}:${monitorIssueId}`)
        : undefined;
      const monitorDispatchLostWithoutFutureWake =
        readNonEmptyString(runContext.wakeReason) === "issue_monitor_due" &&
        monitorNextCheckAt !== undefined &&
        (!monitorNextCheckAt || monitorNextCheckAt.getTime() <= now.getTime());
      const unmanagedBackgroundTaskEvidence = descendantOnlyCleanup
        ? {
          kind: "orphaned_process_group_cleanup",
          stopped: true,
          stopReason: UNMANAGED_BACKGROUND_TASK_STOP_REASON,
          reason: UNMANAGED_BACKGROUND_TASK_LIVENESS_REASON,
          processPid: run.processPid ?? null,
          processGroupId: run.processGroupId ?? null,
        }
        : null;

      // BLO-12564: symmetric boot-side guard to the BLO-12563 shutdown guard
      // above. On a fresh worker boot the kube client may not be serving yet, so
      // the startup reap and first periodic ticks can run fully kube-blind
      // (liveJobRunIds === null — the same signal that drove
      // recordProcessLostLivenessNull() above). A running external-lifecycle Job
      // survives the worker restart (it is owned by its own k8s controller), so
      // minting process_lost while blind would zero a run whose Job is very
      // likely still Running. Within the cold-boot grace, hold the reap: leave
      // the run running so the next warm tick resolves "alive" (reattach via the
      // continue-paths above) or "dead" (reap). Past the grace a persistent kube
      // outage still reaps after the silence floor — no permanent shield, no
      // regression to the legitimate-lost path. Covers both pre-adapter and
      // started external runs (both reach this mint when blind). Gated on the
      // injected grace (default 0) so only the long-lived worker opts in.
      if (
        externalLifecycleRun &&
        liveJobRunIds === null &&
        coldBootReattachGraceMs > 0 &&
        now.getTime() - workerBootAt.getTime() < coldBootReattachGraceMs
      ) {
        logger.info(
          {
            runId: run.id,
            adapterType,
            msSinceWorkerBoot: now.getTime() - workerBootAt.getTime(),
            coldBootReattachGraceMs,
          },
          "reapOrphanedRuns: holding process_lost during cold-boot kube-blind grace so a live Job can reattach (BLO-12564)",
        );
        continue;
      }

      const contextSnapshot = parseObject(run.contextSnapshot);
      const prReviewRetry = isPrReviewRetryContext(contextSnapshot);
      const shouldRetry =
        (
          tracksLocalChild &&
          (!!run.processPid || !!run.processGroupId) &&
          (run.processLossRetryCount ?? 0) < 1 &&
          prReviewRetry
        ) ||
        (externalLifecyclePreAdapter && (run.processLossRetryCount ?? 0) < 1 && prReviewRetry) ||
        ((run.processLossRetryCount ?? 0) < 1 && monitorDispatchLostWithoutFutureWake);
      const baseMessage = externalLifecyclePreAdapter
        ? "Process lost before external adapter invocation -- k8s job terminated or server restarted"
        : buildProcessLossMessage(run, descendantOnlyCleanup ? { descendantOnly: true } : undefined);

      // BLO-16181: durably record what the reap loop already knows about the
      // backing k8s Job at process_lost mint time -- whether a Job name was ever
      // stamped, whether we were pre- or post-adapter, and the resolved Job
      // liveness -- so the fleet-wide process_lost split (BLO-12292) and reattach
      // feasibility (BLO-12564) can be measured without re-deriving it. No extra
      // kube round-trip: every signal below is already in hand here. (A confirmed
      // exact-name 404 never lands here -- that path finalizes as job_missing.)
      const processLossCapture = buildProcessLossCapture({
        externalLifecycleRun,
        preAdapter: externalLifecyclePreAdapter,
        externalRunId: run.externalRunId,
        preAdapterJobLiveness,
      });
      // BLO-16184: numerator of the process_lost trigger monitor, emitted below
      // once the mint is committed (so a failed/aborted setRunStatus never
      // over-counts). Split by adapter + error-string bucket + the durable
      // classification, all bounded.
      const finalizedRunWrite = await setRunStatusIfRunning(run.id, "failed", {
        error: shouldRetry ? `${baseMessage}; retrying once` : baseMessage,
        errorCode: "process_lost",
        finishedAt: now,
        resultJson: (() => {
          const result = mergeRunStopMetadataForAgent(
            { adapterType, adapterConfig },
            "failed",
            {
              resultJson: { ...parseObject(run.resultJson), processLoss: processLossCapture },
              errorCode: "process_lost",
              errorMessage: shouldRetry ? `${baseMessage}; retrying once` : baseMessage,
            },
          );
          return unmanagedBackgroundTaskEvidence
            ? {
              ...result,
              stopReason: UNMANAGED_BACKGROUND_TASK_STOP_REASON,
              unmanagedBackgroundTask: unmanagedBackgroundTaskEvidence,
            }
            : result;
        })(),
      });
      if (!finalizedRunWrite.updated || !finalizedRunWrite.run) {
        // Another reap invocation won the terminal transition for this run.
        // Do not duplicate process_lost metrics, retries, wakeup finalization,
        // run events, or issue-promotion side effects.
        if (finalizedRunWrite.run?.status !== "running") {
          runningProcesses.delete(run.id);
          activeRunExecutions.delete(run.id);
        }
        continue;
      }
      let finalizedRun = finalizedRunWrite.run;
      await setWakeupStatus(run.wakeupRequestId, "failed", {
        finishedAt: now,
        error: shouldRetry ? `${baseMessage}; retrying once` : baseMessage,
      });
      // BLO-16184: the process_lost mint is now committed for this run -- count it
      // (bounded adapter + error-string bucket + durable classification).
      recordProcessLost({
        adapter: adapterType,
        errorString: baseMessage,
        classification: processLossCapture.classification,
      });
      finalizedRun = await classifyAndPersistRunLiveness(finalizedRun, parseObject(finalizedRun.resultJson)) ?? finalizedRun;
      // PCL-2571: cancel any open stale_active_run_evaluation review for
      // this run now that the silence is explained by process_lost. The
      // detector and the reaper race on the suspicion threshold (~1h);
      // without this cleanup, reviews accreted indefinitely on the CTO
      // inbox (11 stuck reviews in 5 days observed 2026-05-25).
      try {
        await recovery.dismissStaleEvaluationOnRunTerminated({
          companyId: finalizedRun.companyId,
          runId: finalizedRun.id,
          agentId: finalizedRun.agentId,
          terminalStatus: "failed",
          errorCode: "process_lost",
          errorMessage: shouldRetry ? `${baseMessage}; retrying once` : baseMessage,
        });
      } catch (err) {
        logger.warn(
          { err, runId: finalizedRun.id, companyId: finalizedRun.companyId },
          "failed to dismiss stale active run evaluation during process_lost cleanup",
        );
      }
      await releaseEnvironmentLeasesForRun({
        runId: finalizedRun.id,
        companyId: finalizedRun.companyId,
        agentId: finalizedRun.agentId,
        status: finalizedRun.status,
        failureReason: finalizedRun.error ?? undefined,
      });
      // BLO-19085: `baseMessage` is the process_lost diagnosis already written
      // to the run record; pass it through so the agent record carries it too
      // instead of latching into `error` with a null reason.
      await finalizeAgentStatus(run.agentId, "failed", baseMessage, {
        errorCode: "process_lost",
        runId: run.id,
      });

      let retriedRun: typeof heartbeatRuns.$inferSelect | null = null;
      let promotedRunDispatched = false;
      const retryAgent = await getAgent(run.agentId);
      if (shouldRetry) {
        if (retryAgent) {
          retriedRun = await enqueueProcessLossRetry(finalizedRun, retryAgent, now);
        }
      } else if (retryAgent) {
        const scheduled = await scheduleInteractionContinuationInfrastructureRetryIfEligible(finalizedRun, retryAgent);
        retriedRun = scheduled?.outcome === "scheduled" ? scheduled.run : null;
      }

      if (!retriedRun) {
        promotedRunDispatched = await releaseIssueExecutionAndPromote(finalizedRun);
      }
      if (!opts?.suppressDispatchAfterReap && !promotedRunDispatched) {
        await startNextQueuedRunForAgent(run.agentId);
      }

      await appendRunEvent(finalizedRun, await nextRunEventSeq(finalizedRun.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "error",
        message: shouldRetry
          ? `${baseMessage}; queued retry ${retriedRun?.id ?? ""}`.trim()
          : baseMessage,
        payload: {
          ...(run.processPid ? { processPid: run.processPid } : {}),
          ...(run.processGroupId ? { processGroupId: run.processGroupId } : {}),
          ...(descendantOnlyCleanup ? { descendantOnlyCleanup: true } : {}),
          ...(externalLifecyclePreAdapter ? { externalLifecyclePreAdapter: true } : {}),
          ...(retriedRun ? { retryRunId: retriedRun.id } : {}),
        },
      });

      runningProcesses.delete(run.id);
      // For external-lifecycle adapters, also clear the in-process await
      // tracking. If we just reaped a run that the local executor was still
      // awaiting (because the kube Job vanished without notifying us), the
      // dispatch slot stays held until pod restart unless we clean this up.
      activeRunExecutions.delete(run.id);
      // Release any active environment leases the orphaned run held so the
      // environment isn't permanently checked out (ported from upstream
      // v513). Marks lease as `failed` rather than `released` to preserve
      // forensic signal for stuck-lease audits.
      await environmentsSvc.releaseLeasesForRun(run.id, "failed");
      reaped.push(run.id);

    }

    if (reaped.length > 0) {
      logger.warn({ reapedCount: reaped.length, runIds: reaped }, "reaped orphaned heartbeat runs");
    }
    return { reaped: reaped.length, runIds: reaped };
  }

  async function resumeQueuedRuns() {
    if ((await getSchedulingSuppression()).suppressed) return;
    const cutoff = await getWorktreeExecutionCutoff();

    const queuedRuns = await db
      .select({ agentId: heartbeatRuns.agentId })
      .from(heartbeatRuns)
      .innerJoin(companies, eq(companies.id, heartbeatRuns.companyId))
      .where(and(
        eq(heartbeatRuns.status, "queued"),
        eq(companies.status, "active"),
        cutoff ? gte(heartbeatRuns.createdAt, cutoff) : undefined,
      ));

    const agentIds = [...new Set(queuedRuns.map((r) => r.agentId))];
    for (const agentId of agentIds) {
      await startNextQueuedRunForAgent(agentId);
    }
  }

  async function reconcileStrandedAssignedIssues() {
    return recovery.reconcileStrandedAssignedIssues({ issueCreatedAtGte: await getWorktreeExecutionCutoff() });
  }

  async function sweepStaleIssueLocks() {
    const pendingStageExitCancellations = await db
      .select({ id: heartbeatRuns.id })
      .from(heartbeatRuns)
      .where(and(
        eq(heartbeatRuns.status, "running"),
        sql`${heartbeatRuns.resultJson} ->> 'pipelineStageExitCancellationRequestedAt' is not null`,
      ));
    for (const run of pendingStageExitCancellations) {
      await cancelRunInternal(
        run.id,
        "Cancelled because the pipeline case left the automation issue's originating stage",
        {
          errorCode: "pipeline_stage_exited",
          eventMessage: "run cancelled after pipeline stage exit",
        },
      ).catch((error) => {
        logger.warn({ err: error, runId: run.id }, "failed to reconcile pending pipeline stage-exit cancellation");
      });
    }
    return recovery.sweepStaleIssueLocks();
  }

  function issueIdFromRunContext(contextSnapshot: unknown) {
    const context = parseObject(contextSnapshot);
    return readNonEmptyString(context.issueId) ?? readNonEmptyString(context.taskId);
  }

  function isQueuedMaintenanceWake(run: typeof heartbeatRuns.$inferSelect) {
    const context = parseObject(run.contextSnapshot);
    const wakeReason = readNonEmptyString(context.wakeReason);
    return (
      run.status === "queued" &&
      !issueIdFromRunContext(context) &&
      Boolean(wakeReason && STALE_QUEUED_MAINTENANCE_WAKE_REASONS.includes(
        wakeReason as (typeof STALE_QUEUED_MAINTENANCE_WAKE_REASONS)[number],
      ))
    );
  }

  async function cancelStaleQueuedMaintenanceRun(run: typeof heartbeatRuns.$inferSelect, now: Date) {
    const context = parseObject(run.contextSnapshot);
    const wakeReason = readNonEmptyString(context.wakeReason);
    const reason = "Cancelled stale non-issue maintenance wake backlog; the current or next timer wake represents latest state";
    // BLO-20396: CAS on status='queued'. The SELECT that produced `run` is not
    // carried into the write, so without this gate a concurrent dispatch that
    // already claimed the row to `running` would be silently stomped back to
    // `cancelled` — and counted as pruned.
    const outcome = await setRunStatusIfQueued(run.id, "cancelled", {
      finishedAt: now,
      error: reason,
      errorCode: "stale_maintenance_wake_backlog",
      resultJson: {
        ...parseObject(run.resultJson),
        stopReason: "stale_maintenance_wake_backlog",
        wakeReason,
        maintenanceCleanupAt: now.toISOString(),
      },
    });
    if (!outcome.updated) return null;
    const cancelled = outcome.run;
    await setWakeupStatus(run.wakeupRequestId, "cancelled", {
      finishedAt: now,
      error: reason,
    });
    if (cancelled) {
      await appendRunEvent(cancelled, await nextRunEventSeq(cancelled.id), {
        eventType: "lifecycle",
        stream: "system",
        level: "warn",
        message: "stale queued maintenance wake cancelled",
        payload: {
          wakeReason,
          staleAgeMs: now.getTime() - new Date(run.updatedAt ?? run.createdAt).getTime(),
        },
      });
    }
    return cancelled;
  }

  async function pruneStaleQueuedMaintenanceRunsForAgent(agentId: string, now = new Date()) {
    const staleCutoff = new Date(now.getTime() - STALE_QUEUED_MAINTENANCE_WAKE_MAX_AGE_MS);
    const staleRuns = await db
      .select()
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.agentId, agentId),
          eq(heartbeatRuns.status, "queued"),
          lt(heartbeatRuns.updatedAt, staleCutoff),
          sql`not (${heartbeatRuns.contextSnapshot} ? 'issueId')`,
          sql`not (${heartbeatRuns.contextSnapshot} ? 'taskId')`,
          inArray(
            sql<string>`${heartbeatRuns.contextSnapshot} ->> 'wakeReason'`,
            [...STALE_QUEUED_MAINTENANCE_WAKE_REASONS],
          ),
        ),
      )
      .orderBy(asc(heartbeatRuns.updatedAt), asc(heartbeatRuns.createdAt), asc(heartbeatRuns.id))
      .limit(STALE_QUEUED_MAINTENANCE_WAKE_BATCH_SIZE);

    let cancelledCount = 0;
    for (const run of staleRuns) {
      if (!isQueuedMaintenanceWake(run)) continue;
      const cancelled = await cancelStaleQueuedMaintenanceRun(run, now);
      if (cancelled) cancelledCount += 1;
    }
    if (cancelledCount > 0) {
      logger.info(
        { agentId, cancelledCount, maxAgeMs: STALE_QUEUED_MAINTENANCE_WAKE_MAX_AGE_MS },
        "pruned stale queued maintenance heartbeat runs",
      );
    }
    return cancelledCount;
  }

  function issueIdFromWakePayload(payload: unknown) {
    const parsed = parseObject(payload);
    const nestedContext = parseObject(parsed[DEFERRED_WAKE_CONTEXT_KEY]);
    return readNonEmptyString(parsed.issueId) ??
      readNonEmptyString(nestedContext.issueId) ??
      readNonEmptyString(nestedContext.taskId);
  }

